-- 003_seed_real_laws.sql — بذر بيانات حقيقية: قانون العمل 14/2025 وقانون
-- التأمين الموحد 155/2024 (EP-05، 2026-08-21)
--
-- المصدر: نص الجريدة الرسمية الرسمي (رفعه رجل الأعمال مباشرة كملفات PDF
-- أصلية — العدد 18 تابع، 3 مايو 2025 لقانون العمل؛ العدد 27 مكرر (ج)،
-- 10 يوليو 2024 لقانون التأمين الموحد). استُخرج نص المواد آلياً بالكامل
-- (pdftotext + تطبيع NFKC لإصلاح أشكال العرض العربية المعزولة + إزالة
-- التطويل الزخرفى) دون أي إعادة صياغة أو تدخل بشري فى المحتوى — انظر
-- /home/claude/law-ingestion/parse.py لمنطق الاستخراج الكامل. تحقّق آلي:
-- 298 مادة متتالية بلا تكرار أو فجوة لقانون 14/2025، 224 مادة لقانون
-- 155/2024 (راجع سجل جلسة 2026-08-21).
--
-- حادثة دقة حرجة مرتبطة: قانون العمل رقم 12 لسنة 2003 (القانون الوحيد
-- المُحمَّل سابقاً بحالة in_force) أصبح ملغياً فعلياً بقانون 14/2025 اعتباراً
-- من 2025-09-01 — هذا الملف يصحح حالته إلى repealed كجزء من نفس البذر،
-- لمنع استمرار المنصة فى الإفتاء بقانون ملغٍ.
--
-- 'insurance' فئة جديدة تُضاف صراحة إلى قيد laws.category (لم تكن ضمن
-- الفئات الخمس الأصلية) لأن قانون 155/2024 تأمينى بحت ولا يقع تحت أي
-- من labor/rent/personal_status/traffic/consumer_protection.
--
-- ملاحظة نطاق معروفة: عمود articles.embedding يبقى NULL لهذه المواد بعد
-- هذا الملف مباشرة (الفهرسة الدلالية عبر Voyage AI تتم فقط ضمن مسار
-- IngestionService.importLaws() فى TypeScript، غير متاح لملف SQL خام) —
-- الاسترجاع النصي الكامل (FTS، المسار الأساسي فى questions.service.ts)
-- يعمل فوراً بلا أي أثر لهذه الفجوة؛ الفهرسة الدلالية تحتاج إعادة تشغيل
-- لاحقة لخط استيراد الإدخال (متابعة منفصلة).
--
-- قابل لإعادة التشغيل بأمان (idempotent) — كل مادة تُدرج فقط إن لم تكن
-- موجودة أصلاً (ON CONFLICT DO NOTHING)، بنفس نمط بقية ملفات هذا المجلد.

BEGIN;

-- توسيع قيد الفئة ليشمل 'insurance'
ALTER TABLE laws DROP CONSTRAINT IF EXISTS laws_category_check;
ALTER TABLE laws ADD CONSTRAINT laws_category_check
  CHECK (category IN ('labor','rent','personal_status','traffic','consumer_protection','insurance','other'));

-- تصحيح حرج: قانون العمل 12/2003 ملغٍ فعلياً منذ 2025-09-01 بقانون 14/2025
UPDATE laws SET status = 'repealed', updated_at = now()
  WHERE law_no = 12 AND law_year = 2003 AND status <> 'repealed';

-- ===== law14: قانون العمل الصادر بالقانون رقم 14 لسنة 2025 (298 مادة) =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (14, 2025, $q1$قانون العمل الصادر بالقانون رقم 14 لسنة 2025$q1$, $q2$قانون العمل (2025)$q2$, 'labor', 'in_force', $q3$https://www.eastlaws.com/legislation-full-text/ar/egypt/law/03-05-2025/no-14?type=1&id=2165366&sub=11404110$q3$, '2025-05-03')
ON CONFLICT (law_no, law_year) DO NOTHING;

WITH ins_art_law14_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $q5$يقصد فى تطبيق أحكام هذا القانون بالكلمات والمصطلحات الآتية المعانى المبينة قرين كل منها:
-١ العامل:كل شخص طبيعى يعمل لقاء أجر لدى صاحب عمل تحت إدارته أو إشرافه.
-٢ المتدرج:كل من التحق لدى صاحب عمل بقصد تعلم مهنة أو صنعة أو حرفة لقاء أجر.
-٣ صاحب العمل:كل شخص طبيعى أو اعتبارى يستخدم عاملا ً أو أكثر لقاء أجر.
-٤ الأجر:كل ما يحصل عليه العامل لقاء عمله نقدا كان أو عين ًا، ويشمل الآتى: الأجر الأساسى:الأجر المنصوص عليه فى عقد العمل،وما يطرأ عليه من علاوات. الأجر المتغير:باقى ما يحصل عليه العامل من عناصر الأجر،وعلى الأخص: ) أ( العمولة أو النسبة المئوية:مبلغ من المال يدفع للعامل مقابل ما يقوم بإنتاجه،أو بيعه،أو تحصيله طوال قيامه بالعمل المقرر له هذه النسبة. )ب( العلاوات:مبلغ مالى أو نسبة من الأجر الأساسى ت ُمنح للعامل لمواجهة ظروف اقتصادية أو اجتماعية أو فنية ما لم تضم إلى الأجر الأساسى. )ج( المنح:ما يعطى للعامل زيادة على أجره،متى كانت مقررة فى عقود العمل الفردية،أو الجماعية،أو الأنظمة الأساسية للعمل،أو ما جرت العادة بمنحه.
)د( المكافأة:كل ما يصرف للعامل نقدا كان أو عين ًا نظير إجادة،أو تميز، أو كفاءة فى أداء العمل المكلف به. )ه( البدلات:ما يعطى للعامل لقاء ظروف أو مخاطر معينة،يتعرض لها فى أداء عمله. )و( نصيب العامل فى الأرباح:ما يصرف للعامل من صافى الأرباح المحققة وفق ًا للقوانين المنظمة لها. )ز( الوهبة:المقابل الذى يحصل عليه العامل من غير صاحب العمل إذا جرت العادة بدفعها،وكانت لها قواعد تسمح بتحديدها وفق ًا للائحة المنشأة أو العرف السائد. )ح( مقابل الخدمة:المقابل النقدى الذى قد يدفعه العملاء فى المنشآت السياحية والفندقية،وغيرها من المنشآت الأخرى،ويصدر قرار من الوزير المختص بالاتفاق مع الوزراء المعنيين والمنظمة النقابية المعنية ومنظمات أصحاب الأعمال بكيفية توزيعها على العاملين. )ط( المزايا العينية:ما يلتزم به صاحب العمل من مزايا غير نقدية لا تستلزمها مقتضيات العمل.
-٥ الأجر التأمينى:أجر الاشتراك الوارد بقانون التأمينات الاجتماعية والمعاشات الصادر بالقانون رقم ١٤٨لسنة ٢٠١٩
-٦ العمل المؤقت:العمل الذى يدخل بطبيعته فيما يزاوله صاحب العمل من نشاط وتقتضى طبيعة إنجازه مدة محددة،أو ينصب على عمل بذاته، وينتهى بانتهائه.
-٧ العمل العرضى:العمل الذى لا يدخل بطبيعته فيما يزاوله صاحب العمل من نشاط ولا يستغرق إنجازه أكثر من ستة أشهر.
-٨ العمل الموسمى:العمل الذى يتم فى مواسم دورية متعارف عليها.
-٩ العامل غير المنتظم:كل من يقوم بأداء عمل غير دائم بطبيعته مقابل أجر أيا كانت صورته،أو يعمل فى مهنة أو حرفة لا ينظمها قانون خاص،مثل الباعة الجائلين،وموزعى الصحف،وغيرهم.
-١٠ العامل فى القطاع غير الرسمى:كل من يقوم بأداء عمل داخل المنشأة أو خارجها بشكل غير رسمى أو مستتر. - ١١السخرة:كل عمل أو خدمة تفرض عنوة على أى شخص تحت التهديد بإنزال عقوبة أو إيذاء،ولم يتطوع هذا الشخص بأدائها بمحض اختياره.
-١٢ الليل:الفترة ما بين غروب الشمس وشروقها.
-١٣ التوجيه المهنى:مساعدة الفرد فى اختيار المهنة أو المسار المهنى الأكثر ملاءمة لقدراته واستعداده وميوله فى ضوء الدراسات المستمرة لسوق العمل والمهن المطلوبة ومقوماتها.
-١٤ التدريب:عملية ت ُمكن الفرد من اكتساب وتنمية المعارف والمهارات الفنية وسلوكيات المهنة اللازمة لإعداده للعمل المناسب.
-١٥ التلمذة الصناعية:شكل من أشكال التعلم أو تنمية المهارات داخل العمل أو خارجه،يمكن الفرد من اكتساب المهارات والمعارف والجدارات اللازمة للعمل فى مهنة أو صنعة أو حرفة من خلال تدريب منظم مقابل أجر.
-١٦ مجالس المهارات القطاعية:كيانات قطاعية تعزز التعاون بين الحكومة والقطاع الخاص تنشأ لضمان استيفاء منظومة التعليم الفنى والتقنى والتدريب المهنى لاحتياجات القطاع الاقتصادى من العمالة الفنية الماهرة.
-١٧ وكالات التشغيل الخاصة:شركات متخصصة فى اختيار العمال، أو تشغيلهم لدى الغير بالشروط التى أوجبها هذا القانون.
-١٨ الوكلاء المفوضون:كل شخص أنابه أو فوضه صاحب العمل فى إدارة المنشأة،أو شاغلو الوظائف الرئيسية العليا بها الذين يمارسون بعض أو كل سلطات صاحب العمل.
-١٩ المفاوضة الجماعية:الحوار الذى يجرى بين صاحب عمل أو منظمة أصحاب أعمال أو أكثر من جهة،وبين منظمة نقابية عمالية،أو أكثر من جهة أخرى بغرض التوافق لتحقيق مصالح الطرفين.
-٢٠ المنازعة الجماعية:كل نزاع ينشأ بين صاحب عمل أو مجموعة أصحاب أعمال أو منظماتهم،وبين جميع عمال المنشأة أو فريق منهم أو منظماتهم النقابية المعنية بشأن شروط العمل أو ظروفه أو التشغيل.
-٢١ الشركاء الاجتماعيون:أطراف العملية الإنتاجية )الحكومة،ومنظمات أصحاب الأعمال،والمنظمات النقابية العمالية(.
-٢٢ المفوض العمالى:أحد العاملين بالمنشأة يتفق العاملون بها على تفويضه بموجب سند رسمى لتمثيلهم أمام صاحب العمل فى حالة عدم وجود منظمة نقابية عمالية بها.
-٢٣ اتفاقية العمل الجماعية:اتفاق مكتوب ينظم شروط وظروف العمل وأحكام التشغيل،ويبرم بين منظمة أو أكثر من المنظمات النقابية العمالية وبين صاحب عمل أو مجموعة من أصحاب الأعمال أو منظمة أو أكثر من منظماتهم.
-٢٤ التوفيق:وسيلة يلجأ إليها أحد طرفى منازعة العمل الجماعية طالبا تدخل الجهة الإدارية المختصة بعد تعثر المفاوضة الجماعية بينهما.
-٢٥ الوساطة:وسيلة ودية لفض منازعات العمل الجماعية،يتفق بموجبها طرفا النزاع على إسناد مهمة اقتراح التسوية إلى شخص ثالث حيادى يدعى )وسيط النزاع(،يشتركان فى اختياره من القائمة المعدة لذلك.
-٢٦ التحكيم:وسيلة اتفاقية لإنهاء النزاع الجماعى القائم بعد فشل وسائل التسوية الودية ويتولى القيام به محكم أو أكثر يتم اختيارهم من القائمة المعدة لذلك.
-٢٧ شرط التحكيم:اتفاق مكتوب بين طرفى علاقة العمل على تسوية ما قد ينشأ بينهما من نزاع بشأن هذه العلاقة بواسطة التحكيم.
-۲۸ مشارطة التحكيم:اتفاق مكتوب بين طرفى علاقة العمل بعد نشوء النزاع.
-۲۹ الإضراب عن العمل:اتفاق جميع العمال أو فريق منهم على التوقف عن أداء أعمالهم بمقر العمل للمطالبة بما يرونه محقق ًا لمصالحهم المهنية والاقتصادية والاجتماعية،بعد تعذر التسوية الودية،فى حدود الضوابط والإجراءات المقررة قانون ًا.
-٣٠ إصابة العمل والأمراض المزمنة:التعريفات الواردة لها فى قانون التأمينات الاجتماعية والمعاشات الصادر بالقانون رقم ١٤٨لسنة ٢٠١٩
-٣١ التحرش:كل فعل أو سلوك فى مكان العمل أو بمناسبته يشكل تعرضا للغير بإتيان أمور أو إيحاءات أو تلميحات جنسية أو إباحية سواء بالإشارة أو بالقول أو بالفعل بأية وسيلة بما فى ذلك وسائل الاتصالات السلكية أو اللاسلكية أو الإلكترونية،أو أية وسيلة تقنية أخرى.
-٣٢ التنمر:كل فعل أو سلوك فى مكان العمل أو بمناسبته سواء بالقول أو باستعراض القوة أو السيطرة على الغير أو استغلال ضعفه أو لحالة يعتقد مرتكب ذلك الفعل أو السلوك أنها تسيء للغير كالجنس أو العرق أو الدين أو الأوصاف البدنية أو الحالة الصحية أو العقلية أو المستوى الاجتماعى بقصد تخويفه أو وضعه موضع السخرية أو الحط من شأنه أو إقصائه من محيطه الاجتماعى.بأية وسيلة بما فى ذلك وسائل الاتصالات السلكية واللاسلكية أو الإلكترونية،أو أية وسيلة تقنية أخرى.
-٣٣ المنشأة:كل مشروع أو مرفق يملكه أو يديره شخص من أشخاص القانون الخاص أيا كان نوعها أو تبعيتها،وذلك مع مراعاة ما نصت عليه المادة )(٢٤٣ من هذا القانون.
-٣٤ موقع العمل:هو المكان الذى يمارس فيه العامل العمل المكلف به، أو يحتمل تواجده فيه بسببه.
-٣٥ المهنة أو الحرفة:كل عمل يتطلب أداؤه مهارة خاصة أو خبرة محددة، ولا ينظم مزاولته قانون خاص.
-٣٦ الوزير المختص:الوزير المعنى بشئون العمل.
-۳۷ الوزارة المختصة:الوزارة المعنية بشئون العمل.
-۳۸ الجهة الإدارية المختصة:الوزارة المعنية بشئون العمل ومديرياتها وإداراتها التابعة لها على مستوى الجمهورية.$q5$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
