)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q19$يكون للمبالغ المستحقة للعامل،أو المستحقين عنه،والناشئة عن علاقة عمل امتياز على جميع أموال المدين من منقول وعقار،وتستوفى هذه المبالغ قبل المصروفات القضائية،والمبالغ المستحقة للخزانة العامة،ومصروفات الحفظ والترميم وأية مرتبة امتياز مقررة أو تقرر وفق ًا لأى قانون آخر. وتعتبر اشتراكات التأمين الاجتماعى جزءا من حقوق العمال التى تستوفى وتؤدى للهيئة المختصة.$q19$, '2025-09-01', 'active' FROM ins_art_law14_8;

WITH ins_art_law14_9 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 9, $q20$الباب الثاني: الأحكام العامة$q20$, $q21$لا يمنع من الوفاء بجميع الالتزامات الناشئة طبق ًا لهذا القانون،حل المنشأة، أو تصفيتها،أو إغلاقها،أو إفلاسها. ويجب أن يحدد القرار أو الحكم الصادر بأى من ذلك،أجلا ً للوفاء بحقوق العاملين،وتتولى الجهة الإدارية المختصة متابعة الوفاء بتلك الحقوق،ويكون لها أن تنوب عن ذوى الشأن فى اتخاذ الإجراءات اللازمة للوفاء بها فى الأجل المحدد. ويصدر الوزير المختص قرارا بتحديد ضوابط وإجراءات ومواعيد الوفاء بحقوق العمال.$q21$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q21$لا يمنع من الوفاء بجميع الالتزامات الناشئة طبق ًا لهذا القانون،حل المنشأة، أو تصفيتها،أو إغلاقها،أو إفلاسها. ويجب أن يحدد القرار أو الحكم الصادر بأى من ذلك،أجلا ً للوفاء بحقوق العاملين،وتتولى الجهة الإدارية المختصة متابعة الوفاء بتلك الحقوق،ويكون لها أن تنوب عن ذوى الشأن فى اتخاذ الإجراءات اللازمة للوفاء بها فى الأجل المحدد. ويصدر الوزير المختص قرارا بتحديد ضوابط وإجراءات ومواعيد الوفاء بحقوق العمال.$q21$, '2025-09-01', 'active' FROM ins_art_law14_9;

