WITH ins_art_law14_16 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 16, $q34$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الأول: التدريب$q34$, $q35$تسرى أحكام هذا الباب على جميع مراكز التدريب الخاضعة لأحكام هذا القانون، وعلى الفئات الآتية:
-١ الراغبين فى التدريب.
-٢ الأشخاص ذوو الإعاقة والأقزام،والفئات الأولى بالرعاية.
-٣ المتدرجين.
