WITH ins_art_law14_21 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 21, $q44$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الأول: التدريب$q44$, $q45$تتكون موارد الصندوق المشار إليه فى المادة ۲۰من هذا القانون من:
-١ نسبة ) ٪٠,٢٥ربع فى المائة( من الحد الأدنى للأجر التأمينى بمنشآت القطاع العام،وقطاع الأعمال العام،والقطاع الخاص،والتى يعمل بها ثلاثون عاملا ً فأكثر،بحد أدنى عشرة جنيهات،وبحد أقصى ثلاثون جنيها عن كل عامل، تتحملها وتلتزم المنشأة بسدادها سنويا مقابل الخدمات المنصوص عليها فى المادة )(٢٠ من هذا القانون. ويحدد بقرار من الوزير المختص قواعد وشروط الإعفاء الكلى من النسبة المشار إليها،وذلك فى حالة قيام تلك المنشآت بتدريب العاملين لديها وفق ًا لمقتضياتها، أو اللوائح المعتمدة بتلك المنشآت.
-٢ الإعانات والتبرعات والهبات التى يقبلها مجلس إدارة الصندوق طبق ًا للقواعد التى تحددها لائحة النظام الأساسى وفق ًا للقوانين المعمول بها فى هذا الشأن.
-٣ عائد استثمار أموال الصندوق. ويكون للصندوق حساب خاص لدى أحد البنوك التجارية المعتمدة لدى البنك المركزى،ويعد الصندوق سنويا القوائم الدالة على المركز المالي،وتخضع أمواله لرقابة الجهاز المركزى للمحاسبات ويرحل فائض أمواله من سنة إلى أخرى.$q45$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
