-٣ عائد استثمار أموال الصندوق. ويكون للصندوق حساب خاص لدى أحد البنوك التجارية المعتمدة لدى البنك المركزى،ويعد الصندوق سنويا القوائم الدالة على المركز المالي،وتخضع أمواله لرقابة الجهاز المركزى للمحاسبات ويرحل فائض أمواله من سنة إلى أخرى.$q45$, '2025-09-01', 'active' FROM ins_art_law14_21;

WITH ins_art_law14_22 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 22, $q46$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الأول: التدريب$q46$, $q47$لا يجوز لأية جهة مزاولة عمليات التدريب،إلا إذا كانت متخذة شكل شركة من شركات المساهمة،أو التوصية بالأسهم،أو ذات المسئولية المحدودة أو الشخص الواحد. ويستثنى من أحكام الفقرة الأولى من هذه المادة: - ١منظمات أصحاب الأعمال والمنظمات النقابية العمالية،والجمعيات والمؤسسات الأهلية المنشأة وفق ًا للقانون المنظم لها،التى تزاول عمليات التدريب.
-٢ جهات التدريب التى تنشئها وحدات الجهاز الإدارى للدولة،والهيئات العامة، ووحدات الإدارة المحلية لتدريب موظفيها وموظفى الجهات ذات الصلة بها.
-٣ المنشآت التى تتولى تدريب عمالها.
-٤ الكيانات التى تزاول عمليات تأهيل وتدريب الأشخاص ذوى الإعاقة والأقزام،والفئات الأولى بالرعاية.$q47$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
