WITH ins_art_law14_35 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 35, $q72$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثانى: التشغيل$q72$, $q73$مع عدم الإخلال بأحكام قانون حقوق الأشخاص ذوى الإعاقة المشار إليه تلتزم المنشآت القائمة وقت تطبيق هذا القانون،وتلك التى تنشأ مستقبلا ً أن تعيد إلى الجهة الإدارية المختصة شهادة قيد العامل الصادرة عنها خلال خمسة وأربعين يوما من تاريخ استلام العمل بعد استيفاء البيانات المدونة بها،وعليها تدوين رقم شهادة القيد، وتاريخها أمام اسم العامل فى سجل قيد العمال بالمنشأة.$q73$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q73$مع عدم الإخلال بأحكام قانون حقوق الأشخاص ذوى الإعاقة المشار إليه تلتزم المنشآت القائمة وقت تطبيق هذا القانون،وتلك التى تنشأ مستقبلا ً أن تعيد إلى الجهة الإدارية المختصة شهادة قيد العامل الصادرة عنها خلال خمسة وأربعين يوما من تاريخ استلام العمل بعد استيفاء البيانات المدونة بها،وعليها تدوين رقم شهادة القيد، وتاريخها أمام اسم العامل فى سجل قيد العمال بالمنشأة.$q73$, '2025-09-01', 'active' FROM ins_art_law14_35;

WITH ins_art_law14_36 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 36, $q74$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثانى: التشغيل$q74$, $q75$تلتزم المنشآت الخاضعة لأحكام هذا القانون بأن ترسل إلى الجهة الإدارية المختصة خلال ثلاثين يوما من تاريخ بدء العمل بالمنشأة،بيان ًا مفصلا ً بعدد العمال طبق ًا لمؤهلاتهم،ومهنهم،وفئات أعمارهم،وجنسياتهم،ونوعهم،والأجور التى يتقاضونها. وعلى هذه المنشآت أن ترسل إلى تلك الجهة خلال شهر يناير من كل عام البيانات الآتية:
-١ ما طرأ من تعديلات على البيانات الواردة فى الفقرة الأولى من هذه المادة.
-٢ عدد الوظائف الشاغرة بسبب الإحلال أو التوسعات الجديدة،والوظائف التى تم إلغاؤها.
-٣ بيان بتقدير الاحتياجات المتوقعة حسب الحالة التعليمية والمهنية خلال العام التالي. وذلك كله وفق ًا للنماذج التى تعدها الوزارة المختصة. وعلى الجهة الإدارية المختصة موافاة الهيئة القومية للتأمين الاجتماعى بنسخة من البيانات المشار إليها بالفقرة الثانية من هذه المادة.$q75$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
