WITH ins_art_law14_42 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 42, $q86$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثانى: التشغيل$q86$, $q87$يصدر الوزير المختص قرارا يتضمن التزامات الشركات المرخص لها بالتشغيل والشروط الواجب توافرها فى مقر الشركة وإدارتها،وتنظيم إجراءات العمل فى هذا النشاط والسجلات اللازمة لمباشرة عملها والتى يتعين إمساكها،وقواعد القيد فيها، والرقابة والتفتيش عليها،والشروط الواجب توافرها فى الإعلانات التى تنشر عن فرص العمل.$q87$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q87$يصدر الوزير المختص قرارا يتضمن التزامات الشركات المرخص لها بالتشغيل والشروط الواجب توافرها فى مقر الشركة وإدارتها،وتنظيم إجراءات العمل فى هذا النشاط والسجلات اللازمة لمباشرة عملها والتى يتعين إمساكها،وقواعد القيد فيها، والرقابة والتفتيش عليها،والشروط الواجب توافرها فى الإعلانات التى تنشر عن فرص العمل.$q87$, '2025-09-01', 'active' FROM ins_art_law14_42;

WITH ins_art_law14_43 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 43, $q88$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثانى: التشغيل$q88$, $q89$يحظر على الجهات المشار إليها فى المادة ) (٤٠من هذا القانون تقاضى أى مبالغ مالية من العامل بطريقة مباشرة أو غير مباشرة نظير إلحاقه بالعمل،ولها أن تتقاضى مقابل ذلك من صاحب العمل. واستثناء من أحكام الفقرة الأولى من هذه المادة يجوز للشركات المشار إليها فى البند ) (٣من المادة ) (٤٠من هذا القانون أن تتقاضى مبلغ ًا لا يجاوز ) (٪١من أجر العامل الذى يتم إلحاقه بالعمل،وذلك عن السنة الأولى فقط كمصروفات إدارية، ويحظر تقاضى أى مبالغ أخرى من العامل تحت أى مسمى.$q89$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q89$يحظر على الجهات المشار إليها فى المادة ) (٤٠من هذا القانون تقاضى أى مبالغ مالية من العامل بطريقة مباشرة أو غير مباشرة نظير إلحاقه بالعمل،ولها أن تتقاضى مقابل ذلك من صاحب العمل. واستثناء من أحكام الفقرة الأولى من هذه المادة يجوز للشركات المشار إليها فى البند ) (٣من المادة ) (٤٠من هذا القانون أن تتقاضى مبلغ ًا لا يجاوز ) (٪١من أجر العامل الذى يتم إلحاقه بالعمل،وذلك عن السنة الأولى فقط كمصروفات إدارية، ويحظر تقاضى أى مبالغ أخرى من العامل تحت أى مسمى.$q89$, '2025-09-01', 'active' FROM ins_art_law14_43;

WITH ins_art_law14_44 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 44, $q90$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثانى: التشغيل$q90$, $q91$يلغى الترخيص المشار إليه بالبند ) (٣من المادة ) (٤٠من هذا القانون بقرار من الوزير المختص فى الحالات الآتية:
-١ فقد الشركة شرط ًا من شروط الترخيص.
-٢ حصول الشركة على الترخيص أو تجديده بناء على ما قدمته من بيانات غير صحيحة.
-٣ ثبوت ممارسة الشركة لنشاطها خارج المقر المرخص لها ممارسة النشاط فيه.
-٤ تشغيل العامل دون تحرير عقد عمل مكتوب،أو ما يقوم مقامه لدى بعض الدول،أو عدم اعتماد العقد من الجهة الإدارية المختصة.
-٥ عدم إمساك السجلات الخاصة بتسجيل بيانات العمالة أو تسجيل المبالغ التى يتم تحصيلها منهم،والتى يصدر بتحديدها قرار من الوزير المختص.
-٦ قيام الشركة بالإعلان عن وظائف غير حقيقية أو تجاوز الشركة حدود التعاقد مع أصحاب الأعمال.
-٧ تقاضى الشركة أى مبالغ من العامل نظير تشغيله بالمخالفة لأحكام هذا القانون. ويجوز للوزير المختص إيقاف نشاط الشركة مؤقت ًا فى أى من الحالات المبينة فى الفقرة الأولى من هذه المادة لحين الفصل فى مدى ثبوت تلك الحالات،أو زوال تلك المخالفات. ولا يخل إلغاء الترخيص فى أى من الحالات المبينة فى هذه المادة بالمسئولية الجنائية أو المدنية أو التأديبية.$q91$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
