WITH ins_art_law14_70 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 70, $q142$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثانى: التشغيل$q142$, $q143$يخضع عمل الأجانب فى جميع منشآت القطاع الخاص،ووحدات القطاع العام، وقطاع الأعمال العام،والهيئات العامة والإدارة المحلية،والجهاز الإدارى للدولة للأحكام الواردة فى هذا الفصل،وذلك مع مراعاة شرط المعاملة بالمثل. ويحدد الوزير المختص النسبة القصوى لتشغيل الأجانب فى تلك المنشآت والجهات،وحالات الاستثناء من تلك النسبة،والمهن والحرف التى يحظر على الأجانب الاشتغال بها. ويجوز للوزير المختص إعفاء الأجانب من شرط المعاملة بالمثل.$q143$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q143$يخضع عمل الأجانب فى جميع منشآت القطاع الخاص،ووحدات القطاع العام، وقطاع الأعمال العام،والهيئات العامة والإدارة المحلية،والجهاز الإدارى للدولة للأحكام الواردة فى هذا الفصل،وذلك مع مراعاة شرط المعاملة بالمثل. ويحدد الوزير المختص النسبة القصوى لتشغيل الأجانب فى تلك المنشآت والجهات،وحالات الاستثناء من تلك النسبة،والمهن والحرف التى يحظر على الأجانب الاشتغال بها. ويجوز للوزير المختص إعفاء الأجانب من شرط المعاملة بالمثل.$q143$, '2025-09-01', 'active' FROM ins_art_law14_70;

WITH ins_art_law14_71 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 71, $q144$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثانى: التشغيل$q144$, $q145$لا يجوز للأجنبى العمل داخل البلاد إلا بعد الحصول على ترخيص بذلك من الوزارة المختصة وأن يكون مصرحا له بدخول البلاد والإقامة بها بقصد العمل، ولا يجوز لأصحاب الأعمال تشغيل الأجانب إلا بعد الحصول على هذا الترخيص. ويصدر الوزير المختص قرارا بشروط الحصول على الترخيص المشار إليه، وإجراءاته،والبيانات التى يتضمنها،وإجراءات تجديده،والرسم الذى يحصل عنه ورسوم الإعفاء من شروط الاستقدام،بما لا يقل عن خمسة آلاف جنيه،ولا يزيد على مائة وخمسين ألف جنيه،ويحدد حالات إلغاء الترخيص قبل انتهاء مدته، وحالات إعفاء الأجانب من شرط الحصول عليه،وحالات الإعفاء من شرط الاستقدام وبما يتماشى مع احتياجات سوق العمل. ويلتزم كل من يستخدم أجنبيا أعفى من شرط الحصول على الترخيص بأن يخطر الجهة الإدارية المختصة بذلك خلال سبعة أيام من مزاولة الأجنبى للعمل،وعند انتهاء خدمته لديه.$q145$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q145$لا يجوز للأجنبى العمل داخل البلاد إلا بعد الحصول على ترخيص بذلك من الوزارة المختصة وأن يكون مصرحا له بدخول البلاد والإقامة بها بقصد العمل، ولا يجوز لأصحاب الأعمال تشغيل الأجانب إلا بعد الحصول على هذا الترخيص. ويصدر الوزير المختص قرارا بشروط الحصول على الترخيص المشار إليه، وإجراءاته،والبيانات التى يتضمنها،وإجراءات تجديده،والرسم الذى يحصل عنه ورسوم الإعفاء من شروط الاستقدام،بما لا يقل عن خمسة آلاف جنيه،ولا يزيد على مائة وخمسين ألف جنيه،ويحدد حالات إلغاء الترخيص قبل انتهاء مدته، وحالات إعفاء الأجانب من شرط الحصول عليه،وحالات الإعفاء من شرط الاستقدام وبما يتماشى مع احتياجات سوق العمل. ويلتزم كل من يستخدم أجنبيا أعفى من شرط الحصول على الترخيص بأن يخطر الجهة الإدارية المختصة بذلك خلال سبعة أيام من مزاولة الأجنبى للعمل،وعند انتهاء خدمته لديه.$q145$, '2025-09-01', 'active' FROM ins_art_law14_71;

WITH ins_art_law14_72 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 72, $q146$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثانى: التشغيل$q146$, $q147$يلتزم صاحب العمل بإبلاغ الجهة الإدارية والسلطات المختصة عن غياب العامل الأجنبى عن العمل لمدة خمسة عشر يوما متصلة دون مسوغ قانونى يجيز ذلك، ويصدر الوزير المختص قرارا بالضوابط والشروط والإجراءات المنظمة لذلك.$q147$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q147$يلتزم صاحب العمل بإبلاغ الجهة الإدارية والسلطات المختصة عن غياب العامل الأجنبى عن العمل لمدة خمسة عشر يوما متصلة دون مسوغ قانونى يجيز ذلك، ويصدر الوزير المختص قرارا بالضوابط والشروط والإجراءات المنظمة لذلك.$q147$, '2025-09-01', 'active' FROM ins_art_law14_72;

WITH ins_art_law14_73 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 73, $q148$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثانى: التشغيل$q148$, $q149$مع عدم الإخلال بأحكام قانون الاستثمار الصادر بالقانون رقم ٧٢لسنة، ٢٠١٧ يجوز للوزير المختص بالاتفاق مع الوزير المعنى بشئون الاستثمار،وضع القواعد والضوابط اللازمة للترخيص بالعمل للأجانب المخاطبين بأحكام قانون الاستثمار المشار إليه.$q149$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q149$مع عدم الإخلال بأحكام قانون الاستثمار الصادر بالقانون رقم ٧٢لسنة، ٢٠١٧ يجوز للوزير المختص بالاتفاق مع الوزير المعنى بشئون الاستثمار،وضع القواعد والضوابط اللازمة للترخيص بالعمل للأجانب المخاطبين بأحكام قانون الاستثمار المشار إليه.$q149$, '2025-09-01', 'active' FROM ins_art_law14_73;

WITH ins_art_law14_74 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 74, $q150$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثانى: التشغيل$q150$, $q151$يلتزم صاحب العمل الذى يعمل لديه الأجنبى بإعادته إلى الدولة التى تم استقدامه منها على نفقة صاحب العمل الخاصة حال انتهاء علاقة العمل،ما لم ينص عقد العمل على خلاف ذلك. ويصدر الوزير المختص قرارا بالحالات والمواعيد والإجراءات المنظمة لذلك.$q151$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q151$يلتزم صاحب العمل الذى يعمل لديه الأجنبى بإعادته إلى الدولة التى تم استقدامه منها على نفقة صاحب العمل الخاصة حال انتهاء علاقة العمل،ما لم ينص عقد العمل على خلاف ذلك. ويصدر الوزير المختص قرارا بالحالات والمواعيد والإجراءات المنظمة لذلك.$q151$, '2025-09-01', 'active' FROM ins_art_law14_74;

WITH ins_art_law14_75 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 75, $q152$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثالث: تشغيل العمالة غير المنتظمة$q152$, $q153$تهدف أحكام هذا الباب إلى تنظيم ودعم وتشغيل العمالة غير المنتظمة والعاملين فى القطاع غير الرسمى على المستوى القومى،ومساعدتهم فى الحصول على فرص العمل اللائقة لهم،وتنمية مهاراتهم بما يتناسب مع احتياجات سوق العمل فى الداخل والخارج،وحمايتهم أثناء العمل،وتقديم الدعم اللازم أثناء فترات التعطل. وتسرى على العمالة غير المنتظمة والعاملين فى القطاع غير الرسمى،الذين يعملون لدى أصحاب الأعمال،جميع الحقوق والواجبات الواردة فى هذا القانون. ويصدر الوزير المختص قرارا بالقواعد والأحكام المنظمة لشروط وظروف عمل تلك الفئات،وطرق الحصول على حقوقهم والقيام بواجباتهم،بما يتوافق مع طبيعة وفترات عملهم.$q153$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q153$تهدف أحكام هذا الباب إلى تنظيم ودعم وتشغيل العمالة غير المنتظمة والعاملين فى القطاع غير الرسمى على المستوى القومى،ومساعدتهم فى الحصول على فرص العمل اللائقة لهم،وتنمية مهاراتهم بما يتناسب مع احتياجات سوق العمل فى الداخل والخارج،وحمايتهم أثناء العمل،وتقديم الدعم اللازم أثناء فترات التعطل. وتسرى على العمالة غير المنتظمة والعاملين فى القطاع غير الرسمى،الذين يعملون لدى أصحاب الأعمال،جميع الحقوق والواجبات الواردة فى هذا القانون. ويصدر الوزير المختص قرارا بالقواعد والأحكام المنظمة لشروط وظروف عمل تلك الفئات،وطرق الحصول على حقوقهم والقيام بواجباتهم،بما يتوافق مع طبيعة وفترات عملهم.$q153$, '2025-09-01', 'active' FROM ins_art_law14_75;

WITH ins_art_law14_76 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 76, $q154$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثالث: تشغيل العمالة غير المنتظمة$q154$, $q155$تتولى الوزارة المختصة رسم سياسة ومتابعة تشغيل العمالة غير المنتظمة وعلى الأخص عمال الزراعة الموسميون،وعمال المقاولات وعمال البحر،وعمال المناجم والمحاجر،بما يتفق مع السياسة العامة للدولة. وللوزير المختص تحديد فئات العمالة غير المنتظمة بالتشاور مع الوزراء المعنيين والمنظمات النقابية العمالية المعنية،ومنظمات أصحاب الأعمال المعنيين.$q155$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q155$تتولى الوزارة المختصة رسم سياسة ومتابعة تشغيل العمالة غير المنتظمة وعلى الأخص عمال الزراعة الموسميون،وعمال المقاولات وعمال البحر،وعمال المناجم والمحاجر،بما يتفق مع السياسة العامة للدولة. وللوزير المختص تحديد فئات العمالة غير المنتظمة بالتشاور مع الوزراء المعنيين والمنظمات النقابية العمالية المعنية،ومنظمات أصحاب الأعمال المعنيين.$q155$, '2025-09-01', 'active' FROM ins_art_law14_76;

WITH ins_art_law14_77 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 77, $q156$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثالث: تشغيل العمالة غير المنتظمة$q156$, $q157$تلتزم الجهة الإدارية المختصة بحصر وقيد العمالة غير المنتظمة،وفق ًا لتصنيفها وفئاتها،فى السجلات الورقية أو الإلكترونية المعدة لذلك. كما تلتزم بإعداد قواعد بيانات قومية لفئات العمالة غير المنتظمة،وربطها بأجهزة ووزارات الدولة بالتنسيق مع الجهات المعنية،وعلى الأخص الجهاز المركزى للتعبئة العامة والإحصاء،والهيئة القومية للتأمين الاجتماعي. ويصدر الوزير المختص قرارا بالقواعد والإجراءات اللازمة لذلك.$q157$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q157$تلتزم الجهة الإدارية المختصة بحصر وقيد العمالة غير المنتظمة،وفق ًا لتصنيفها وفئاتها،فى السجلات الورقية أو الإلكترونية المعدة لذلك. كما تلتزم بإعداد قواعد بيانات قومية لفئات العمالة غير المنتظمة،وربطها بأجهزة ووزارات الدولة بالتنسيق مع الجهات المعنية،وعلى الأخص الجهاز المركزى للتعبئة العامة والإحصاء،والهيئة القومية للتأمين الاجتماعي. ويصدر الوزير المختص قرارا بالقواعد والإجراءات اللازمة لذلك.$q157$, '2025-09-01', 'active' FROM ins_art_law14_77;

WITH ins_art_law14_78 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 78, $q158$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثالث: تشغيل العمالة غير المنتظمة$q158$, $q159$ينشأ صندوق لحماية وتشغيل العمالة غير المنتظمة يسمى "صندوق إعانات الطوارئ والخدمات الاجتماعية والصحية للعمالة غير المنتظمة"،تكون له الشخصية الاعتبارية العامة،ويتبع الوزير المختص،ويكون مقره الرئيسى محافظة القاهرة، وله أن ينشئ فروعا فى المحافظات. ويصدر رئيس مجلس الوزراء قرارا بتشكيل مجلس إدارة الصندوق،برئاسة الوزير المختص،وعضوية ممثلى المنظمات النقابية العمالية المعنية ومنظمات أصحاب الأعمال المعنية بالتساوى فيما بينهما،وممثلى الوزارات والجهات المعنية، ويحدد القرار اختصاصات المجلس،والنظام الأساسى للصندوق،والمعاملة المالية لرئيس وأعضاء مجلس الإدارة،على أن تكون من موارده الذاتية،والنظام المحاسبى الواجب اتباعه.$q159$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q159$ينشأ صندوق لحماية وتشغيل العمالة غير المنتظمة يسمى "صندوق إعانات الطوارئ والخدمات الاجتماعية والصحية للعمالة غير المنتظمة"،تكون له الشخصية الاعتبارية العامة،ويتبع الوزير المختص،ويكون مقره الرئيسى محافظة القاهرة، وله أن ينشئ فروعا فى المحافظات. ويصدر رئيس مجلس الوزراء قرارا بتشكيل مجلس إدارة الصندوق،برئاسة الوزير المختص،وعضوية ممثلى المنظمات النقابية العمالية المعنية ومنظمات أصحاب الأعمال المعنية بالتساوى فيما بينهما،وممثلى الوزارات والجهات المعنية، ويحدد القرار اختصاصات المجلس،والنظام الأساسى للصندوق،والمعاملة المالية لرئيس وأعضاء مجلس الإدارة،على أن تكون من موارده الذاتية،والنظام المحاسبى الواجب اتباعه.$q159$, '2025-09-01', 'active' FROM ins_art_law14_78;

WITH ins_art_law14_79 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 79, $q160$الكتاب الثانى: التدريب والتشغيل وتشغيل العمالة غير المنتظمة — الباب الثالث: تشغيل العمالة غير المنتظمة$q160$, $q161$يختص الصندوق بما يأتي:
-١ صرف إعانات الطوارئ للعمالة غير المنتظمة فى حالات الأزمات الاقتصادية العامة أو الكوارث أو الأوبئة أو حالات التوقف المؤقت عن العمل.
-٢ تقديم الخدمات الاجتماعية والصحية لفئات العمالة غير المنتظمة.
-٣ دعم النفقات العلاجية والخدمات الطبية.
-٤ المساهمة فى سداد اشتراكات التأمين الاجتماعى للعمالة غير المنتظمة بالاتفاق مع وزير المالية ووزير التضامن الاجتماعى،والهيئة القومية للتأمين الاجتماعي،وفى حدود موارد الصندوق.
-٥ دعم وتطوير وتعزيز عمليات التشغيل اللازمة للعمالة غير المنتظمة.
-٦ تدريب العمالة غير المنتظمة المخاطبين بأحكام هذا القانون وتنمية مهاراتهم الفنية والمهنية فى مجالات العمل المختلفة بالتنسيق مع الوزارة المختصة.
-٧ المساهمة فى توفير أدوات العمل اللازمة لبعض فئات العمالة غير المنتظمة للقيام بأعمالهم.
-٨ المساهمة فى توفير سبل الانتقال والإعاشة والإقامة بمواقع العمل النائية.
-٩ المشاركة فى دعم الالتزام باشتراطات السلامة والصحة المهنية اللازمة وتأمين بيئة العمل.
-١٠ تقديم البرامج الثقافية والرياضية،وإقامة المسابقات اللازمة لتنمية مهارات العمالة غير المنتظمة،فنيا وثقافيا،ورياضيا،وإعداد برامج الرحلات الترفيهية، والمصايف طبق ًا للموارد المتاحة.
-١١ المساهمة فى تمويل عمليات حصر العمالة غير المنتظمة على المستوى القومى أو إعداد قواعد بياناتها.
-١٢ إطلاق الحملات التوعوية إعلاميا للتعريف بحقوق العمالة غير المنتظمة وحقوقهم التأمينية والاجتماعية وغيرها.
-١٣ إنشاء المنصات الإلكترونية اللازمة لتقديم خدمات الصندوق الرقمية.
- ١٤إقامة مشروعات تنموية تستهدف الارتقاء بأوضاع العمالة غير المنتظمة، أو دمج العاملين فى القطاع غير الرسمى بالقطاع الرسمى على المستوى القومى، سواء منفردا أو بالتعاون مع الجهات والمنظمات الدولية أو الإقليمية المتخصصة بعد موافقة الجهات الوطنية المعنية.$q161$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q161$يختص الصندوق بما يأتي:
-١ صرف إعانات الطوارئ للعمالة غير المنتظمة فى حالات الأزمات الاقتصادية العامة أو الكوارث أو الأوبئة أو حالات التوقف المؤقت عن العمل.
-٢ تقديم الخدمات الاجتماعية والصحية لفئات العمالة غير المنتظمة.
-٣ دعم النفقات العلاجية والخدمات الطبية.
-٤ المساهمة فى سداد اشتراكات التأمين الاجتماعى للعمالة غير المنتظمة بالاتفاق مع وزير المالية ووزير التضامن الاجتماعى،والهيئة القومية للتأمين الاجتماعي،وفى حدود موارد الصندوق.
-٥ دعم وتطوير وتعزيز عمليات التشغيل اللازمة للعمالة غير المنتظمة.
-٦ تدريب العمالة غير المنتظمة المخاطبين بأحكام هذا القانون وتنمية مهاراتهم الفنية والمهنية فى مجالات العمل المختلفة بالتنسيق مع الوزارة المختصة.
-٧ المساهمة فى توفير أدوات العمل اللازمة لبعض فئات العمالة غير المنتظمة للقيام بأعمالهم.
-٨ المساهمة فى توفير سبل الانتقال والإعاشة والإقامة بمواقع العمل النائية.
-٩ المشاركة فى دعم الالتزام باشتراطات السلامة والصحة المهنية اللازمة وتأمين بيئة العمل.
