INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q179$يعتبر عقد العمل غير محدد المدة منذ إبرامه فى الحالات الآتية:
-١ إذا كان غير مكتوب.
-٢ إذا لم ينص العقد على مدته.
-٣ إذا كان مبرما لمدة محددة واستمر الطرفان فى تنفيذه بعد انتهاء هذه المدة دون اتفاق مكتوب بينهما.$q179$, '2025-09-01', 'active' FROM ins_art_law14_88;

WITH ins_art_law14_89 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 89, $q180$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q180$, $q181$يلتزم صاحب العمل بتحرير عقد العمل كتابة باللغة العربية من أربع نسخ، يحتفظ صاحب العمل بنسخة،وتسلم نسخة للعامل،وتودع الثالثة بمكتب التأمين الاجتماعى المختص،والنسخة الرابعة بالجهة الإدارية المختصة. وإذا كان العامل أجنبيا ولا يجيد اللغة العربية يجوز أن يحرر عقد العمل باللغة العربية ولغة العامل،وفى حالة الاختلاف فى التفسير يعمل بعقد العمل المحرر باللغة العربية. ويجب أن يتضمن العقد على الأخص البيانات الآتية:
-١ تاريخ بداية العقد.
-۲ اسم صاحب العمل وعنوان محل العمل.
-٣ اسم العامل ومؤهله،ومهنته،أو حرفته ورقمه التأميني،ومحل إقامته، وما يلزم لإثبات شخصيته.
-٤ طبيعة ونوع العمل محل العقد.
-٥ الأجر المتفق عليه،وطريقة وموعد أدائه،وسائر المزايا النقدية والعينية المتفق عليها. وإذا لم يوجد عقد مكتوب فيكون لكل من العامل وصاحب العمل الحق فى إثبات علاقة العمل،ومدته،وجميع الحقوق المترتبة عليها بطرق الإثبات كافة. ويعطى صاحب العمل للعامل إيصالا ً بما يكون قد أودعه لديه من أوراق وشهادات.$q181$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
