WITH ins_art_law14_102 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 102, $q206$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q206$, $q207$يختص المجلس المشار إليه فى المادة ) (١٠١من هذا القانون على وجه الخصوص بالآتي:
-١ وضع الحد الأدنى لأجور العاملين فى كل القطاعات على المستوى القومى، بمراعاة احتياجات العمال وعائلاتهم وتكاليف المعيشة وتغيراتها،وتحقيق التوازن بين طرفى علاقة العمل،وضمان زيادة معدلات الإنتاج.
-۲ وضع الحد الأدنى للعلاوة الدورية السنوية،بما لا يقل عن النسبة المقررة فى المادة ) (١٢من هذا القانون،والقواعد المنظمة لصرفها وفق ًا لأحكام هذا القانون.
-٣ النظر فى طلبات أصحاب الأعمال للتخفيض أو الإعفاء من صرف العلاوة الدورية لظروف اقتصادية طارئة.
-٤ وضع المعايير والضوابط التى على أساسها يتم قبول أو رفض طلبات التخفيض أو الإعفاء من صرف العلاوة الدورية السنوية.
-٥ إخطار الوزارات المعنية بقبول أو رفض الطلبات المقدمة من ذوى الشأن بالتخفيض أو الإعفاء من صرف العلاوة الدورية السنوية. ويصدر رئيس مجلس الوزراء قرارا بتحديد نظام العمل بالمجلس،واختصاصاته الأخرى،فى موعد أقصاه ستة أشهر من تاريخ العمل بهذا القانون.$q207$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
