INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q215$مع عدم الإخلال بالاختصاص المقرر لمحاكم مجلس الدولة،لكل ذى مصلحة الطعن على القرارات الصادرة عن المجلس القومى للأجور فى طلبات أصحاب الأعمال بالتخفيض أو الإعفاء من صرف العلاوة الدورية السنوية أمام المحكمة العمالية،وذلك خلال ثلاثين يوما من التاريخ المقرر لصرف العلاوة أو الإخطار بالقرار المطعون فيه،بحسب الأحوال.$q215$, '2025-09-01', 'active' FROM ins_art_law14_106;

WITH ins_art_law14_107 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 107, $q216$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q216$, $q217$يحدد الأجر وفق ًا لعقد العمل الفردى،أو اتفاقية العمل الجماعية،أو لائحة المنشأة المعتمدة،فإذا لم يحدد بأى من هذه الطرق استحق العامل أجر المثل إن وجد،وإلا قدر الأجر طبق ًا لعرف المهنة فى الجهة التى يؤدى فيها العمل،فإن لم يوجد عرف تولى قاضى الأمور الوقتية بالمحكمة العمالية المختصة تقدير الأجر وفق ًا لمقتضيات العدالة،مع مراعاة أحكام هذا القانون.$q217$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q217$يحدد الأجر وفق ًا لعقد العمل الفردى،أو اتفاقية العمل الجماعية،أو لائحة المنشأة المعتمدة،فإذا لم يحدد بأى من هذه الطرق استحق العامل أجر المثل إن وجد،وإلا قدر الأجر طبق ًا لعرف المهنة فى الجهة التى يؤدى فيها العمل،فإن لم يوجد عرف تولى قاضى الأمور الوقتية بالمحكمة العمالية المختصة تقدير الأجر وفق ًا لمقتضيات العدالة،مع مراعاة أحكام هذا القانون.$q217$, '2025-09-01', 'active' FROM ins_art_law14_107;

WITH ins_art_law14_108 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 108, $q218$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q218$, $q219$تؤدى الأجور وغيرها من المبالغ المستحقة للعامل فى أحد أيام العمل وفى مكانه بالعملة المتداولة قانون ًا،أو فى حساب العامل البنكى،مع مراعاة الأحكام التالية:
-١ العمال المعينون بأجر شهرى تؤدى أجورهم مرة على الأقل فى الشهر.
-٢ إذا كان الأجر بالإنتاج أو بالعمولة واستلزم العمل مدة تزيد على أسبوعين، وجب أن يحصل العامل كل أسبوع على دفعة تحت الحساب تتناسب مع ما أتمه من العمل،وأن يؤدى له باقى أجره خلال الأسبوع التالى لتسليم ما كلف به.
-٣ فى غير ما ذكر فى البندين ) (٢، ۱من هذه المادة تؤدى للعمال أجورهم مرة كل أسبوع على الأكثر ما لم يتفق على غير ذلك.
-٤ إذا انتهت علاقة العمل لأى سبب يؤدى صاحب العمل للعامل أجره وجميع المبالغ المستحقة له فى مدة لا تجاوز سبعة أيام من تاريخ مطالبة العامل بهذه المستحقات. وفى جميع الأحوال،يجب ألا يقل ما يحصل عليه العامل عن الحد الأدنى للأجور،ويحظر احتجاز أجر العامل أو جزء منه دون سند قانوني.$q219$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
