  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 123, $q248$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q248$, $q249$لا تسرى أحكام المواد ) / ۱۲۰، ۱۱۹، ۱۱۸، ۱۱۷فقرة ثانية( من هذا القانون على الفئات الآتية:
