SELECT id, 1, $q249$لا تسرى أحكام المواد ) / ۱۲۰، ۱۱۹، ۱۱۸، ۱۱۷فقرة ثانية( من هذا القانون على الفئات الآتية:
-١ الوكلاء المفوضين عن صاحب العمل.
-٢ العمال المشتغلين بالأعمال التجهيزية والتكميلية التى يتعين إنجازها قبل أو بعد انتهاء العمل.
-٣ العمال المخصصين للحراسة والنظافة. ويحدد الحد الأقصى لساعات العمل الفعلية والإضافية للأعمال المشار إليها فى البندين ) (٣، ٢من الفقرة الأولى من هذه المادة بقرار من الوزير المختص، ويستحق العمال فى هذه الحالة أجرا إضافيا طبق ًا لنص المادة ) (١٢١من هذا القانون. ) الفصل الخامس ( الإجازات$q249$, '2025-09-01', 'active' FROM ins_art_law14_123;

WITH ins_art_law14_124 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 124, $q250$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q250$, $q251$يستحق العامل إجازة سنوية بأجر،لا يدخل فى حسابها أيام عطلات الأعياد والمناسبات الرسمية والراحة الأسبوعية،وذلك على الوجه الآتى:
-١ خمسة عشر يوما فى السنة الأولى.
-٢ واحد وعشرون يوما اعتبارا من السنة الثانية.
-٣ ثلاثون يوما لمن أمضى عشر سنوات كاملة لدى صاحب عمل أو أكثر، أو لمن تجاوزت سنه خمسين عاما.
-٤ خمسة وأربعون يوما للأشخاص ذوى الإعاقة والأقزام. وإذا قلت مدة خدمة العامل عن سنة تكون إجازته بنسبة المدة التى قضاها في العمل بشرط أن يكون قد أمضى ستة أشهر على الأقل فى خدمة صاحب العمل. وفى جميع الأحوال،تزاد مدة الإجازة السنوية بمقدار سبعة أيام للعمال الذين يعملون فى الأعمال الخطرة،أو المضرة بالصحة،أو فى المناطق النائية،والتى يصدر بتحديدها قرار من الوزير المختص بعد أخذ رأى الجهات المعنية.$q251$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q251$يستحق العامل إجازة سنوية بأجر،لا يدخل فى حسابها أيام عطلات الأعياد والمناسبات الرسمية والراحة الأسبوعية،وذلك على الوجه الآتى:
-١ خمسة عشر يوما فى السنة الأولى.
-٢ واحد وعشرون يوما اعتبارا من السنة الثانية.
-٣ ثلاثون يوما لمن أمضى عشر سنوات كاملة لدى صاحب عمل أو أكثر، أو لمن تجاوزت سنه خمسين عاما.
-٤ خمسة وأربعون يوما للأشخاص ذوى الإعاقة والأقزام. وإذا قلت مدة خدمة العامل عن سنة تكون إجازته بنسبة المدة التى قضاها في العمل بشرط أن يكون قد أمضى ستة أشهر على الأقل فى خدمة صاحب العمل. وفى جميع الأحوال،تزاد مدة الإجازة السنوية بمقدار سبعة أيام للعمال الذين يعملون فى الأعمال الخطرة،أو المضرة بالصحة،أو فى المناطق النائية،والتى يصدر بتحديدها قرار من الوزير المختص بعد أخذ رأى الجهات المعنية.$q251$, '2025-09-01', 'active' FROM ins_art_law14_124;

WITH ins_art_law14_125 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 125, $q252$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q252$, $q253$يحدد صاحب العمل مواعيد الإجازة السنوية حسب مقتضيات العمل وظروفه، ولا يجوز قطعها إلا لأسباب قوية تقتضيها مصلحة العمل. ولا يجوز للعامل النزول عن إجازته،ويلتزم بالقيام بالإجازة فى التاريخ، والمدة التى حددها صاحب العمل وتم إخطاره بها،وإذا رفض العامل كتابة القيام بالإجازة سقط حقه فى اقتضاء مقابلها. وفى جميع الأحوال،يجب أن يحصل العامل على إجازة سنوية مدتها خمسة عشر يوما،منها ستة أيام متصلة على الأقل،ويلتزم صاحب العمل بتسوية رصيد الإجازات،أو الأجر المقابل له كل ثلاث سنوات على الأكثر،فإذا انتهت علاقة العمل قبل استنفاد العامل رصيد إجازته السنوية استحق الأجر المقابل لهذا الرصيد. ولا يجوز تجزئة الإجازة أو ضمها أو تأجيلها بالنسبة للأطفال والأشخاص ذوى الإعاقة والأقزام.$q253$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q253$يحدد صاحب العمل مواعيد الإجازة السنوية حسب مقتضيات العمل وظروفه، ولا يجوز قطعها إلا لأسباب قوية تقتضيها مصلحة العمل. ولا يجوز للعامل النزول عن إجازته،ويلتزم بالقيام بالإجازة فى التاريخ، والمدة التى حددها صاحب العمل وتم إخطاره بها،وإذا رفض العامل كتابة القيام بالإجازة سقط حقه فى اقتضاء مقابلها. وفى جميع الأحوال،يجب أن يحصل العامل على إجازة سنوية مدتها خمسة عشر يوما،منها ستة أيام متصلة على الأقل،ويلتزم صاحب العمل بتسوية رصيد الإجازات،أو الأجر المقابل له كل ثلاث سنوات على الأكثر،فإذا انتهت علاقة العمل قبل استنفاد العامل رصيد إجازته السنوية استحق الأجر المقابل لهذا الرصيد. ولا يجوز تجزئة الإجازة أو ضمها أو تأجيلها بالنسبة للأطفال والأشخاص ذوى الإعاقة والأقزام.$q253$, '2025-09-01', 'active' FROM ins_art_law14_125;

WITH ins_art_law14_126 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 126, $q254$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q254$, $q255$للعامل الحق فى تحديد موعد إجازته السنوية إذا كان متقدما لأداء الامتحان فى إحدى مراحل التعليم بشرط أن يخطر صاحب العمل قبل قيامه بالإجازة بخمسة عشر يوما على الأقل. وللعامل الحق فى الحصول على إجازة دراسية بأجر عن أيام الامتحان الفعلية لا تحتسب من رصيد إجازاته السنوية،ويشترط لذلك:
-١ إخطار صاحب العمل قبل القيام بالإجازة بعشرة أيام على الأقل.
-٢ إثبات ما يفيد دخوله الامتحان فعليا.$q255$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q255$للعامل الحق فى تحديد موعد إجازته السنوية إذا كان متقدما لأداء الامتحان فى إحدى مراحل التعليم بشرط أن يخطر صاحب العمل قبل قيامه بالإجازة بخمسة عشر يوما على الأقل. وللعامل الحق فى الحصول على إجازة دراسية بأجر عن أيام الامتحان الفعلية لا تحتسب من رصيد إجازاته السنوية،ويشترط لذلك:
-١ إخطار صاحب العمل قبل القيام بالإجازة بعشرة أيام على الأقل.
-٢ إثبات ما يفيد دخوله الامتحان فعليا.$q255$, '2025-09-01', 'active' FROM ins_art_law14_126;

WITH ins_art_law14_127 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 127, $q256$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q256$, $q257$لصاحب العمل أن يحرم العامل من أجره عن مدة الإجازة،أو يسترد ما أداه من أجر عنها،إذا ثبت اشتغاله خلالها لدى الغير،وذلك دون إخلال بالجزاء التأديبي.$q257$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q257$لصاحب العمل أن يحرم العامل من أجره عن مدة الإجازة،أو يسترد ما أداه من أجر عنها،إذا ثبت اشتغاله خلالها لدى الغير،وذلك دون إخلال بالجزاء التأديبي.$q257$, '2025-09-01', 'active' FROM ins_art_law14_127;

WITH ins_art_law14_128 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 128, $q258$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q258$, $q259$للعامل أن ينقطع عن العمل لسبب عارض لمدة لا تجاوز سبعة أيام خلال السنة، وبحد أقصى يومان فى المرة الواحدة،وتحسب الإجازة العارضة من الإجازة السنوية المقررة للعامل. وللعامل الذى يولد له مولود الحق فى إجازة طارئة مدفوعة الأجر يوم الولادة لا تحسب من رصيد إجازاته السنوية،بحد أقصى ثلاث مرات طوال مدة الخدمة.$q259$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q259$للعامل أن ينقطع عن العمل لسبب عارض لمدة لا تجاوز سبعة أيام خلال السنة، وبحد أقصى يومان فى المرة الواحدة،وتحسب الإجازة العارضة من الإجازة السنوية المقررة للعامل. وللعامل الذى يولد له مولود الحق فى إجازة طارئة مدفوعة الأجر يوم الولادة لا تحسب من رصيد إجازاته السنوية،بحد أقصى ثلاث مرات طوال مدة الخدمة.$q259$, '2025-09-01', 'active' FROM ins_art_law14_128;

WITH ins_art_law14_129 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 129, $q260$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q260$, $q261$للعامل الحق فى إجازة بأجر فى العطلات والأعياد والمناسبات التى يصدر بتحديدها قرار من الوزير المختص،وتسرى بالنسبة للأعياد الدينية لغير المسلمين أحكام قرار مجلس الوزراء الصادر فى هذا الشأن. ولصاحب العمل تشغيل العامل فى هذه الأيام،إذا اقتضت ظروف العمل ذلك، ويستحق العامل فى هذه الحالة بالإضافة إلى أجره عن هذا اليوم مثلى هذا الأجر أو أن يمنح العامل يوما آخر عوضا عنه بناء على طلب كتابى من العامل يودع بالملف الخاص به.$q261$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q261$للعامل الحق فى إجازة بأجر فى العطلات والأعياد والمناسبات التى يصدر بتحديدها قرار من الوزير المختص،وتسرى بالنسبة للأعياد الدينية لغير المسلمين أحكام قرار مجلس الوزراء الصادر فى هذا الشأن. ولصاحب العمل تشغيل العامل فى هذه الأيام،إذا اقتضت ظروف العمل ذلك، ويستحق العامل فى هذه الحالة بالإضافة إلى أجره عن هذا اليوم مثلى هذا الأجر أو أن يمنح العامل يوما آخر عوضا عنه بناء على طلب كتابى من العامل يودع بالملف الخاص به.$q261$, '2025-09-01', 'active' FROM ins_art_law14_129;

WITH ins_art_law14_130 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 130, $q262$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q262$, $q263$للعامل الذى أمضى فى خدمة صاحب عمل خمس سنوات متصلة،الحق فى إجازة بأجر لمدة شهر لأداء فريضة الحج،أو زيارة بيت المقدس،وتكون هذه الإجازة مرة واحدة طوال مدة خدمته.$q263$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
