INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q263$للعامل الذى أمضى فى خدمة صاحب عمل خمس سنوات متصلة،الحق فى إجازة بأجر لمدة شهر لأداء فريضة الحج،أو زيارة بيت المقدس،وتكون هذه الإجازة مرة واحدة طوال مدة خدمته.$q263$, '2025-09-01', 'active' FROM ins_art_law14_130;

WITH ins_art_law14_131 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 131, $q264$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q264$, $q265$للعامل الذى يثبت مرضه،أو إصابته على نحو يحول بينه وبين أداء عمله الحق فى إجازة مرضية تحددها الجهة الطبية المختصة،ويستحق العامل خلالها تعويضا عن الأجر،تحدد نسبته ومدته،وفق ًا لأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه. ويكون للعامل الذى يثبت مرضه فى المنشآت الصناعية التى يسرى فى شأنها قانون تيسير منح تراخيص المنشآت الصناعية الصادر بالقانون رقم ١٥لسنة، ٢٠١٧الحق فى إجازة مرضية كل ثلاث سنوات تقضى فى الخدمة على أساس ثلاثة أشهر بأجر،
ثم ستة أشهر بأجر يعادل ) (٪٨٥من أجره،ثم ثلاثة أشهر بأجر يعادل ) (٪٧٥من أجره، وذلك إذا قررت الجهة الطبية المختصة احتمال شفائه. ويخصم من الأجر الذى يلتزم به صاحب العمل،ما يلتزم بأدائه نظام التأمين الاجتماعى من تعويض عن الأجر. وللعامل أن يستفيد من متجمد إجازاته السنوية إلى جانب ما يستحقه من إجازة مرضية،كما له أن يطلب تحويل الإجازة المرضية إلى إجازة سنوية،إذا كان له رصيد يسمح بذلك.$q265$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q265$للعامل الذى يثبت مرضه،أو إصابته على نحو يحول بينه وبين أداء عمله الحق فى إجازة مرضية تحددها الجهة الطبية المختصة،ويستحق العامل خلالها تعويضا عن الأجر،تحدد نسبته ومدته،وفق ًا لأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه. ويكون للعامل الذى يثبت مرضه فى المنشآت الصناعية التى يسرى فى شأنها قانون تيسير منح تراخيص المنشآت الصناعية الصادر بالقانون رقم ١٥لسنة، ٢٠١٧الحق فى إجازة مرضية كل ثلاث سنوات تقضى فى الخدمة على أساس ثلاثة أشهر بأجر،
ثم ستة أشهر بأجر يعادل ) (٪٨٥من أجره،ثم ثلاثة أشهر بأجر يعادل ) (٪٧٥من أجره، وذلك إذا قررت الجهة الطبية المختصة احتمال شفائه. ويخصم من الأجر الذى يلتزم به صاحب العمل،ما يلتزم بأدائه نظام التأمين الاجتماعى من تعويض عن الأجر. وللعامل أن يستفيد من متجمد إجازاته السنوية إلى جانب ما يستحقه من إجازة مرضية،كما له أن يطلب تحويل الإجازة المرضية إلى إجازة سنوية،إذا كان له رصيد يسمح بذلك.$q265$, '2025-09-01', 'active' FROM ins_art_law14_131;

WITH ins_art_law14_132 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 132, $q266$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q266$, $q267$للجهة الطبية المختصة منع العامل المخالط لمريض بمرض معد من أحد أفراد أسرته من مزاولة عمله المدة المناسبة بما لا يجاوز ثلاثة أشهر،وتحدد هذه الأمراض بقرار من الوزير المعنى بشئون الصحة،كما يحدد القرار الجهة الطبية المختصة المشار إليها.$q267$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q267$للجهة الطبية المختصة منع العامل المخالط لمريض بمرض معد من أحد أفراد أسرته من مزاولة عمله المدة المناسبة بما لا يجاوز ثلاثة أشهر،وتحدد هذه الأمراض بقرار من الوزير المعنى بشئون الصحة،كما يحدد القرار الجهة الطبية المختصة المشار إليها.$q267$, '2025-09-01', 'active' FROM ins_art_law14_132;

