WITH ins_art_law14_134 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 134, $q270$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q270$, $q271$يجب على العامل ما يأتي:
-١ أن يؤدى بنفسه الواجبات المنوطة به بدقة وأمانة،وذلك وفق ًا لما هو محدد بالقانون ولوائح العمل،وعقود العمل الفردية والجماعية،وأن ينجزها فى الوقت المحدد،وأن يبذل فيها عناية الشخص المعتاد.
-٢ أن ينفذ أوامر وتعليمات صاحب العمل الخاصة بتنفيذ الواجبات التى تدخل فى نطاق العمل المنوط به،إذا لم يكن فى هذه الأوامر والتعليمات ما يخالف العقد أو القانون أو اللوائح أو الآداب العامة،ولم يكن فى تنفيذها ما يعرض للخطر.
-٣ أن يحافظ على مواعيد العمل،وأن يتبع الإجراءات المقررة فى حالة التغيب عن العمل،أو مخالفة مواعيده.
-٤ أن يحافظ على ما يسلمه إليه صاحب العمل من أدوات أو أجهزة أو مستندات أو أى أشياء أخرى،وأن يقوم بجميع الأعمال اللازمة لسلامتها،ويلتزم بأن يبذل فى ذلك عناية الشخص المعتاد.
-٥ أن يحسن معاملة عملاء صاحب العمل.
-٦ أن يحترم رؤساءه وزملاءه فى العمل،وأن يتعاون معهم بما يحقق مصلحة المنشأة التي يعمل بها.
-٧ أن يحافظ على كرامة العمل،وأن يتبع السلوك القويم.
-٨ أن يراعى النظم الموضوعة للمحافظة على سلامة المنشأة وأمنها.
-٩ أن يحافظ على أسرار العمل،فلا يفشى المعلومات المتعلقة بالعمل متى كانت سرية بطبيعتها،أو وفق ًا للتعليمات الكتابية الصادرة عن صاحب العمل.
-١٠ أن يخطر جهة العمل بالبيانات الصحيحة المتعلقة بمحل إقامته وحالته الاجتماعية وموقفه من أداء الخدمة العسكرية،والبيانات الأخرى التى تتطلب القوانين أو النظم إدراجها فى السجل الخاص به،وبكل تغيير يطرأ على بيان من البيانات السابقة فى المواعيد المحددة لذلك.
-١١ أن يتبع النظم التى يضعها صاحب العمل لتنمية وتطوير مهاراته وخبراته مهنيا وثقافيا،أو لتأهيله للقيام بعمل يتفق،أو يتناسب مع عمله والتطور التقنى داخل المنشأة،وذلك بالاشتراك مع المنظمة النقابية العمالية المعنية.$q271$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
