WITH ins_art_law14_135 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 135, $q272$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q272$, $q273$مع عدم الإخلال بأحكام القانون رقم ١٣٧لسنة ١٩٥٨فى شأن الاحتياطات الصحية للوقاية من الأمراض المعدية بالإقليم المصرى،ومع مراعاة أحكام المادتين )۱۳۲ و (۱۳۸من هذا القانون يلتزم العامل بالخضوع للاختبارات الطبية عن تعاطى المواد المخدرة أو الأمراض المعدية حينما يطلب منه صاحب العمل ذلك وعلى نفقته،ويتم الاختبار الطبى بالهيئة العامة للتأمين الصحى أو المعامل المركزية بوزارة الصحة.
وتتم الاختبارات الطبية عن تعاطى المواد المخدرة والتظلم منها وفق ًا للتنظيم والإجراءات والضمانات التى يصدر بها قرار من الوزير المختص،على أن يكون من بينها إجراء فحص لذات العينة فى ذات يوم سحبها،وفى حالة اختلاف نتيجتى الفحص يتم إجراء تحليل توكيدى لدى أى من الجهتين المشار إليهما فى الفقرة الأولى من هذه المادة. فإذا تأكدت إيجابية العينة يتم إحالة العامل للمحكمة العمالية المختصة لإعمال شئونها. وفى جميع الأحوال،يلتزم صاحب العمل باتباع السرية فى إجراء الكشف الطبى وعدم الإفصاح عن الوضع الصحى للعامل بناء على هذه الاختبارات.$q273$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q273$مع عدم الإخلال بأحكام القانون رقم ١٣٧لسنة ١٩٥٨فى شأن الاحتياطات الصحية للوقاية من الأمراض المعدية بالإقليم المصرى،ومع مراعاة أحكام المادتين )۱۳۲ و (۱۳۸من هذا القانون يلتزم العامل بالخضوع للاختبارات الطبية عن تعاطى المواد المخدرة أو الأمراض المعدية حينما يطلب منه صاحب العمل ذلك وعلى نفقته،ويتم الاختبار الطبى بالهيئة العامة للتأمين الصحى أو المعامل المركزية بوزارة الصحة.
وتتم الاختبارات الطبية عن تعاطى المواد المخدرة والتظلم منها وفق ًا للتنظيم والإجراءات والضمانات التى يصدر بها قرار من الوزير المختص،على أن يكون من بينها إجراء فحص لذات العينة فى ذات يوم سحبها،وفى حالة اختلاف نتيجتى الفحص يتم إجراء تحليل توكيدى لدى أى من الجهتين المشار إليهما فى الفقرة الأولى من هذه المادة. فإذا تأكدت إيجابية العينة يتم إحالة العامل للمحكمة العمالية المختصة لإعمال شئونها. وفى جميع الأحوال،يلتزم صاحب العمل باتباع السرية فى إجراء الكشف الطبى وعدم الإفصاح عن الوضع الصحى للعامل بناء على هذه الاختبارات.$q273$, '2025-09-01', 'active' FROM ins_art_law14_135;

WITH ins_art_law14_136 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 136, $q274$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q274$, $q275$يحظر على العامل أن يقوم بنفسه،أو بواسطة غيره بالأعمال الآتية:
-١ الاحتفاظ لنفسه بأى ورقة أو مستند خاص بالعمل أو أى بيانات إلكترونية أو أى من وسائل التأمين الإلكترونية الخاصة بالعمل سواء بنفسه،أو بتمكين الغير من الحصول على أى منها أو على أية معلومات تخص العمل.
-٢ العمل لدى الغير سواء بأجر،أو دون أجر إذا كان فى قيامه بهذا العمل ما يخل بحسن أدائه لعمله أو يمكن الغير،أو يساعده على التعرف على أسرار المنشأة، أو منافسة صاحب العمل.
-٣ ممارسة نشاط مماثل للنشاط الذى يمارسه صاحب العمل أثناء قيام علاقة العمل أو الاشتراك فى نشاط من هذا القبيل،سواء بصفته شريك ًا،أو عاملا ً.
-٤ الاقتراض من عملاء صاحب العمل،أو ممن يمارسون نشاط ًا مماثلا ً للنشاط الذى يمارسه صاحب العمل،ولا يسرى هذا الحظر على الاقتراض من البنوك أو غيرها من الجهات المرخص لها بذلك.
-٥ طلب أو قبول هدايا،أو مكافآت،أو عمولات،أو مبالغ،أو أشياء أخرى بأية صفة كانت بمناسبة قيامه بواجباته بغير موافقة صاحب العمل.
-٦ جمع تبرعات نقدية أو عينية،أو توزيع منشورات،أو جمع توقيعات، أو تنظيم اجتماعات داخل مكان العمل دون موافقة صاحب العمل كتابة،مع مراعاة ما تقضى به أحكام قانون المنظمات النقابية العمالية وحماية حق التنظيم النقابى المشار إليه.$q275$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
