WITH ins_art_law14_138 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 138, $q278$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q278$, $q279$يشترط فى الفعل الذى تجوز مساءلة العامل عنه تأديبيا أن يكون ذا صلة بالعمل، وتحدد لائحة الجزاءات المخالفات والجزاءات المقررة لها،وفق ًا لما هو منصوص عليه فى المادة ) (١٣٩من هذا القانون وبما يحقق تناسب الجزاء مع المخالفة. ولا يجوز توقيع جزاء تأديبى على العامل بعد مضى ثلاثين يوما من تاريخ الانتهاء من التحقيق فى المخالفة.$q279$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q279$يشترط فى الفعل الذى تجوز مساءلة العامل عنه تأديبيا أن يكون ذا صلة بالعمل، وتحدد لائحة الجزاءات المخالفات والجزاءات المقررة لها،وفق ًا لما هو منصوص عليه فى المادة ) (١٣٩من هذا القانون وبما يحقق تناسب الجزاء مع المخالفة. ولا يجوز توقيع جزاء تأديبى على العامل بعد مضى ثلاثين يوما من تاريخ الانتهاء من التحقيق فى المخالفة.$q279$, '2025-09-01', 'active' FROM ins_art_law14_138;

WITH ins_art_law14_139 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 139, $q280$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q280$, $q281$الجزاءات التأديبية التى يجوز توقيعها على العامل وفق ًا للوائح تنظيم العمل والجزاءات فى المنشأة هي:
-١ الإنذار الكتابي.
-٢ الخصم من الأجر الأساسي.
-٣ تأجيل موعد استحقاق العلاوة السنوية لمدة لا تجاوز ثلاثة أشهر.
-٤ الحرمان من جزء من العلاوة السنوية،بما لا يجاوز نصفها.
-٥ تأجيل الترقية عند استحقاقها لمدة لا تزيد على سنة.
-٦ خفض الأجر الأساسى بمقدار علاوة على الأكثر.
-٧ الخفض إلى وظيفة فى الدرجة الأدنى مباشرة،دون تخفيض الأجر.
-٨ الفصل من الخدمة وفق ًا لأحكام هذا القانون.$q281$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
