INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q289$لا يجوز لصاحب العمل أن يوقع جزاء الخصم على العامل عن المخالفة الواحدة بما يزيد على خمسة أيام من الأجر الأساسي،كما لا يجوز أن يقتطع من هذا الأجر وفاء للجزاءات التى يوقعها أكثر من أجر خمسة أيام فى الشهر الواحد. وإذا حدد الخصم بنسبة محددة من الأجر،اعتبر أن المقصود بذلك هو الأجر الأساسى اليومى للعامل.$q289$, '2025-09-01', 'active' FROM ins_art_law14_143;

