WITH ins_art_law14_145 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 145, $q292$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q292$, $q293$لصاحب العمل أن يوقف العامل عن عمله مؤقت ًا بموجب قرار مكتوب لمدة لا تزيد على ستين يوما مع صرف أجره كاملا ً،وذلك فى الحالات الآتية:
-١ إذا أحيل العامل للتحقيق بسبب مخالفة ارتكبها داخل مقر العمل،واقتضت مصلحة التحقيق ذلك.
-٢ إذا أت ُهم العامل بارتكاب جناية أو جنحة مخلة بالشرف أو الأمانة أو الآداب العامة،أو أى جنحة أخرى داخل محل العمل.
-٣ إذا طلب صاحب العمل من المحكمة العمالية المختصة فصل العامل من الخدمة.$q293$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
