-٣ إذا طلب صاحب العمل من المحكمة العمالية المختصة فصل العامل من الخدمة.$q293$, '2025-09-01', 'active' FROM ins_art_law14_145;

WITH ins_art_law14_146 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 146, $q294$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q294$, $q295$للعامل التظلم من قرار وقفه عن العمل الصادر وفق ًا للبندين ) (٢، ١من المادة )(١٤٥ من هذا القانون بموجب عريضة تقدم لقاضى الأمور الوقتية بالمحكمة العمالية المختصة، رار صدور الق ه ب اره،أو علم اريخ إخط ن ت ام م ة أي لال ثلاث ك خ وذل المتظلم منه. وعلى القاضى الفصل فى هذا التظلم فى اليوم التالى لتقديمه على الأكثر،فإذا قضى بعدم صحة القرار الصادر بالوقف،قضى بعودته للعمل مرة أخرى.$q295$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q295$للعامل التظلم من قرار وقفه عن العمل الصادر وفق ًا للبندين ) (٢، ١من المادة )(١٤٥ من هذا القانون بموجب عريضة تقدم لقاضى الأمور الوقتية بالمحكمة العمالية المختصة، رار صدور الق ه ب اره،أو علم اريخ إخط ن ت ام م ة أي لال ثلاث ك خ وذل المتظلم منه. وعلى القاضى الفصل فى هذا التظلم فى اليوم التالى لتقديمه على الأكثر،فإذا قضى بعدم صحة القرار الصادر بالوقف،قضى بعودته للعمل مرة أخرى.$q295$, '2025-09-01', 'active' FROM ins_art_law14_146;

WITH ins_art_law14_147 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 147, $q296$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q296$, $q297$لصاحب العمل أن يطلب من قاضى الأمور الوقتية بالمحكمة العمالية المختصة مد فترة الإيقاف عن العمل لمدة أو لمدد أخرى مع صرف نصف أجر العامل وذلك قبل انتهاء مدة الإيقاف بعشرة أيام. وعلى قاضى الأمور الوقتية البت فى هذا الطلب قبل انتهاء فترة الإيقاف،فإذا لم يصدر قراره خلال هذه المدة ولم يعد العامل إلى عمله،يستمر إيقاف العامل مع صرف الأجر كاملا ً لحين البت فى الطلب فإذا قضى برفض الطلب يعاد لعمله فور انتهاء مدة إيقافه الأخيرة. فإذا كان الوقف لأحد الأسباب الواردة بالبند ) (٢من المادة ) (١٤٥من هذا القانون،ورأت السلطة المختصة بالاتهام حفظ التحقيق،أو إصدار أمر بأن لا وجه لإقامة الدعوى الجنائية،أو قدم العامل للمحاكمة الجنائية وقضى ببراءته،وجبت إعادته إلى عمله مع صرف ما لم يصرف له من مستحقات عن فترة الإيقاف،وإلا اعتبر عدم إعادته للعمل فصلا ً تعسفيا.$q297$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q297$لصاحب العمل أن يطلب من قاضى الأمور الوقتية بالمحكمة العمالية المختصة مد فترة الإيقاف عن العمل لمدة أو لمدد أخرى مع صرف نصف أجر العامل وذلك قبل انتهاء مدة الإيقاف بعشرة أيام. وعلى قاضى الأمور الوقتية البت فى هذا الطلب قبل انتهاء فترة الإيقاف،فإذا لم يصدر قراره خلال هذه المدة ولم يعد العامل إلى عمله،يستمر إيقاف العامل مع صرف الأجر كاملا ً لحين البت فى الطلب فإذا قضى برفض الطلب يعاد لعمله فور انتهاء مدة إيقافه الأخيرة. فإذا كان الوقف لأحد الأسباب الواردة بالبند ) (٢من المادة ) (١٤٥من هذا القانون،ورأت السلطة المختصة بالاتهام حفظ التحقيق،أو إصدار أمر بأن لا وجه لإقامة الدعوى الجنائية،أو قدم العامل للمحاكمة الجنائية وقضى ببراءته،وجبت إعادته إلى عمله مع صرف ما لم يصرف له من مستحقات عن فترة الإيقاف،وإلا اعتبر عدم إعادته للعمل فصلا ً تعسفيا.$q297$, '2025-09-01', 'active' FROM ins_art_law14_147;

WITH ins_art_law14_148 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 148, $q298$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q298$, $q299$يكون الاختصاص بتوقيع جزاء الفصل من العمل للمحكمة العمالية المختصة، ويكون توقيع باقى الجزاءات التأديبية لصاحب العمل،أو من يفوضه لذلك، ويكون لمدير المنشأة توقيع جزائى الإنذار الكتابى،والخصم من الأجر لمدة لا تجاوز ثلاثة أيام.
وفى جميع الأحوال،لا يجوز فصل العامل إلا إذا ارتكب خطأ جسيما، ويعتبر من قبيل الخطأ الجسيم الحالات الآتية:
-١ إذا ثبت انتحال العامل شخصية غير صحيحة أو قدم مستندات مزورة.
-٢ إذا ثبت ارتكاب العامل لخطأ نشأت عنه أضرار جسيمة لصاحب العمل، بشرط أن يبلغ صاحب العمل الجهات المختصة بالواقعة،أو الحادث خلال أربع وعشرين ساعة من وقت علمه بوقوعه.
-٣ إذا ثبت تكرار عدم مراعاة العامل التعليمات اللازم اتباعها لسلامة العمال، أو المنشأة،بشرط أن تكون هذه التعليمات مكتوبة،ومعلنة فى مكان ظاهر، رغم التنبيه عليه كتابة بمراعاة ذلك.
-٤ إذا ثبت أن العامل أفشى أسرار المنشأة التى يعمل بها،وأدى ذلك إلى إحداث أضرار جسيمة بالمنشأة.
-٥ إذا ثبت قيام العامل بمنافسة صاحب العمل فى ذات نشاطه.
-٦ إذا ثبت وجود العامل فى حالة سكر بين أو متأثرا بما تعاطاه من مادة مخدرة أثناء ساعات العمل.
-٧ إذا ثبت اعتداء العامل على صاحب العمل،أو المدير العام،وكذلك إذا وقع منه اعتداء جسيم على أحد رؤسائه أثناء العمل،أو بسببه. وفى جميع الأحوال،لا يجوز الفصل من الخدمة إلا وفق ًا لأحكام هذا القانون.$q299$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
