  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 163, $q328$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q328$, $q329$لصاحب العمل أن يعفى العامل من العمل أثناء مهلة الإخطار،مع احتساب مدة خدمة العامل مستمرة إلى حين انتهاء تلك المهلة،مع ما يترتب على ذلك من آثار، وبخاصة استحقاق العامل أجره عن هذه المهلة.$q329$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q329$لصاحب العمل أن يعفى العامل من العمل أثناء مهلة الإخطار،مع احتساب مدة خدمة العامل مستمرة إلى حين انتهاء تلك المهلة،مع ما يترتب على ذلك من آثار، وبخاصة استحقاق العامل أجره عن هذه المهلة.$q329$, '2025-09-01', 'active' FROM ins_art_law14_163;

WITH ins_art_law14_164 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 164, $q330$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q330$, $q331$إذا أنهى صاحب العمل عقد العمل غير محدد المدة دون إخطار أو قبل انقضاء مهلة الإخطار،يلتزم بأن يؤدى للعامل مبلغ ًا يعادل أجره عن مدة المهلة،أو الجزء الباقى منها. وفى هذه الحالة تحسب مدة المهلة،أو الجزء الباقى منها ضمن مدة خدمة العامل،ويستمر صاحب العمل فى تحمل الأعباء،والالتزامات المترتبة على ذلك،أما إذا كان الإنهاء صادرا من جانب العامل فإن العقد ينتهى من وقت تركه العمل.$q331$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q331$إذا أنهى صاحب العمل عقد العمل غير محدد المدة دون إخطار أو قبل انقضاء مهلة الإخطار،يلتزم بأن يؤدى للعامل مبلغ ًا يعادل أجره عن مدة المهلة،أو الجزء الباقى منها. وفى هذه الحالة تحسب مدة المهلة،أو الجزء الباقى منها ضمن مدة خدمة العامل،ويستمر صاحب العمل فى تحمل الأعباء،والالتزامات المترتبة على ذلك،أما إذا كان الإنهاء صادرا من جانب العامل فإن العقد ينتهى من وقت تركه العمل.$q331$, '2025-09-01', 'active' FROM ins_art_law14_164;

WITH ins_art_law14_165 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 165, $q332$الكتاب الثالث: علاقات العمل — الباب الأول: علاقات العمل الفردية$q332$, $q333$إذا أنهى صاحب العمل العقد غير محدد المدة لسبب غير مشروع،كان للعامل الحق فى تعويض عما أصابه من ضرر بسبب هذا الإنهاء بما لا يقل عن أجر شهرين عن كل سنة من سنوات الخدمة،ولا يخل ذلك بحق العامل فى المطالبة بباقى حقوقه المقررة قانون ًا. ويعتبر من الأسباب غير المشروعة ما يأتي:
-١ انتساب العامل إلى منظمة نقابية،أو مشاركته فى نشاط نقابى فى نطاق هذا القانون.
-٢ ممارسة صفة المفوض العمالي،أو سبق ممارسة هذه الصفة، أو السعى إلى ذلك.
-٣ تقديم شكوى،أو إقامة دعوى ضد صاحب العمل،أو المشاركة فى ذلك، تظلما من إخلاله بالقوانين،أو اللوائح،أو عقود العمل.
-٤ توقيع الحجز على مستحقات العامل تحت يد صاحب العمل.
-٥ استخدام العامل لحقه فى الإجازات الممنوحة له طبق ًا لأحكام هذا القانون.
-٦ اللون،أو الجنس،أو الحالة الاجتماعية،أو المسئوليات العائلية، أو الحمل أو الدين أو الرأى السياسي.$q333$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
