INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q379$ينشأ بالوزارة المختصة مجلس يسمى "المجلس الأعلى للتشاور الاجتماعي"، وتكون له الشخصية الاعتبارية العامة،يهدف إلى تعزيز التعاون والتشاور والحوار بين أطراف العمل الثلاثة فى جميع قضايا العمل،بما يحقق التوازن والاستقرار فى علاقات العمل الفردية والجماعية.$q379$, '2025-09-01', 'active' FROM ins_art_law14_188;

WITH ins_art_law14_189 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 189, $q380$الكتاب الثالث: علاقات العمل — الباب الثالث: علاقات العمل الجماعية$q380$, $q381$يختص المجلس الأعلى للتشاور الاجتماعى بما يأتي:
-١ رسم السياسات القومية للتشاور الثلاثى والحوار الاجتماعى،وخلق بيئة عمل محفزة على التشاور والتعاون وتبادل المعلومات بين أطراف العمل الثلاثة،بما يتفق مع السياسة العامة للدولة.
-٢ إبداء الرأى فى مشروعات القوانين المتعلقة بالعمل،والحماية الاجتماعية، والمنظمات النقابية العمالية،والعلاقات الصناعية والقوانين ذات الصلة.
-٣ إبداء الرأى فى اتفاقيات العمل الدولية والعربية قبل التصديق عليها،وإعداد دراسات تحليل الفجوة التشريعية والتنفيذية اللازمة لها.
-٤ اقتراح الحلول المناسبة لتفادى منازعات العمل الجماعية على المستوى القومى،وعلى الأخص فى الأزمات الاقتصادية التى تؤدى إلى توقف بعض المشروعات عن العمل كليا أو جزئيا.
-٥ اتخاذ الوسائل المناسبة لتعزيز الثقة والتفاهم بين طرفى علاقة العمل على جميع المستويات.
-٦ اقتراح الوسائل والإجراءات اللازمة لدعم المشروعات القومية والاقتصادية التى تهدف إلى خلق فرص العمل.
-٧ إعداد الدراسات والأبحاث اللازمة فى اقتصاديات العمل،ومنها العلاقات الصناعية والمهنية والتدريب المهنى،ودعم تنافسية الاقتصاد الوطني.
-٨ النظر فى المقترحات أو الموضوعات التى تناقش فى مؤتمر العمل الدولى، أو مجلس إدارة منظمة العمل الدولية،أو الهيئات الإشرافية للمنظمة،والموضوعات التى تتضمنها التقارير المقدمة إلى مكتب العمل الدولى،أو المسائل التى تتناولها المؤتمرات الثلاثية الأخرى الإقليمية والدولية.
-٩ التشاور حول مسودة تقارير الحكومة الدورية المتعلقة باتفاقيات العمل الدولية.
-١٠ إبداء الرأى فى الموضوعات التى تعرض عليه من الوزارة المختصة.$q381$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q381$يختص المجلس الأعلى للتشاور الاجتماعى بما يأتي:
-١ رسم السياسات القومية للتشاور الثلاثى والحوار الاجتماعى،وخلق بيئة عمل محفزة على التشاور والتعاون وتبادل المعلومات بين أطراف العمل الثلاثة،بما يتفق مع السياسة العامة للدولة.
