WITH ins_art_law14_221 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 221, $q444$الكتاب الثالث: علاقات العمل — الباب الثالث: علاقات العمل الجماعية$q444$, $q445$يشترط فيمن يقيد بقائمة الوسطاء الشروط الآتية:
-١ أن يكون حاصلا ً على مؤهل عالٍ.
-٢ أن يكون محمود السيرة،وحسن السمعة.
-٣ ألا يكون قد سبق إدانته فى جناية أو جنحة مخلة بالشرف أو الأمانة، ما لم يكن قد رد إليه اعتباره.
-٤ ألا يكون من العاملين بالجهاز الإدارى للدولة.
-٥ ألا يكون قد سبق فصله بالطريق التأديبي.
-٦ قضاء مدة التدريب الأولى على أعمال الوساطة ومجالاتها بالمركز. - ٧اجتياز الاختبار الذى يعقده مركز الوساطة والتحكيم بدرجة لا تقل عن سبعين بالمائة.$q445$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
