)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q481$فى حالة الإغلاق الجزئى أو تقليص حجم المنشأة أو نشاطها،إذا لم تتضمن الاتفاقية الجماعية السارية فى المنشأة المعايير الموضوعية لاختيار من سيتم الاستغناء عنهم من العمال،يتعين على صاحب العمل أن يتشاور فى هذا الشأن مع المنظمة النقابية العمالية المعنية،وذلك بعد صدور القرار وقبل التنفيذ. وتعتبر الأقدمية،والأعباء العائلية،والسن،والقدرات والمهارات المهنية للعمال من المعايير التى يمكن الاسترشاد بها فى هذا الشأن. ويصدر الوزير المختص قرارا بالمعايير الموضوعية لاختيار من سيتم الاستغناء عنهم من العمال،وذلك بالتشاور مع منظمات العمال وأصحاب الأعمال.$q481$, '2025-09-01', 'active' FROM ins_art_law14_239;

