WITH ins_art_law14_248 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 248, $q498$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الأول: تأمين بيئة العمل$q498$, $q499$تلتزم المنشأة وفروعها باتخاذ وسائل وطرق وقاية العمال من خطر الإصابة بالبكتيريا والفيروسات والفطريات،والطفيليات،وسائر المخاطر البيولوجية متى كانت طبيعة العمل ت ُعرض العمال لظروف الإصابة بها،وعلى الأخص ما يأتي:
