WITH ins_art_law14_249 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 249, $q500$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الأول: تأمين بيئة العمل$q500$, $q501$تلتزم المنشأة،وفروعها بتوفير وسائل السلامة والصحة المهنية وتأمين بيئة العمل فى أماكن العمل بما يكفل الوقاية من المخاطر الكيميائية الناتجة عن التعامل مع المواد الكيميائية الصلبة والسائلة والغازية،مع مراعاة ما يأتي:
-١ عدم تجاوز أقصى تركيز مسموح به للتعامل فى المواد الكيميائية،والمواد المسببة للسرطان التى يتعرض لها العمال.
-٢ عدم تجاوز مخزون المواد الكيميائية الخطرة كميات العتبة لكل منها.
-٣ توفير الاحتياطات اللازمة لوقاية المنشأة،والعمال عند تداول ونقل وتخزين،واستخدام المواد الكيميائية الخطرة،والتخلص من مخلفاتها.
-٤ الاحتفاظ بسجل ورقى أو إلكترونى لحصر المواد الكيميائية الخطرة المتداولة متضمن ًا جميع البيانات الخاصة بكل مادة،ويسجل لرصد ملوثات بيئة العمل التى يتعرض لها العمال،ويسجل المواد والمخلفات الخطرة وفق ًا لقانون تنظيم إدارة المخلفات الصادر بالقانون رقم ۲۰۲لسنة ٢٠٢٠
-٥ وضع بطاقات تعريف جميع المواد الكيميائية المتداولة فى العمل موضحا بها الاسم العلمى والتجارى،وتركيبها الكيميائي،ودرجة خطورتها واحتياطات السلامة وإجراءات الطوارئ المتعلقة بها،وعلى المنشأة أن تحصل على البيانات المذكورة فى هذه المواد من مصنعها،أو موردها عند التوريد.
-٦ تدريب العمال على طرق التعامل مع المواد الكيميائية الخطرة،والمواد المسببة للسرطان وتعريفهم بمخاطرها،وبطرق الأمان،والوقاية من هذه المخاطر.
-٧ معايير التعرض والحدود العتبية.$q501$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
