INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q511$تلتزم المنشآت وفروعها بتوفير بيئة عمل آمنة،وغير عدائية،خالية من التحرش والتنمر والعنف،وتوفير الوسائل الكفيلة بالوقاية منهم. ويصدر الوزير المختص قرارا بتحديد نماذج لمدونة السلوك الوظيفي، والقواعد والإجراءات اللازمة لتقديم الشكاوى وسبل تسويتها واتخاذ الإجراءات اللازمة فى شأنها.$q511$, '2025-09-01', 'active' FROM ins_art_law14_254;

