WITH ins_art_law14_256 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 256, $q514$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الثاني: التفتيش فى مجال السلامة$q514$, $q515$مع مراعاة الأحكام الواردة فى الكتاب الخامس من هذا القانون،تلتزم الجهة الإدارية المختصة بما يأتي:
-١ تشكيل جهاز متخصص يسمى )جهاز تفتيش السلامة والصحة المهنية وتأمين بيئة العمل(،من أعضاء تتوافر فيهم المؤهلات العلمية والعملية فى مجالات الطب البشرى،والبيطرى،والصيدلة،والهندسة والعلوم،والبيئة وإدارة المخلفات للتفتيش على المنشآت ومراقبة تنفيذ أحكام السلامة والصحة المهنية وتأمين بيئة العمل على أن يكون التفتيش على فترات دورية مناسبة.
-٢ تنظيم برامج تدريبية متخصصة ونوعية لرفع كفاءة ومستوى أداء أعضاء جهاز التفتيش المشار إليه فى البند ) (١من هذه المادة،وتزويدهم بالخبرات الفنية والتطورات الحديثة بما يضمن أفضل مستويات السلامة والصحة المهنية وتأمين بيئة العمل.
-٣ تزويد جهاز التفتيش المشار إليه بأجهزة ومعدات القياس،وجميع الإمكانيات اللازمة لأداء مهمته. ويكون التفتيش على المنشآت المتعلق عملها بالأمن القومى،والتى تحدد بقرار من رئيس مجلس الوزراء،بمعرفة الجهة التى يحددها هذا القرار.$q515$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q515$مع مراعاة الأحكام الواردة فى الكتاب الخامس من هذا القانون،تلتزم الجهة الإدارية المختصة بما يأتي:
-١ تشكيل جهاز متخصص يسمى )جهاز تفتيش السلامة والصحة المهنية وتأمين بيئة العمل(،من أعضاء تتوافر فيهم المؤهلات العلمية والعملية فى مجالات الطب البشرى،والبيطرى،والصيدلة،والهندسة والعلوم،والبيئة وإدارة المخلفات للتفتيش على المنشآت ومراقبة تنفيذ أحكام السلامة والصحة المهنية وتأمين بيئة العمل على أن يكون التفتيش على فترات دورية مناسبة.
-٢ تنظيم برامج تدريبية متخصصة ونوعية لرفع كفاءة ومستوى أداء أعضاء جهاز التفتيش المشار إليه فى البند ) (١من هذه المادة،وتزويدهم بالخبرات الفنية والتطورات الحديثة بما يضمن أفضل مستويات السلامة والصحة المهنية وتأمين بيئة العمل.
-٣ تزويد جهاز التفتيش المشار إليه بأجهزة ومعدات القياس،وجميع الإمكانيات اللازمة لأداء مهمته. ويكون التفتيش على المنشآت المتعلق عملها بالأمن القومى،والتى تحدد بقرار من رئيس مجلس الوزراء،بمعرفة الجهة التى يحددها هذا القرار.$q515$, '2025-09-01', 'active' FROM ins_art_law14_256;

WITH ins_art_law14_257 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 257, $q516$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الثاني: التفتيش فى مجال السلامة$q516$, $q517$على أعضاء جهاز تفتيش السلامة والصحة المهنية وتأمين بيئة العمل فى سبيل أداء عملهم:
-١ إجراء الفحوص الطبية والمعملية اللازمة على العمال بالمنشآت للتأكد من ملاءمة ظروف العمل.
-۲ أخذ عينات من المواد المستعملة أو المتداولة فى العمليات الصناعية، وأنشطة العمل المختلفة والتى قد يكون لها تأثير ضار على سلامة وصحة العمال أو بيئة العمل،بغرض تحليلها والتعرف على الآثار الناتجة عن استخدامها وتداولها، وإخطار المنشأة بذلك لاتخاذ ما يلزم فى هذا الشأن.
-٣ استخدام المعدات والأجهزة وآلات التصوير وغيرها أثناء التفتيش لتحليل أسباب الحوادث.
-٤ الاطلاع على خطط الطوارئ،وتحليل المخاطر الخاصة بالمنشأة.
-٥ الاطلاع على نتائج التقارير الفنية والإدارية التى ترد للمنشأة عن أنواع الحوادث الجسيمة وأسبابها.
-٦ الاطلاع على كميات المخزون من المواد الخطرة التى قد تهدد المنشأة. وعلى الجهة الإدارية المختصة بناء على تقرير جهاز تفتيش السلامة والصحة المهنية وتأمين بيئة العمل الأمر بإغلاق المنشأة كليا أو جزئيا،أو إيقاف آلة،أو أكثر، وذلك فى حالة وجود خطر داهم يهدد سلامة المنشأة،أو صحة العمال والمترددين، أو سلامة بيئة العمل حتى زوال أسباب الخطر،مع عدم الإخلال بحق العاملين فى تقاضي أجورهم.
وللجهة الإدارية المختصة بناء على قرار الإغلاق أن تقوم بإزالة أسباب الخطر بطريق التنفيذ المباشر على نفقة المنشأة. وينفذ القرار الصادر بالإغلاق أو الإيقاف بالطرق الإدارية. وتصدر الجهة الإدارية المختصة الأمر بإلغاء الإغلاق،أو الإيقاف فور زوال أسباب الخطر.$q517$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q517$على أعضاء جهاز تفتيش السلامة والصحة المهنية وتأمين بيئة العمل فى سبيل أداء عملهم:
-١ إجراء الفحوص الطبية والمعملية اللازمة على العمال بالمنشآت للتأكد من ملاءمة ظروف العمل.
-۲ أخذ عينات من المواد المستعملة أو المتداولة فى العمليات الصناعية، وأنشطة العمل المختلفة والتى قد يكون لها تأثير ضار على سلامة وصحة العمال أو بيئة العمل،بغرض تحليلها والتعرف على الآثار الناتجة عن استخدامها وتداولها، وإخطار المنشأة بذلك لاتخاذ ما يلزم فى هذا الشأن.
-٣ استخدام المعدات والأجهزة وآلات التصوير وغيرها أثناء التفتيش لتحليل أسباب الحوادث.
-٤ الاطلاع على خطط الطوارئ،وتحليل المخاطر الخاصة بالمنشأة.
-٥ الاطلاع على نتائج التقارير الفنية والإدارية التى ترد للمنشأة عن أنواع الحوادث الجسيمة وأسبابها.
-٦ الاطلاع على كميات المخزون من المواد الخطرة التى قد تهدد المنشأة. وعلى الجهة الإدارية المختصة بناء على تقرير جهاز تفتيش السلامة والصحة المهنية وتأمين بيئة العمل الأمر بإغلاق المنشأة كليا أو جزئيا،أو إيقاف آلة،أو أكثر، وذلك فى حالة وجود خطر داهم يهدد سلامة المنشأة،أو صحة العمال والمترددين، أو سلامة بيئة العمل حتى زوال أسباب الخطر،مع عدم الإخلال بحق العاملين فى تقاضي أجورهم.
وللجهة الإدارية المختصة بناء على قرار الإغلاق أن تقوم بإزالة أسباب الخطر بطريق التنفيذ المباشر على نفقة المنشأة. وينفذ القرار الصادر بالإغلاق أو الإيقاف بالطرق الإدارية. وتصدر الجهة الإدارية المختصة الأمر بإلغاء الإغلاق،أو الإيقاف فور زوال أسباب الخطر.$q517$, '2025-09-01', 'active' FROM ins_art_law14_257;

WITH ins_art_law14_258 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 258, $q518$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الثاني: التفتيش فى مجال السلامة$q518$, $q519$مع مراعاة حكم المادة ) (٢٤٢من هذا القانون،يكون لمفتشى السلامة والصحة المهنية وتأمين بيئة العمل حق التفتيش على المنشآت للتحقق من توافر اشتراطات السلامة والصحة المهنية وتأمين بيئة العمل تطبيق ًا لأحكام هذا القانون،والقرارات المنفذة له.$q519$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q519$مع مراعاة حكم المادة ) (٢٤٢من هذا القانون،يكون لمفتشى السلامة والصحة المهنية وتأمين بيئة العمل حق التفتيش على المنشآت للتحقق من توافر اشتراطات السلامة والصحة المهنية وتأمين بيئة العمل تطبيق ًا لأحكام هذا القانون،والقرارات المنفذة له.$q519$, '2025-09-01', 'active' FROM ins_art_law14_258;

WITH ins_art_law14_259 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 259, $q520$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الثالث: تنظيم أجهزة السلامة والصحة المهنية$q520$, $q521$يصدر الوزير المختص القرارات اللازمة بتحديد المنشآت،وفروعها، التى تلتزم بإنشاء أجهزة وظيفية للسلامة والصحة المهنية وتأمين بيئة العمل، واللجان المختصة بذلك. وتختص اللجان المشار إليها بالفقرة الأولى من هذه المادة ببحث ظروف العمل وأسباب حوادث وإصابات العمل وغيرها،ووضع القواعد،والاحتياطات الكفيلة بمنعها،وتكون قرارات هذه اللجان ملزمة للمنشأة وفروعها. ويجب أن يشمل التدريب العاملين بالجهاز الوظيفى للسلامة والصحة المهنية وتأمين بيئة العمل وأعضاء اللجان المختصة بذلك،والمسئولين عن الإدارة،والإنتاج بمستوياتهم كافة بما يتفق ومسئوليتهم،وطبيعة عملهم.$q521$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q521$يصدر الوزير المختص القرارات اللازمة بتحديد المنشآت،وفروعها، التى تلتزم بإنشاء أجهزة وظيفية للسلامة والصحة المهنية وتأمين بيئة العمل، واللجان المختصة بذلك. وتختص اللجان المشار إليها بالفقرة الأولى من هذه المادة ببحث ظروف العمل وأسباب حوادث وإصابات العمل وغيرها،ووضع القواعد،والاحتياطات الكفيلة بمنعها،وتكون قرارات هذه اللجان ملزمة للمنشأة وفروعها. ويجب أن يشمل التدريب العاملين بالجهاز الوظيفى للسلامة والصحة المهنية وتأمين بيئة العمل وأعضاء اللجان المختصة بذلك،والمسئولين عن الإدارة،والإنتاج بمستوياتهم كافة بما يتفق ومسئوليتهم،وطبيعة عملهم.$q521$, '2025-09-01', 'active' FROM ins_art_law14_259;

WITH ins_art_law14_260 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 260, $q522$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الثالث: تنظيم أجهزة السلامة والصحة المهنية$q522$, $q523$تلتزم كل منشأة يعمل بها ثلاثون عاملا ً فأكثر،بموافاة الجهة الإدارية المختصة بإحصائية نصف سنوية ببيانات حقيقية عن الأمراض العادية،والمزمنة، والحوادث الجسيمة،والإصابات،وذلك خلال النصف الأول من شهرى يوليو، ويناير على الأكثر. كما تلتزم المنشآت الخاضعة لأحكام هذا الكتاب،بإخطار الجهة الإدارية المختصة بكل حادث جسيم يقع بالمنشأة،أو عند ظهور أعراض مرض مهني، وذلك خلال أربع وعشرين ساعة من وقوعه،ويصدر الوزير المختص قرارا بالنماذج التى تستخدم لهذا الغرض. وتلتزم جميع المنشآت الخاضعة لأحكام هذا الكتاب بموافاة الوزارة المختصة إلكترونيا على المنصة الإلكترونية المعدة لذلك بكافة البيانات والتقارير والإحصائيات اللازمة والتى يصدر بتحديدها قرار من الوزير المختص،ويحدد القرار البيانات الأساسية المطلوبة لذلك.$q523$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q523$تلتزم كل منشأة يعمل بها ثلاثون عاملا ً فأكثر،بموافاة الجهة الإدارية المختصة بإحصائية نصف سنوية ببيانات حقيقية عن الأمراض العادية،والمزمنة، والحوادث الجسيمة،والإصابات،وذلك خلال النصف الأول من شهرى يوليو، ويناير على الأكثر. كما تلتزم المنشآت الخاضعة لأحكام هذا الكتاب،بإخطار الجهة الإدارية المختصة بكل حادث جسيم يقع بالمنشأة،أو عند ظهور أعراض مرض مهني، وذلك خلال أربع وعشرين ساعة من وقوعه،ويصدر الوزير المختص قرارا بالنماذج التى تستخدم لهذا الغرض. وتلتزم جميع المنشآت الخاضعة لأحكام هذا الكتاب بموافاة الوزارة المختصة إلكترونيا على المنصة الإلكترونية المعدة لذلك بكافة البيانات والتقارير والإحصائيات اللازمة والتى يصدر بتحديدها قرار من الوزير المختص،ويحدد القرار البيانات الأساسية المطلوبة لذلك.$q523$, '2025-09-01', 'active' FROM ins_art_law14_260;

WITH ins_art_law14_261 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 261, $q524$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الثالث: تنظيم أجهزة السلامة والصحة المهنية$q524$, $q525$تتولى الوزارة المختصة،والمركز القومى لدراسات السلامة والصحة المهنية وتأمين بيئة العمل المشار إليه فى المادة ) (٢٦٣من هذا القانون،والجهات التى يرخص لها،التدريب الأساسى،والمتقدم،والنوعى،والتخصصى للأخصائيين والفنيين،وأعضاء اللجان فى مجال السلامة والصحة المهنية. ويصدر الوزير المختص قرارا بقواعد منح التراخيص،ونظم التدريب فى الحالات السابقة فى مجال التدريب الأساسى،وتدريب السلامة والصحة المهنية والتدريب النوعي،والتخصصى،للكليات والمعاهد،والجمعيات الأهلية والشركات والمؤسسات المتخصصة،على أن يتضمن شروط منح الترخيص وإجراءاته،ومدته، والرسم المقرر عنه،بما لا يزيد على خمسين ألف جنيه،وحالات الإعفاء منه.$q525$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q525$تتولى الوزارة المختصة،والمركز القومى لدراسات السلامة والصحة المهنية وتأمين بيئة العمل المشار إليه فى المادة ) (٢٦٣من هذا القانون،والجهات التى يرخص لها،التدريب الأساسى،والمتقدم،والنوعى،والتخصصى للأخصائيين والفنيين،وأعضاء اللجان فى مجال السلامة والصحة المهنية. ويصدر الوزير المختص قرارا بقواعد منح التراخيص،ونظم التدريب فى الحالات السابقة فى مجال التدريب الأساسى،وتدريب السلامة والصحة المهنية والتدريب النوعي،والتخصصى،للكليات والمعاهد،والجمعيات الأهلية والشركات والمؤسسات المتخصصة،على أن يتضمن شروط منح الترخيص وإجراءاته،ومدته، والرسم المقرر عنه،بما لا يزيد على خمسين ألف جنيه،وحالات الإعفاء منه.$q525$, '2025-09-01', 'active' FROM ins_art_law14_261;

WITH ins_art_law14_262 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 262, $q526$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الثالث: تنظيم أجهزة السلامة والصحة المهنية$q526$, $q527$يشترط لمزاولة أعمال الخبرة والاستشارات فى مجال السلامة والصحة المهنية وتأمين بيئة العمل الحصول على الترخيص اللازم من الوزارة المختصة.
ويصدر الوزير المختص قرارا بتحديد شروط وقواعد،وإجراءات منح الترخيص،ومدته،وقيده فى السجل الورقى أو الإلكترونى المعد لهذا الغرض، والرسوم المقررة عنه بما لا يزيد على خمسين ألف جنيه،وحالات الإعفاء منه.$q527$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q527$يشترط لمزاولة أعمال الخبرة والاستشارات فى مجال السلامة والصحة المهنية وتأمين بيئة العمل الحصول على الترخيص اللازم من الوزارة المختصة.
ويصدر الوزير المختص قرارا بتحديد شروط وقواعد،وإجراءات منح الترخيص،ومدته،وقيده فى السجل الورقى أو الإلكترونى المعد لهذا الغرض، والرسوم المقررة عنه بما لا يزيد على خمسين ألف جنيه،وحالات الإعفاء منه.$q527$, '2025-09-01', 'active' FROM ins_art_law14_262;

WITH ins_art_law14_263 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 263, $q528$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الرابع: أجهزة البحوث والدراسات$q528$, $q529$يختص المركز القومى لدراسات السلامة والصحة المهنية وتأمين بيئة العمل المعاد تنظيمه بقرار رئيس الجمهورية رقم ۳۳۳لسنة ۲۰۰۳بالاشتراك مع الوزارة المختصة،بإعداد الخطط المركزية للبحوث والدراسات فى مجالات السلامة والصحة المهنية وتأمين بيئة العمل طبق ًا لنتائج التحليل الإحصائى لإصابات العمل بالمنشآت، ويتابع تنفيذها بالتنسيق مع الأجهزة المعنية فى الوزارة المختصة،وذلك وفق ًا للقواعد والإجراءات التى يصدر بها قرار من الوزير المختص.$q529$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q529$يختص المركز القومى لدراسات السلامة والصحة المهنية وتأمين بيئة العمل المعاد تنظيمه بقرار رئيس الجمهورية رقم ۳۳۳لسنة ۲۰۰۳بالاشتراك مع الوزارة المختصة،بإعداد الخطط المركزية للبحوث والدراسات فى مجالات السلامة والصحة المهنية وتأمين بيئة العمل طبق ًا لنتائج التحليل الإحصائى لإصابات العمل بالمنشآت، ويتابع تنفيذها بالتنسيق مع الأجهزة المعنية فى الوزارة المختصة،وذلك وفق ًا للقواعد والإجراءات التى يصدر بها قرار من الوزير المختص.$q529$, '2025-09-01', 'active' FROM ins_art_law14_263;

WITH ins_art_law14_264 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 264, $q530$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الرابع: أجهزة البحوث والدراسات$q530$, $q531$ينشأ مجلس يسمى "المجلس الأعلى للسلامة والصحة المهنية وتأمين بيئة العمل"، برئاسة الوزير المختص،وعضوية ممثلين عن الوزارات والجهات المختصة،وعدد متساو من ممثلى كل من منظمات أصحاب الأعمال المعنية الأكثر تمثيلا ً ترشحهم منظماتهم،وممثلى المنظمات النقابية العمالية المعنية الأكثر تمثيلا ً ترشحهم منظماتهم، على أن يراعى عند الترشيح تمثيل كافة مستويات المنظمات النقابية المعنية ما لم يتعذر ذلك،وعدد من ذوى الخبرة. ويتولى المجلس رسم السياسة العامة فى هذه المجالات واقتراح ما يلزم فى شأن تنفيذها بما يتفق مع السياسة العامة للدولة. ويصدر بتشكيل المجلس،واختصاصاته،ونظام العمل به قرار من رئيس مجلس الوزراء.$q531$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
