WITH ins_art_law14_265 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 265, $q532$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الرابع: أجهزة البحوث والدراسات$q532$, $q533$يشكل فى نطاق كل محافظة لجنة فرعية للمجلس الأعلى للسلامة والصحة المهنية وتأمين بيئة العمل،برئاسة المحافظ المختص،وتضم فى عضويتها ممثلين عن الوزارات والجهات المختصة،وممثلى المنظمات النقابية العمالية المعنية ترشحهم منظماتهم ما لم يتعذر ذلك،ومنظمات أصحاب الأعمال بالتساوى فيما بينهما،وعدد من ذوى الخبرة. ويصدر بتشكيلها،وتحديد اختصاصاتها،ونظام العمل بها قرار من الوزير المختص.$q533$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q533$يشكل فى نطاق كل محافظة لجنة فرعية للمجلس الأعلى للسلامة والصحة المهنية وتأمين بيئة العمل،برئاسة المحافظ المختص،وتضم فى عضويتها ممثلين عن الوزارات والجهات المختصة،وممثلى المنظمات النقابية العمالية المعنية ترشحهم منظماتهم ما لم يتعذر ذلك،ومنظمات أصحاب الأعمال بالتساوى فيما بينهما،وعدد من ذوى الخبرة. ويصدر بتشكيلها،وتحديد اختصاصاتها،ونظام العمل بها قرار من الوزير المختص.$q533$, '2025-09-01', 'active' FROM ins_art_law14_265;

WITH ins_art_law14_266 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 266, $q534$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الخامس: الخدمات الاجتماعية والصحية$q534$, $q535$مع عدم الإخلال بأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه، تلتزم المنشأة وفروعها بإجراء ما يأتي:
-١ الكشف الطبى الابتدائى على العامل قبل التحاقه بالعمل للتأكد من سلامته، ولياقته الصحية طبق ًا لنوع واحتياجات العمل الذى يسند إليه.
-٢ كشف القدرات للتأكد من لياقة العامل من ناحية قدراته الجسمانية والعقلية والنفسية بما يناسب احتياجات العمل. وتجرى هذه الفحوص طبق ًا للأحكام المنظمة للتأمين الصحى،ويصدر الوزير المختص بالاتفاق مع الوزير المعنى بشئون الصحة قرارا بتحديد مستويات اللياقة والسلامة الصحية والقدرات العقلية والنفسية التى تتم على أساسها هذه الفحوص.$q535$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q535$مع عدم الإخلال بأحكام قانون التأمينات الاجتماعية والمعاشات المشار إليه، تلتزم المنشأة وفروعها بإجراء ما يأتي:
-١ الكشف الطبى الابتدائى على العامل قبل التحاقه بالعمل للتأكد من سلامته، ولياقته الصحية طبق ًا لنوع واحتياجات العمل الذى يسند إليه.
-٢ كشف القدرات للتأكد من لياقة العامل من ناحية قدراته الجسمانية والعقلية والنفسية بما يناسب احتياجات العمل. وتجرى هذه الفحوص طبق ًا للأحكام المنظمة للتأمين الصحى،ويصدر الوزير المختص بالاتفاق مع الوزير المعنى بشئون الصحة قرارا بتحديد مستويات اللياقة والسلامة الصحية والقدرات العقلية والنفسية التى تتم على أساسها هذه الفحوص.$q535$, '2025-09-01', 'active' FROM ins_art_law14_266;

WITH ins_art_law14_267 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 267, $q536$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الخامس: الخدمات الاجتماعية والصحية$q536$, $q537$تلتزم المنشأة وفروعها بما يأتي:
-١ تدريب العامل على الأسس السليمة لأداء مهنته.
-۲ إحاطة العامل قبل مزاولة العمل بمخاطر مهنته،وإلزامه باستخدام وسائل الوقاية المقررة لها مع توفير أدوات الوقاية الشخصية المناسبة وتدريبه على استخدامها. ولا يجوز للمنشأة أن تحمل العامل أية نفقات أو تقتطع من أجره أى مبالغ لقاء توفير وسائل الحماية اللازمة له.$q537$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q537$تلتزم المنشأة وفروعها بما يأتي:
-١ تدريب العامل على الأسس السليمة لأداء مهنته.
-۲ إحاطة العامل قبل مزاولة العمل بمخاطر مهنته،وإلزامه باستخدام وسائل الوقاية المقررة لها مع توفير أدوات الوقاية الشخصية المناسبة وتدريبه على استخدامها. ولا يجوز للمنشأة أن تحمل العامل أية نفقات أو تقتطع من أجره أى مبالغ لقاء توفير وسائل الحماية اللازمة له.$q537$, '2025-09-01', 'active' FROM ins_art_law14_267;

WITH ins_art_law14_268 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 268, $q538$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الخامس: الخدمات الاجتماعية والصحية$q538$, $q539$يلتزم العامل بأن يستعمل وسائل الوقاية،ويتعهد بالعناية بما فى حوزته منها، وبتنفيذ التعليمات الصادرة للمحافظة على صحته ووقايته من حوادث العمل،وعليه ألا يرتكب أى فعل يقصد به منع تنفيذ التعليمات أو إساءة استعمال الوسائل الموضوعة لحمايته وسلامة العمال المشتغلين معه أو تغييرها أو إلحاق ضرر أو تلف بها،وذلك دون الإخلال بما يفرضه أى قانون آخر فى هذا الشأن.$q539$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q539$يلتزم العامل بأن يستعمل وسائل الوقاية،ويتعهد بالعناية بما فى حوزته منها، وبتنفيذ التعليمات الصادرة للمحافظة على صحته ووقايته من حوادث العمل،وعليه ألا يرتكب أى فعل يقصد به منع تنفيذ التعليمات أو إساءة استعمال الوسائل الموضوعة لحمايته وسلامة العمال المشتغلين معه أو تغييرها أو إلحاق ضرر أو تلف بها،وذلك دون الإخلال بما يفرضه أى قانون آخر فى هذا الشأن.$q539$, '2025-09-01', 'active' FROM ins_art_law14_268;

WITH ins_art_law14_269 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 269, $q540$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الخامس: الخدمات الاجتماعية والصحية$q540$, $q541$تلتزم المنشأة وفروعها بإجراء ما يأتي:
-١ التفتيش الدورى اليومى فى كل وردية عمل على أماكن العمل وخاصة الخطرة منها لاكتشاف المخاطر المهنية،والعمل على الوقاية منها،وإعداد سجل ورقى أو إلكترونى لهذا الغرض.
-۲ فحص شكوى العامل المرضية،ومعرفة علاقتها بنوع العمل بمعرفة طبيب المنشأة،إن وجد.
-٣ التنسيق مع الهيئة العامة للتأمين الصحى لإجراء الفحص الطبى الدورى لجميع عمال المنشأة للمحافظة على لياقتهم الصحية والنفسية والعقلية، وسلامتهم بصفة مستمرة واكتشاف ما يظهر من أمراض مهنية فى مراحلها الأولى ولإجراء الفحص عند انتهاء الخدمة،وذلك كله طبق ًا لأنظمة التأمين الصحى المقررة فى هذا الشأن.$q541$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q541$تلتزم المنشأة وفروعها بإجراء ما يأتي:
-١ التفتيش الدورى اليومى فى كل وردية عمل على أماكن العمل وخاصة الخطرة منها لاكتشاف المخاطر المهنية،والعمل على الوقاية منها،وإعداد سجل ورقى أو إلكترونى لهذا الغرض.
-۲ فحص شكوى العامل المرضية،ومعرفة علاقتها بنوع العمل بمعرفة طبيب المنشأة،إن وجد.
-٣ التنسيق مع الهيئة العامة للتأمين الصحى لإجراء الفحص الطبى الدورى لجميع عمال المنشأة للمحافظة على لياقتهم الصحية والنفسية والعقلية، وسلامتهم بصفة مستمرة واكتشاف ما يظهر من أمراض مهنية فى مراحلها الأولى ولإجراء الفحص عند انتهاء الخدمة،وذلك كله طبق ًا لأنظمة التأمين الصحى المقررة فى هذا الشأن.$q541$, '2025-09-01', 'active' FROM ins_art_law14_269;

WITH ins_art_law14_270 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 270, $q542$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الخامس: الخدمات الاجتماعية والصحية$q542$, $q543$تلتزم المنشأة بأن توفر لعمالها وسائل الإسعاف الأولية. وإذا زاد عدد عمال المنشأة فى مكان واحد أو بلد واحد أو فى دائرة نصف قطرها خمسة عشر كيلو مترا على خمسين عاملا ً،تلتزم المنشأة بأن تستخدم ممرضا مؤهلا ً أو أكثر الأعمال التمريض أو الإسعاف بكل وردية عمل بها،وأن تعهد إلى طبيب لعيادتهم فى المكان الذى تعده لهذا الغرض،وأن تقدم لهم الأدوية اللازمة للعلاج،وذلك كله بالمجان.
وإذا عولج العامل فى الحالتين المنصوص عليهما فى الفقرتين الأولى والثانية من هذه المادة بمستشفى حكومى أو خيرى،وجب على المنشأة أن تؤدى إلى إدارة المستشفى نفقات العلاج،والأدوية،والإقامة. ويتبع فى تحديد نفقات العلاج،والأدوية،والإقامة المنصوص عليها فى الفقرات السابقة الطرق والأوضاع التى يصدر بها قرار من الوزير المختص بالاتفاق مع الوزير المعنى بشئون الصحة.$q543$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q543$تلتزم المنشأة بأن توفر لعمالها وسائل الإسعاف الأولية. وإذا زاد عدد عمال المنشأة فى مكان واحد أو بلد واحد أو فى دائرة نصف قطرها خمسة عشر كيلو مترا على خمسين عاملا ً،تلتزم المنشأة بأن تستخدم ممرضا مؤهلا ً أو أكثر الأعمال التمريض أو الإسعاف بكل وردية عمل بها،وأن تعهد إلى طبيب لعيادتهم فى المكان الذى تعده لهذا الغرض،وأن تقدم لهم الأدوية اللازمة للعلاج،وذلك كله بالمجان.
وإذا عولج العامل فى الحالتين المنصوص عليهما فى الفقرتين الأولى والثانية من هذه المادة بمستشفى حكومى أو خيرى،وجب على المنشأة أن تؤدى إلى إدارة المستشفى نفقات العلاج،والأدوية،والإقامة. ويتبع فى تحديد نفقات العلاج،والأدوية،والإقامة المنصوص عليها فى الفقرات السابقة الطرق والأوضاع التى يصدر بها قرار من الوزير المختص بالاتفاق مع الوزير المعنى بشئون الصحة.$q543$, '2025-09-01', 'active' FROM ins_art_law14_270;

WITH ins_art_law14_271 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 271, $q544$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الخامس: الخدمات الاجتماعية والصحية$q544$, $q545$يلتزم من يستخدم عمالا ً فى أماكن لا تصل إليها وسائل المواصلات العادية أن يوفر لهم وسائل الانتقال المناسبة على نفقته الخاصة. وعلى من يستخدم عمالا ً فى المناطق البعيدة عن العمران أن يوفر لهم التغذية المناسبة،والمساكن الملائمة مع مراعاة تخصيص بعضها للعمال المتزوجين على نفقته الخاصة. ويصدر الوزير المختص بالاتفاق مع الوزراء المعنيين،ومع منظمات أصحاب الأعمال والعمال القرارات اللازمة لتحديد المناطق البعيدة عن العمران،واشتراطات ومواصفات المساكن،وتعيين أصناف الطعام والكميات التى تقدم منها لكل عامل، وما يؤديه صاحب العمل مقابلا ً لها. ويجوز بالنسبة لنظام الوجبات الغذائية الواردة فى الفقرة الثالثة من هذه المادة الأخذ بنظام توافق عليه إدارة المنشأة والمنظمة النقابية العمالية أو المفوض العمالى فى حالة عدم وجودها،بشرط أن يعتمد من الجهة الإدارية المختصة،ويحظر الاستعاضة عن تقديم تلك الوجبات كلها أو بعضها بمقابل نقدى.$q545$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q545$يلتزم من يستخدم عمالا ً فى أماكن لا تصل إليها وسائل المواصلات العادية أن يوفر لهم وسائل الانتقال المناسبة على نفقته الخاصة. وعلى من يستخدم عمالا ً فى المناطق البعيدة عن العمران أن يوفر لهم التغذية المناسبة،والمساكن الملائمة مع مراعاة تخصيص بعضها للعمال المتزوجين على نفقته الخاصة. ويصدر الوزير المختص بالاتفاق مع الوزراء المعنيين،ومع منظمات أصحاب الأعمال والعمال القرارات اللازمة لتحديد المناطق البعيدة عن العمران،واشتراطات ومواصفات المساكن،وتعيين أصناف الطعام والكميات التى تقدم منها لكل عامل، وما يؤديه صاحب العمل مقابلا ً لها. ويجوز بالنسبة لنظام الوجبات الغذائية الواردة فى الفقرة الثالثة من هذه المادة الأخذ بنظام توافق عليه إدارة المنشأة والمنظمة النقابية العمالية أو المفوض العمالى فى حالة عدم وجودها،بشرط أن يعتمد من الجهة الإدارية المختصة،ويحظر الاستعاضة عن تقديم تلك الوجبات كلها أو بعضها بمقابل نقدى.$q545$, '2025-09-01', 'active' FROM ins_art_law14_271;

WITH ins_art_law14_272 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 272, $q546$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الخامس: الخدمات الاجتماعية والصحية$q546$, $q547$تلتزم المنشأة التى يبلغ عدد عمالها خمسين عاملا ً فأكثر بتقديم الخدمات الاجتماعية والثقافية اللازمة لعمالها،وذلك بالاشتراك مع المنظمة النقابية العمالية، دون تحميل العامل أى التزامات،ويصدر الوزير المختص بالتشاور مع منظمات أصحاب الأعمال والعمال القرارات المشار إليها بتحديد الحد الأدنى لهذه الخدمات.$q547$
