WITH ins_art_law14_273 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 273, $q548$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الخامس: الخدمات الاجتماعية والصحية$q548$, $q549$يتمتع صندوق الخدمات الاجتماعية والصحية والثقافية بالشخصية الاعتبارية، ويهدف إلى تقديم الخدمات اللازمة للنهوض بالمستوى الاجتماعى والصحى والثقافى للعاملين بمنشآت القطاع العام،وقطاع الأعمال العام،والقطاع الخاص. ويصدر رئيس مجلس الوزراء قرارا بتشكيل مجلس إدارة الصندوق برئاسة الوزير المختص،وعضوية ممثلى المنظمات النقابية العمالية المعنية ومنظمات أصحاب الأعمال بالتساوى فيما بينهما،ترشحهم منظماتهم،وممثلى الوزارات والجهات المعنية ويحدد القرار اختصاصات المجلس والنظام الأساسى للصندوق والمعاملة المالية لرئيس وأعضاء مجلس الإدارة،على أن تكون من موارده الذاتية، والنظام المحاسبى الواجب إتباعه. ويكون للصندوق حساب خاص لدى أحد البنوك التجارية المسجلة لدى البنك المركزى المصرى،وموازنة مستقلة،ويعد الصندوق سنويا القوائم الدالة على المركز المالى وفق ًا لنظام المحاسبة المالية،وتبدأ السنة المالية للصندوق مع السنة المالية للدولة،وتنتهى بانتهائها وتخضع أمواله لرقابة الجهاز المركزى للمحاسبات، ويرحل فائض أمواله من سنة إلى أخرى. وتلتزم المنشآت المشار إليها بالفقرة الأولى من هذه المادة والتى يبلغ عدد عمالها عشرون عاملا ً فأكثر بسداد اشتراك سنوى لا يقل عن ثمانية جنيهات ولا يجاوز ستة عشر جنيها عن كل عامل سنويا لتمويل هذا الصندوق،ويصدر بتحديد قيمة الاشتراك السنوى قرار من الوزير المختص،بعد العرض على مجلس إدارة الصندوق،ويحق للمنشأة حال تقديمها للخدمات الواردة بالمادة ٢٧٤من هذا القانون،أو تقديمها لميزة أفضل للعاملين لديها خصم قيمة تلك الخدمات أو الميزة أو خصم ) (٪۷۰من المبلغ المستحق عليها للصندوق سنويا،أيهما أقل.$q549$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q549$يتمتع صندوق الخدمات الاجتماعية والصحية والثقافية بالشخصية الاعتبارية، ويهدف إلى تقديم الخدمات اللازمة للنهوض بالمستوى الاجتماعى والصحى والثقافى للعاملين بمنشآت القطاع العام،وقطاع الأعمال العام،والقطاع الخاص. ويصدر رئيس مجلس الوزراء قرارا بتشكيل مجلس إدارة الصندوق برئاسة الوزير المختص،وعضوية ممثلى المنظمات النقابية العمالية المعنية ومنظمات أصحاب الأعمال بالتساوى فيما بينهما،ترشحهم منظماتهم،وممثلى الوزارات والجهات المعنية ويحدد القرار اختصاصات المجلس والنظام الأساسى للصندوق والمعاملة المالية لرئيس وأعضاء مجلس الإدارة،على أن تكون من موارده الذاتية، والنظام المحاسبى الواجب إتباعه. ويكون للصندوق حساب خاص لدى أحد البنوك التجارية المسجلة لدى البنك المركزى المصرى،وموازنة مستقلة،ويعد الصندوق سنويا القوائم الدالة على المركز المالى وفق ًا لنظام المحاسبة المالية،وتبدأ السنة المالية للصندوق مع السنة المالية للدولة،وتنتهى بانتهائها وتخضع أمواله لرقابة الجهاز المركزى للمحاسبات، ويرحل فائض أمواله من سنة إلى أخرى. وتلتزم المنشآت المشار إليها بالفقرة الأولى من هذه المادة والتى يبلغ عدد عمالها عشرون عاملا ً فأكثر بسداد اشتراك سنوى لا يقل عن ثمانية جنيهات ولا يجاوز ستة عشر جنيها عن كل عامل سنويا لتمويل هذا الصندوق،ويصدر بتحديد قيمة الاشتراك السنوى قرار من الوزير المختص،بعد العرض على مجلس إدارة الصندوق،ويحق للمنشأة حال تقديمها للخدمات الواردة بالمادة ٢٧٤من هذا القانون،أو تقديمها لميزة أفضل للعاملين لديها خصم قيمة تلك الخدمات أو الميزة أو خصم ) (٪۷۰من المبلغ المستحق عليها للصندوق سنويا،أيهما أقل.$q549$, '2025-09-01', 'active' FROM ins_art_law14_273;

WITH ins_art_law14_274 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 274, $q550$الكتاب الرابع: السلامة والصحة المهنية وتأمين بيئة العمل — الباب الخامس: الخدمات الاجتماعية والصحية$q550$, $q551$يلتزم الصندوق المشار إليه فى المادة ) (٢٧٣من هذا القانون بتقديم الخدمات الآتية:
-١ دعم النفقات العلاجية طبق ًا لما تحدده اللائحة المالية والإدارية للصندوق والتى تحدد أنواع الخدمات الطبية والمنتفعين بها واللجان المختصة بتقرير العلاج والجهات التى تتولى تنفيذ الخدمات الصحية.
-۲ تدعيم مكتبات المنشآت بالكتب.
-٣ عقد الندوات الثقافية أو تمويلها.
-٤ دعم تكاليف تنظيم انتخابات المنظمات النقابية العمالية.
-٥ إعداد برامج محو الأمية بالتعاون مع الجهات المختصة.
-٦ تدعيم الأنشطة الرياضية بالمنشأة.
-٧ إقامة المسابقات اللازمة لتنمية مهارات العاملين فنيا وثقافيا ورياضيا.
-٨ إعداد برامج الرحلات الترفيهية،والمصايف طبق ًا لإمكانيات العمال.
-٩ دعم الأنشطة النقابية العمالية.
-١٠ مشاركة العمال وأصحاب العمل فى توفير بيئة عمل آمنة خالية من العنف والتحرش والتنمر من خلال إقامة الندوات التوعوية وتمويل المشروعات التنموية التى تستهدف ذلك متى توافرت الموارد. وللوزير المختص بالاتفاق مع مجلس إدارة الصندوق إضافة خدمات أخرى على أن تكون فى ذات مجال عمل الصندوق. ويصدر رئيس مجلس الوزراء قرارا باللائحة المالية والإدارية للصندوق، وصلاحيات وضوابط الصرف والرقابة عليها.$q551$
  FROM laws WHERE law_no = 14 AND law_year = 2025
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
