-- ===== law155: قانون التأمين الموحد الصادر بالقانون رقم 155 لسنة 2024 (224 مادة) =====
INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at)
VALUES (155, 2024, $q600$قانون التأمين الموحد الصادر بالقانون رقم 155 لسنة 2024$q600$, $q601$قانون التأمين الموحد$q601$, 'insurance', 'in_force', $q602$https://www.eastlaws.com/legislation-full-text/ar/egypt/law/10-07-2024/no-155?type=1&id=2137149&sub=11127287$q602$, '2024-07-10')
ON CONFLICT (law_no, law_year) DO NOTHING;

WITH ins_art_law155_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, NULL, $q604$تعريفات: في تطبيق أحكام هذا القانون،يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها: الهيئة:الهيئة العامة للرقابة المالية. عقد التأمين:عقد يلتزم المؤمن بمقتضاه أن يؤدى إلى المؤمن له أو إلى المستفيد الذي اشترط التأمين لصالحه مبلغ ًا من المال أو إيرادا مرتبا أو أى عوض مالى آخر في حالة وقوع الحادث أو تحقق الخطر المبين بالعقد وذلك نظير قسط أو أقساط دورية أو أية دفعات مالية أخرى يؤديها المؤمن له للمؤمن،ويشار إليه بلا وثيقة. عقد إعادة التأمين:عقد يلتزم بمقتضاه معيد التأمين بأن يعوض الطرف الثاني المؤمن وهو شركة التأمين عن كل أو جزء من الخسارة التي يتحملها بموجب عقد التأمين الأصلي،وذلك في مقابل التزام الطرف الثاني بسداد قسط إعادة التأمين إلى معيد التأمين. عقد التأمين التكافلي:عقد يهدف إلى تحقيق التعاون بين مجموعة من المشتركين يتعرضون لخطر واحد أو أخطار معينة،حيث يقوم كل منهم بدفع مبلغ مالى على سبيل التبرع يسمى الاشتراك بما يؤدى إلى تكوين صندوق يسمى صندوق المشتركين يتم من خلاله دفع التعويض لمن يستحقه،ويكون هذا الصندوق منفصلا ً بشكل تام عن حسابات شركة التأمين التكافلي المتضمنة حسابات المساهمين. الفائض التأميني في مجال التأمين التكافلي:ما تبقى من صافى أقساط المشتركين المؤمن لهم وعوائدها والإيرادات الأخرى المتعلقة بوثائق التأمين بعد خصم جميع المصروفات وصافى التعويضات المدفوعة والمخصصات الفنية خلال السنة.
تأمينات الحياة:جميع عمليات التأمين التي يكون فيها الخطر المؤمن ضده يتعلق بحياة الأشخاص،ويكون الغرض منها دفع مبالغ بسبب وفاة شخص معين أو عجزه عجزا كليا أو جزئيا دائما أو مؤقت ًا أو بلوغه سن ًا معينة أو ضمان معاش يدفع له أو للمستفيدين منه مدى الحياة أو خلال فترة محددة،كما يشمل أيضا ذات التأمينات التي ترتبط المزايا الخاصة بها باستثمارات في الأوراق والأدوات المالية. تأمينات الحوادث الشخصية طويلة الأجل:جميع عمليات التأمين التي تزيد مدتها على سنة،والتي يكون فيها الخطر المؤمن ضده متعلق ًا بالشخص وناتجا عن حادث وترتب عنه الوفاة أو العجز. تأمينات العلاج الطبي طويلة الأجل:جميع عمليات التأمين التي تزيد مدتها على سنة،ويكون الغرض منها صرف مزايا نقدية للأشخاص المؤمن عليهم في حالات العجز الناتج عن المرض،وكذا تغطية تكاليف العلاج الطبي. نشاط شركات إدارة برامج الرعاية الصحية:النشاط الذى تتولى من خلاله الشركة مسئولية جميع الأعمال الإدارية المرتبطة بوثائق التأمين الطبي التي تصدرها شركات التأمين،وذلك كطرف ثالث بين شركة التأمين والعميل،وذلك على النحو الذي تحدده الهيئة. عمليات تكوين الأموال:العمليات التي يكون الغرض منها تكوين مال من مشتركين يصرف فى تاريخ محدد مقابل قسط أو أقساط دورية،دون أن يرتبط ذلك باحتمالات الحياة أو الوفاة. الأطراف المرتبطة:الأشخاص الذين يجمع بينهم اتفاق بغرض الاستحواذ أو السيطرة الفعلية على إحدى الشركات الخاضعة لأحكام هذا القانون،سواء كان هذا الاتفاق مكتوبا أو غير مكتوب. ويعد من الأطراف المرتبطة الأشخاص الطبيعيون وأى من أزواجهم وأقاربهم حتى الدرجة الثانية،والأشخاص الاعتبارية والكيانات والاتحادات والروابط والتجمعات المالية المكونة من شخصين أو أكثر والتي تكون غالبية أسهم أو حصص إحداها مملوكة مباشرة أو بطريق غير مباشر للطرف الآخر أو يكون مالكها شخصا واحدا،كما يعد من الأطراف المرتبطة الأشخاص الخاضعون للسيطرة الفعلية لشخص آخر.
صندوق التأمين الخاص:كل نظام بين مجموعة من الأفراد تربطهم مهنة أو عمل واحد أو أي صلة اجتماعية أخرى ويتألف بغير رأسمال،ويكون الغرض منه أن يؤدى إلى أعضائه أو المستفيدين منه تعويضات أو مزايا تأمينية أو اجتماعية أو معاشات دورية وفق ًا لنظامه الأساسي المعتمد من الهيئة والضوابط أو المعايير التي يصدرها مجلس إدارة الهيئة. صناديق التأمين الحكومية:الصناديق التي تتولى عمليات التأمين ضد الأخطار التى لا تقبلها عادة شركات التأمين أو تلك التي ترى الحكومة مزاولتها بنفسها لهدف قومي أو اجتماعي. نظام المزايا المحددة:النظام الذي تحدد فيه الميزة التأمينية سلف ًا من خلال دراسة اكتوارية للمركز المالي للصندوق بما يكفل تحقيق التوازن بين المزايا والموارد. نظام الاشتراكات المحددة:النظام الذي تحدد فيه حقوق المشترك بالرصيد التراكمي المتجمع في حسابه عند الاستحقاق،ولا تكون فيه المزايا محددة مسبق ًا. النظام المختلط:النظام الذي يجمع بين نظامي المزايا المحددة والاشتراكات المحددة. الحوسبة السحابية:النموذج الذي يمكن من الوصول الشبكي من أي مكان وبشكل مناسب وعند الطلب إلى مجموعة مشتركة من المصادر المادية أو الافتراضية كالشبكات والخوادم ووسائط التخزين والتطبيقات والخدمات التي يمكن توفيرها بسرعة واستخدامها بأقل جهد أو السداد الإلكتروني أو الأنشطة والإعلانات الإلكترونية الخاصة بأى من المنشآت أو الأفراد الخاضعين لإشراف ورقابة الهيئة بما في ذلك آليات ضمان حماية بيانات العملاء وسهولة استرجاعها وقواعد وضوابط الرقابة عليها من الهيئة. مجمعة التأمين:كيانات تؤسسها مجموعة من شركات التأمين أو إعادة التأمين بهدف الاكتتاب في أخطار معينة. الكيان:أى شركة أو منشأة أو مؤسسة أيا كان شكلها القانوني،مصرية أو أجنبية،تسيطر أو تستحوذ بشكل مباشر أو غير مباشر على نسبة ) (٪١٠أو أكثر من حجم نشاط التأمين بالسوق،أو يمثل نشاط التأمين بالنسبة لها وما يرتبط به من خدمات نسبة تزيد على ) (٪٥٠من ملكية شركاتها التابعة داخل جمهورية مصر العربية التي تعمل في تلك الأنشطة أو الخدمات.$q604$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q604$تعريفات: في تطبيق أحكام هذا القانون،يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها: الهيئة:الهيئة العامة للرقابة المالية. عقد التأمين:عقد يلتزم المؤمن بمقتضاه أن يؤدى إلى المؤمن له أو إلى المستفيد الذي اشترط التأمين لصالحه مبلغ ًا من المال أو إيرادا مرتبا أو أى عوض مالى آخر في حالة وقوع الحادث أو تحقق الخطر المبين بالعقد وذلك نظير قسط أو أقساط دورية أو أية دفعات مالية أخرى يؤديها المؤمن له للمؤمن،ويشار إليه بلا وثيقة. عقد إعادة التأمين:عقد يلتزم بمقتضاه معيد التأمين بأن يعوض الطرف الثاني المؤمن وهو شركة التأمين عن كل أو جزء من الخسارة التي يتحملها بموجب عقد التأمين الأصلي،وذلك في مقابل التزام الطرف الثاني بسداد قسط إعادة التأمين إلى معيد التأمين. عقد التأمين التكافلي:عقد يهدف إلى تحقيق التعاون بين مجموعة من المشتركين يتعرضون لخطر واحد أو أخطار معينة،حيث يقوم كل منهم بدفع مبلغ مالى على سبيل التبرع يسمى الاشتراك بما يؤدى إلى تكوين صندوق يسمى صندوق المشتركين يتم من خلاله دفع التعويض لمن يستحقه،ويكون هذا الصندوق منفصلا ً بشكل تام عن حسابات شركة التأمين التكافلي المتضمنة حسابات المساهمين. الفائض التأميني في مجال التأمين التكافلي:ما تبقى من صافى أقساط المشتركين المؤمن لهم وعوائدها والإيرادات الأخرى المتعلقة بوثائق التأمين بعد خصم جميع المصروفات وصافى التعويضات المدفوعة والمخصصات الفنية خلال السنة.
تأمينات الحياة:جميع عمليات التأمين التي يكون فيها الخطر المؤمن ضده يتعلق بحياة الأشخاص،ويكون الغرض منها دفع مبالغ بسبب وفاة شخص معين أو عجزه عجزا كليا أو جزئيا دائما أو مؤقت ًا أو بلوغه سن ًا معينة أو ضمان معاش يدفع له أو للمستفيدين منه مدى الحياة أو خلال فترة محددة،كما يشمل أيضا ذات التأمينات التي ترتبط المزايا الخاصة بها باستثمارات في الأوراق والأدوات المالية. تأمينات الحوادث الشخصية طويلة الأجل:جميع عمليات التأمين التي تزيد مدتها على سنة،والتي يكون فيها الخطر المؤمن ضده متعلق ًا بالشخص وناتجا عن حادث وترتب عنه الوفاة أو العجز. تأمينات العلاج الطبي طويلة الأجل:جميع عمليات التأمين التي تزيد مدتها على سنة،ويكون الغرض منها صرف مزايا نقدية للأشخاص المؤمن عليهم في حالات العجز الناتج عن المرض،وكذا تغطية تكاليف العلاج الطبي. نشاط شركات إدارة برامج الرعاية الصحية:النشاط الذى تتولى من خلاله الشركة مسئولية جميع الأعمال الإدارية المرتبطة بوثائق التأمين الطبي التي تصدرها شركات التأمين،وذلك كطرف ثالث بين شركة التأمين والعميل،وذلك على النحو الذي تحدده الهيئة. عمليات تكوين الأموال:العمليات التي يكون الغرض منها تكوين مال من مشتركين يصرف فى تاريخ محدد مقابل قسط أو أقساط دورية،دون أن يرتبط ذلك باحتمالات الحياة أو الوفاة. الأطراف المرتبطة:الأشخاص الذين يجمع بينهم اتفاق بغرض الاستحواذ أو السيطرة الفعلية على إحدى الشركات الخاضعة لأحكام هذا القانون،سواء كان هذا الاتفاق مكتوبا أو غير مكتوب. ويعد من الأطراف المرتبطة الأشخاص الطبيعيون وأى من أزواجهم وأقاربهم حتى الدرجة الثانية،والأشخاص الاعتبارية والكيانات والاتحادات والروابط والتجمعات المالية المكونة من شخصين أو أكثر والتي تكون غالبية أسهم أو حصص إحداها مملوكة مباشرة أو بطريق غير مباشر للطرف الآخر أو يكون مالكها شخصا واحدا،كما يعد من الأطراف المرتبطة الأشخاص الخاضعون للسيطرة الفعلية لشخص آخر.
صندوق التأمين الخاص:كل نظام بين مجموعة من الأفراد تربطهم مهنة أو عمل واحد أو أي صلة اجتماعية أخرى ويتألف بغير رأسمال،ويكون الغرض منه أن يؤدى إلى أعضائه أو المستفيدين منه تعويضات أو مزايا تأمينية أو اجتماعية أو معاشات دورية وفق ًا لنظامه الأساسي المعتمد من الهيئة والضوابط أو المعايير التي يصدرها مجلس إدارة الهيئة. صناديق التأمين الحكومية:الصناديق التي تتولى عمليات التأمين ضد الأخطار التى لا تقبلها عادة شركات التأمين أو تلك التي ترى الحكومة مزاولتها بنفسها لهدف قومي أو اجتماعي. نظام المزايا المحددة:النظام الذي تحدد فيه الميزة التأمينية سلف ًا من خلال دراسة اكتوارية للمركز المالي للصندوق بما يكفل تحقيق التوازن بين المزايا والموارد. نظام الاشتراكات المحددة:النظام الذي تحدد فيه حقوق المشترك بالرصيد التراكمي المتجمع في حسابه عند الاستحقاق،ولا تكون فيه المزايا محددة مسبق ًا. النظام المختلط:النظام الذي يجمع بين نظامي المزايا المحددة والاشتراكات المحددة. الحوسبة السحابية:النموذج الذي يمكن من الوصول الشبكي من أي مكان وبشكل مناسب وعند الطلب إلى مجموعة مشتركة من المصادر المادية أو الافتراضية كالشبكات والخوادم ووسائط التخزين والتطبيقات والخدمات التي يمكن توفيرها بسرعة واستخدامها بأقل جهد أو السداد الإلكتروني أو الأنشطة والإعلانات الإلكترونية الخاصة بأى من المنشآت أو الأفراد الخاضعين لإشراف ورقابة الهيئة بما في ذلك آليات ضمان حماية بيانات العملاء وسهولة استرجاعها وقواعد وضوابط الرقابة عليها من الهيئة. مجمعة التأمين:كيانات تؤسسها مجموعة من شركات التأمين أو إعادة التأمين بهدف الاكتتاب في أخطار معينة. الكيان:أى شركة أو منشأة أو مؤسسة أيا كان شكلها القانوني،مصرية أو أجنبية،تسيطر أو تستحوذ بشكل مباشر أو غير مباشر على نسبة ) (٪١٠أو أكثر من حجم نشاط التأمين بالسوق،أو يمثل نشاط التأمين بالنسبة لها وما يرتبط به من خدمات نسبة تزيد على ) (٪٥٠من ملكية شركاتها التابعة داخل جمهورية مصر العربية التي تعمل في تلك الأنشطة أو الخدمات.$q604$, '2024-07-11', 'active' FROM ins_art_law155_1;

WITH ins_art_law155_2 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 2, NULL, $q606$تكون مزاولة نشاط التأمين في جمهورية مصر العربية طبق ًا للأنواع والفروع التالية: ً أولا -تأمينات الأشخاص وعمليات تكوين الأموال،وتتمثل في الفروع الآتية:
-١ تأمينات الحياة.
-٢ تأمينات الحوادث الشخصية طويلة الأجل.
-٣ تأمينات العلاج الطبي طويل الأجل.
-٤ تأمين دفعات التقاعد.
-٥ عمليات تكوين الأموال. ً ثانيا -تأمينات الممتلكات والمسئوليات،وتتمثل في الفروع الآتية:
-١ التأمين ضد أخطار الحريق والأخطار المرتبطة به.
-٢ التأمين ضد أخطار النقل بأنواعه البرى والنهرى والبحرى والجوى وتأمينات المسئوليات المتعلقة بها.
-٣ التأمين على أجسام السفن وآلاتها ومهماتها وتأمينات المسئوليات المتعلقة بها.
-٤ التأمين على أجسام الطائرات وآلاتها ومهماتها وتأمينات المسئوليات المتعلقة بها.
-٥ التأمين التكميلى على المركبات والمسئوليات المتعلقة بها.
-٦ التأمين الإلزامي ضد المسئولية المدنية الناشئة عن حوادث مركبات النقل السريع.
-٧ التأمين ضد الأخطار الهندسية وتأمينات المسئوليات المتعلقة بها.
-٨ تأمينات البترول والمسئوليات المتعلقة بها.
-٩ تأمينات الطاقة والمسئوليات المتعلقة بها.
-١٠ التأمينات الزراعية والمسئوليات والأخطار المرتبطة بها.
-١١ التأمين ضد أخطار الحوادث المتنوعة والمسئوليات.
-١٢ التأمين ضد مخاطر عدم السداد.
-١٣ تأمينات العلاج الطبي قصير الأجل.
-١٤ التأمين ضد المخاطر الإلكترونية. ً ثالثا -التأمين الطبي المتخصص بنوعيه طويل وقصير الأجل وما يرتبط بهما من خدمات وأنشطة. ً رابعا -التأمين متناهى الصغر: وللهيئة أن ترخص بممارسة أى من الأنواع السابقة بأسلوب التأمين التكافلي، وذلك وفق ًا للأحكام الواردة في هذا القانون. ويجوز لها أن ترخص بإنشاء شركات تأمين متخصصة في أحد فروع التأمين، وذلك وفق ًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة على ألا يقل رأسمالها عن الحد المقرر بالنسبة لشركات التأمين الطبي المتخصصة. ويصدر عن مجلس إدارة الهيئة قرار بتحديد ماهية كل من التأمين الطبي وتأمينات الحوادث الشخصية طويلة وقصيرة الأجل،كما يكون للمجلس أن يصدر قرارا بتحديد أنواع تأمينات أخرى وفروع لها.$q606$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
