WITH ins_art_law155_5 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 5, NULL, $q612$يقع باطلا ً ما يرد في وثيقة التأمين من الشروط الآتية:
-١ الشرط الذي يقضى بسقوط الحق في التأمين بسبب مخالفة القوانين واللوائح، إلا إذا انطوت هذه المخالفة على جناية أو جنحة عمدية أو غش أو تدليس.
-٢ الشرط الذى يقضى بسقوط حق المؤمن له بسبب تأخره فى إعلان الحادث المؤمن ضده إلى السلطات أو فى تقديم المستندات،إذا تبين من الظروف أن التأخر كان لعذر مقبول ولم يؤد إلى إحداث تغيير جوهرى بمعالم الحادث أو تفاقم الضرر الناتج عنه.
-٣ كل شرط مطبوع لم يبرز بشكل ظاهر وكان متعلق ًا بحالة من الأحوال التي تؤدى إلى البطلان أو السقوط.
-٤ كل شرط تعسفى آخر يتبين أنه لم يكن لمخالفته أثر في وقوع الحادث المؤمن ضده.$q612$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
