WITH ins_art_law155_39 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 39, NULL, $q680$لمجلس إدارة الهيئة اقتراح مجموعة من التأمينات الإلزامية المناسبة للسوق المصرية وفق ًا لما يعده من دراسات فنية متخصصة لكل نوع من أنواع التأمين الإلزامي ويصدر بها قرار من مجلس الوزراء يوضح الفئات والشروط والضوابط والأسعار الخاصة بكل منها على حدة لإنفاذها،على أن تكون من بينها التأمينات الآتية:
-١ تأمينات المسئوليات المهنية بجميع أنواعها كشرط من شروط الترخيص بمزاولة النشاط أو المهنة.
-٢ التأمين ضد حوادث الطرق السريعة المتميزة ذات الرسوم.
-٣ التأمين ضد حوادث السكك الحديدية ومترو الأنفاق.
-٤ التأمين على طلاب المدارس والمعاهد الأزهرية والمعاهد والجامعات بما في ذلك طلاب جامعة الأزهر والمعاهد التابعة لها.
-٥ تغطيات التأمين ضد المخاطر الإلكترونية لجميع المنشآت العاملة بالقطاعات المالية غير المصرفية.
-٦ التأمين ضد المخاطر التي قد تتعرض لها المرافق العامة والأصول المملوكة للدولة.
-٧ التأمين ضد مخاطر حالات الطلاق.
-٨ التأمين متناهى الصغر ضد حالتى الوفاة والعجز الكلى المستديم.
-٩ التأمين ضد المخاطر التي يتعرض لها المصريون في الخارج.
التأمين الإلزامي عن المسئولية المدنية الناشئة عن حوادث مركبات النقل السريع داخل جمهورية مصر العربية$q680$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
