WITH ins_art_law155_58 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 58, NULL, $q718$يجوز لشركات التأمين الخاضعة لأحكام هذا القانون أن تنشئ فيما بينها مجمعة أو أكثر لإدارة خطر أو عملية بذاتها وفق ًا للنظام الأساسي لكل مجمعة تأمين، وذلك في حالة توافر أى من الأخطار الآتية:
-١ الأخطار ذات الطبيعة القومية التي يصعب فيها الحصول على ترتيبات إعادة التأمين.
-٢ الأخطار النمطية التي لا تحتاج إلى عمليات اكتتاب فنية.
-٣ الأخطار الطبيعية.
-٤ الحالات الأخرى التي يقررها مجلس إدارة الهيئة ووفق ًا للضوابط والمعايير التي يقررها. ويكون لمجمعة التأمين الحق فى إصدار الوثائق التي تغطى هذه الأخطار وفى هذه الحالة تخضع لذات الضوابط المقررة على شركات التأمين في هذا الشأن ومنها تلك المتعلقة بالمخصصات الفنية.$q718$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q718$يجوز لشركات التأمين الخاضعة لأحكام هذا القانون أن تنشئ فيما بينها مجمعة أو أكثر لإدارة خطر أو عملية بذاتها وفق ًا للنظام الأساسي لكل مجمعة تأمين، وذلك في حالة توافر أى من الأخطار الآتية:
