WITH ins_art_law155_59 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 59, NULL, $q720$يضع الأعضاء المؤسسون للمجمعة النظام الأساسي لها،ويصدر بإنشاء مجمعة التأمين والتصديق على نظامها قرار من مجلس إدارة الهيئة. وتسجل المجمعة في سجل خاص لدى الهيئة بعد أداء رسم مقداره مائة ألف جنيه، يسدد وفق ًا لطرق السداد المقررة قانونا وتكتسب الشخصية الاعتبارية الخاصة من تاريخ نشر قرار التسجيل في الوقائع المصرية. ويجب إخطار الهيئة بأية تعديلات تطرأ على النظام الأساسي وبمبررات هذا التعديل،ولا يجوز العمل بهذه التعديلات إلا بعد اعتمادها من مجلس إدارة الهيئة ونشرها بالوقائع المصرية. ) الفصل الخامس ( نشاط صناديق التأمين الحكومية$q720$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q720$يضع الأعضاء المؤسسون للمجمعة النظام الأساسي لها،ويصدر بإنشاء مجمعة التأمين والتصديق على نظامها قرار من مجلس إدارة الهيئة. وتسجل المجمعة في سجل خاص لدى الهيئة بعد أداء رسم مقداره مائة ألف جنيه، يسدد وفق ًا لطرق السداد المقررة قانونا وتكتسب الشخصية الاعتبارية الخاصة من تاريخ نشر قرار التسجيل في الوقائع المصرية. ويجب إخطار الهيئة بأية تعديلات تطرأ على النظام الأساسي وبمبررات هذا التعديل،ولا يجوز العمل بهذه التعديلات إلا بعد اعتمادها من مجلس إدارة الهيئة ونشرها بالوقائع المصرية. ) الفصل الخامس ( نشاط صناديق التأمين الحكومية$q720$, '2024-07-11', 'active' FROM ins_art_law155_59;

WITH ins_art_law155_60 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 60, NULL, $q722$يكون إنشاء صندوق التأمين الحكومى بقرار من رئيس مجلس الوزراء بناء على اقتراح من مجلس إدارة الهيئة،ويكون له الشخصية الاعتبارية الخاصة من تاريخ نشر هذا القرار بالوقائع المصرية. ويصدر بتحديد شروط وأسعار عمليات التأمين المشار إليها قرار من مجلس إدارة الهيئة. ويتم تسجيل تلك الصناديق بالسجل المعد لذلك بالهيئة فى مقابل رسم يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه،يسدد وفق ًا لطرق السداد المقررة قانون ًا. ويصدر مجلس إدارة الهيئة قرارا بالأحكام المنظمة لأوجه رقابة الهيئة على هذه الصناديق.$q722$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q722$يكون إنشاء صندوق التأمين الحكومى بقرار من رئيس مجلس الوزراء بناء على اقتراح من مجلس إدارة الهيئة،ويكون له الشخصية الاعتبارية الخاصة من تاريخ نشر هذا القرار بالوقائع المصرية. ويصدر بتحديد شروط وأسعار عمليات التأمين المشار إليها قرار من مجلس إدارة الهيئة. ويتم تسجيل تلك الصناديق بالسجل المعد لذلك بالهيئة فى مقابل رسم يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه،يسدد وفق ًا لطرق السداد المقررة قانون ًا. ويصدر مجلس إدارة الهيئة قرارا بالأحكام المنظمة لأوجه رقابة الهيئة على هذه الصناديق.$q722$, '2024-07-11', 'active' FROM ins_art_law155_60;

WITH ins_art_law155_61 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 61, NULL, $q724$يقوم الصندوق الحكومي لتغطية الأضرار الناتجة عن حوادث مركبات النقل السريع بتغطية الأضرار الناشئة عن الحوادث المشار إليها في الحالات الآتية:
-١ عدم معرفة المركبة المسئولة عن الحادث.
-٢ عدم وجود تأمين على المركبة لصالح الغير.
-٣ حوادث المركبات المعفاة من بعض إجراءات الترخيص.
-٤ حالات إعسار شركة التأمين كليا أو جزئيا.
-٥ الحالات الأخرى التى يصدر بها قرار من مجلس إدارة الهيئة. ويؤدى الصندوق مبلغ التأمين للمستحقين طبق ًا لأحكام المادة ) (٤٧من هذا القانون،ويحق له فى الحالة المنصوص عليها في البندين ) (٣، ٢من الفقرة الأولى من هذه المادة الرجوع على مالك السيارة أو المركبة المتسببة فى الضرر بقيمة التأمين الذي أداه. ويجب على المتضرر تقديم طلب التعويض للصندوق مصحوبا بالمستندات التي يصدر بتحديدها قرار من مجلس إدارة الهيئة،ويتولى الصندوق البت في الطلب خلال شهر من تاريخ تقديمه. ولا يجوز للمتضرر اتخاذ أية إجراءات قضائية ضد الصندوق قبل تقديم الطلب ومرور المدة المشار إليها بالفقرة الثالثة من هذه المادة،ولا تقبل الدعاوى المرفوعة دون مراعاة تقديم الطلب المشار إليه. ويختص رئيس مجلس الوزراء بتعديل نظام الصندوق. وتتولى مجمعة التأمين المعنية تمويل الصندوق بنسبة من متحصلات الأقساط، ويصدر بتحديد هذه النسبة قرار من مجلس إدارة الهيئة بناء على تقرير فني تعده الهيئة عن هذه المتحصلات. كما تلتزم شركات التأمين أعضاء مجمعة التأمين المعنية المرخص لها بمزاولة نشاط التأمين الإلزامي عن المسئولية المدنية الناشئة عن حوادث مركبات النقل السريع داخل جمهورية مصر العربية بسداد أى عجز مالي يواجه الصندوق.$q724$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q724$يقوم الصندوق الحكومي لتغطية الأضرار الناتجة عن حوادث مركبات النقل السريع بتغطية الأضرار الناشئة عن الحوادث المشار إليها في الحالات الآتية:
-١ عدم معرفة المركبة المسئولة عن الحادث.
-٢ عدم وجود تأمين على المركبة لصالح الغير.
-٣ حوادث المركبات المعفاة من بعض إجراءات الترخيص.
-٤ حالات إعسار شركة التأمين كليا أو جزئيا.
-٥ الحالات الأخرى التى يصدر بها قرار من مجلس إدارة الهيئة. ويؤدى الصندوق مبلغ التأمين للمستحقين طبق ًا لأحكام المادة ) (٤٧من هذا القانون،ويحق له فى الحالة المنصوص عليها في البندين ) (٣، ٢من الفقرة الأولى من هذه المادة الرجوع على مالك السيارة أو المركبة المتسببة فى الضرر بقيمة التأمين الذي أداه. ويجب على المتضرر تقديم طلب التعويض للصندوق مصحوبا بالمستندات التي يصدر بتحديدها قرار من مجلس إدارة الهيئة،ويتولى الصندوق البت في الطلب خلال شهر من تاريخ تقديمه. ولا يجوز للمتضرر اتخاذ أية إجراءات قضائية ضد الصندوق قبل تقديم الطلب ومرور المدة المشار إليها بالفقرة الثالثة من هذه المادة،ولا تقبل الدعاوى المرفوعة دون مراعاة تقديم الطلب المشار إليه. ويختص رئيس مجلس الوزراء بتعديل نظام الصندوق. وتتولى مجمعة التأمين المعنية تمويل الصندوق بنسبة من متحصلات الأقساط، ويصدر بتحديد هذه النسبة قرار من مجلس إدارة الهيئة بناء على تقرير فني تعده الهيئة عن هذه المتحصلات. كما تلتزم شركات التأمين أعضاء مجمعة التأمين المعنية المرخص لها بمزاولة نشاط التأمين الإلزامي عن المسئولية المدنية الناشئة عن حوادث مركبات النقل السريع داخل جمهورية مصر العربية بسداد أى عجز مالي يواجه الصندوق.$q724$, '2024-07-11', 'active' FROM ins_art_law155_61;

WITH ins_art_law155_62 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 62, NULL, $q726$يصدر رئيس مجلس الوزراء بناء على اقتراح من مجلس إدارة الهيئة قرارا بتصفية الصندوق الحكومي في الحالات التالية:
-١ إذا تبين من نتيجة فحص المركز المالي للصندوق أن أمواله لا تكفى للوفاء بالتزاماته.
