WITH ins_art_law155_78 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 78, NULL, $q758$تنعقد الجمعية العامة العادية للصندوق خلال الثلاثة أشهر التالية لانتهاء السنة المالية بدعوة من رئيس مجلس إدارة الصندوق،وتحدد الدعوة زمان ومكان الاجتماع وجدول الأعمال. كما يجوز لرئيس مجلس إدارة الصندوق أو لعدد من الأعضاء لا يقل عن الربع أو لرئيس مجلس إدارة الهيئة دعوة الجمعية العامة غير العادية في الحالات التي تستلزم ذلك وفق ًا لأحكام هذا الباب والإجراءات والضوابط التي يحددها مجلس إدارة الهيئة والنظام الأساسي للصندوق.$q758$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q758$تنعقد الجمعية العامة العادية للصندوق خلال الثلاثة أشهر التالية لانتهاء السنة المالية بدعوة من رئيس مجلس إدارة الصندوق،وتحدد الدعوة زمان ومكان الاجتماع وجدول الأعمال. كما يجوز لرئيس مجلس إدارة الصندوق أو لعدد من الأعضاء لا يقل عن الربع أو لرئيس مجلس إدارة الهيئة دعوة الجمعية العامة غير العادية في الحالات التي تستلزم ذلك وفق ًا لأحكام هذا الباب والإجراءات والضوابط التي يحددها مجلس إدارة الهيئة والنظام الأساسي للصندوق.$q758$, '2024-07-11', 'active' FROM ins_art_law155_78;

WITH ins_art_law155_79 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 79, NULL, $q760$تختص الجمعية العامة العادية للصندوق بما يأتي:
-١ مناقشة تقرير مجلس الإدارة عن نشاط الصندوق.
-٢ مناقشة تقرير مجلس الإدارة عن أداء الاستثمار.
-٣ المصادقة على تقرير مراقب الحسابات.
-٤ اعتماد القوائم المالية للصندوق.
-٥ تحديد بدلات مشاركة أعضاء مجلس الإدارة فى اجتماعاته،وكذا مكافآتهم في حالة وجود فائض يظهره تقرير الخبير الاكتوارى وبشرط موافقة الهيئة.
-٦ تعيين مراقب الحسابات وتحديد أتعابه.
-٧ انتخاب أعضاء مجلس الإدارة.
-٨ النظر في الموضوعات الأخرى المحددة في إخطار الدعوة.$q760$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
