WITH ins_art_law155_91 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 91, NULL, $q784$يتولى إدارة شئون الصندوق مجلس إدارته،وله فى سبيل ذلك القيام بأي عمل يحقق أغراضه في حدود أحكام هذا القانون والنظام الأساسي للصندوق،وأن يتخذ ما يراه لازما من قرارات لمباشرة اختصاصات الصندوق وعلى الأخص ما يلى:
-١ تعيين المدير التنفيذي والمالي للصندوق.
-٢ إقرار المراكز المالية ربع السنوية للصندوق والقوائم المالية والإيضاحات المتممة لها في نهاية كل سنة مالية.
-٣ إقرار الموازنات التقديرية للصندوق وتعرض على مجلس إدارة الصندوق قبل ثلاثة شهور على الأقل من بدء السنة المالية الخاصة بالموازنة.
-٤ نظر التقارير ربع السنوية والسنوية عن نشاط الصندوق.
-٥ تعيين مدير الاستثمار أو التعاقد مع شركة إدارة الاستثمار. ويقر مجلس إدارة الصندوق نظاما للرقابة الداخلية يهدف إلى:
-١ التحقق من التزام الصندوق والعاملين به بتطبيق أحكام هذا القانون واللوائح والقرارات الصادرة تنفيذ ًا لها.
-٢ حماية أصول وموارد الصندوق من الضياع نتيجة سوء الاستخدام أو عدم الالتزام بالقوانين ذات الصلة.
-٣ وضع قواعد المساءلة والمحاسبة داخل الصندوق.$q784$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
