WITH ins_art_law155_94 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 94, NULL, $q790$يكون للصندوق مدير مالى متفرغ يصدر بتعيينه وتحديد اختصاصاته ومعاملته المالية قرار من مجلس إدارة الصندوق،ويتولى على الأخص ما يلى:
-١ إعداد السياسة الاستثمارية والمالية التي تساعد على تحقيق أهداف الصندوق ومتابعة تنفيذها.
-٢ الإشراف على إجراءات الجرد بالصندوق والتأكد من أن الجرد والتقييم قد تم وفق ًا للإجراءات وفي المواعيد المحددة.
-٣ الإشراف على إعداد الحسابات الختامية وقائمة المركز المالي للصندوق والتقارير السنوية المرفقة بها في المواعيد القانونية.
-٤ الإشراف على الإجراءات الخاصة بتدبير الاعتمادات وتوفير السيولة النقدية اللازمة لتمكين الصندوق من مباشرة نشاطه.
-٥ تلقى تقارير جهات الرقابة فيما يتعلق بالنواحى المالية والإشراف على دراستها وإعداد الردود عليها.$q790$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
