SELECT id, 1, $q820$اتحاد شركات التأمين،اتحاد غير هادف للربح يتكون من شركات التأمين وإعادة التأمين الخاضعة لهذا القانون أيا كان نوع النشاط الذي تزاوله،ويتمتع بشخصية اعتبارية مستقلة،ويعد من أشخاص القانون الخاص ويسجل فى سجل خاص بالهيئة، ويشار إليه في هذا القانون بالاتحاد.$q820$, '2024-07-11', 'active' FROM ins_art_law155_109;

WITH ins_art_law155_110 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 110, NULL, $q822$يهدف الاتحاد إلى تحقيق الأغراض التالية:
-١ العمل على رفع مستوى صناعة التأمين والمهن التأمينية المرتبطة بها وتحديثها وترسيخ مفاهيم وأعراف العمل التأميني الصحيح.
-٢ التنسيق مع الهيئة فى المسائل المشتركة وتجنب تعارض المصالح وتسوية المنازعات بين الأعضاء.
-٣ توثيق التعاون والتنسيق بين الاتحاد والهيئة بما يحقق صالح سوق التأمين والاقتصاد القومي.
