WITH ins_art_law155_113 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 113, NULL, $q828$الجمعية العامة هي السلطة العليا للاتحاد،وتشكل من ممثل لكل عضو من أعضاء الاتحاد ويحضر اجتماعاتها ممثلو الأعضاء الذين أوفوا بالالتزامات المالية المستحقة عليهم وفق ًا للنظام الأساسى للاتحاد حتى تاريخ انعقاد الجمعية. وتختص الجمعية العامة للاتحاد بما يأتي:
-١ إقرار السياسات اللازمة لتحقيق أهداف الاتحاد.
-٢ اعتماد الهيكل التنظيمي للاتحاد.
-٣ انتخاب رئيس مجلس إدارة الاتحاد ونائبه وأعضاء المجلس.
-٤ الموافقة على النظام الأساسى للاتحاد وتعديلاته.
-٥ وضع قواعد السلوك المهنى التي يلتزم بها أعضاؤه من الشركات على أن تعتمد من الهيئة.
-٦ تحديد قيمة مقابل العضوية الذي يؤديه طالب الانضمام للاتحاد بما لا يجاوز خمسمائة ألف جنيه.
-٧ تحديد قيمة الاشتراك السنوى للأعضاء بما لا يجاوز خمسة ملايين جنيه.
-٨ اعتماد الموازنة التقديرية للاتحاد وكذا القوائم المالية وتقرير مراقب الحسابات والتقرير السنوى عن نشاط الاتحاد.
-٩ تعيين مراقب الحسابات من بين المقيدين بسجل مراقبي الحسابات بالهيئة، وتحديد أتعابه.
-١٠ المسائل الأخرى التى يرى مجلس إدارة الاتحاد عرضها على الجمعية العامة وإدراجها في جدول الأعمال. ويحدد النظام الأساسي للاتحاد الاختصاصات الأخرى للجمعية العامة، وغيرها من الإجراءات والقواعد المتعلقة بنظام عملها.$q828$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
