WITH ins_art_law155_122 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 122, NULL, $q846$يجوز بقرار من مجلس إدارة الهيئة إنشاء أجهزة معاونة لقطاع التأمين وذلك وفق ًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة. ويسجل الجهاز فى سجل خاص لدى الهيئة بعد أداء رسم يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه،يسدد وفق ًا لطرق السداد المقررة قانون ًا. وينشر قرار الإنشاء والنظام الأساسى بالوقائع المصرية وعلى الموقع الإلكتروني للجهاز وكذا الموقع الإلكترونى للهيئة،ويكتسب الجهاز الشخصية الاعتبارية المستقلة اعتبارا من تاريخ هذا النشر،ويعد من أشخاص القانون الخاص. ويعتبر من قبيل الأجهزة المعاونة فى حكم هذه المادة المعاهد التأمينية ومراكز التدريب ومراكز الحاسبات وتكنولوجيا المعلومات وتداول البيانات التي تنشئها شركات التأمين فيما بينها في مجال التأمين. مكاتب تمثيل منشآت التأمين أو إعادة التأمين أو الأنشطة المرتبطة بهما$q846$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q846$يجوز بقرار من مجلس إدارة الهيئة إنشاء أجهزة معاونة لقطاع التأمين وذلك وفق ًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة. ويسجل الجهاز فى سجل خاص لدى الهيئة بعد أداء رسم يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه،يسدد وفق ًا لطرق السداد المقررة قانون ًا. وينشر قرار الإنشاء والنظام الأساسى بالوقائع المصرية وعلى الموقع الإلكتروني للجهاز وكذا الموقع الإلكترونى للهيئة،ويكتسب الجهاز الشخصية الاعتبارية المستقلة اعتبارا من تاريخ هذا النشر،ويعد من أشخاص القانون الخاص. ويعتبر من قبيل الأجهزة المعاونة فى حكم هذه المادة المعاهد التأمينية ومراكز التدريب ومراكز الحاسبات وتكنولوجيا المعلومات وتداول البيانات التي تنشئها شركات التأمين فيما بينها في مجال التأمين. مكاتب تمثيل منشآت التأمين أو إعادة التأمين أو الأنشطة المرتبطة بهما$q846$, '2024-07-11', 'active' FROM ins_art_law155_122;

WITH ins_art_law155_123 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 123, NULL, $q848$يجوز للهيئة الترخيص بإنشاء مكاتب تمثيل في جمهورية مصر العربية للشركات الأجنبية التى تعمل فى مجال التأمين أو إعادة التأمين أو الأنشطة والخدمات المرتبطة بهما وفق ًا للشروط والضوابط التي يصدر بها قرار عن مجلس إدارة الهيئة،وذلك بعد أداء رسم تسجيل مقداره خمسة آلاف دولار أو ما يعادله بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى،يسدد وفق طرق السداد المقررة قانون ًا. ويقتصر غرض عملها على دراسة سوق التأمين والعلاقات العامة والاتصالات، والقيام بدور حلقة اتصال مع المراكز الرئيسية فى الخارج والمساهمة في تذليل المشاكل والصعوبات وتقديم التسهيلات لشركات السوق المحلية. وتجدد تلك الموافقة سنويا مقابل رسم مقداره ألف دولار أو ما يعادله بالعملات الأجنبية الحرة التى يقبلها البنك المركزى المصرى،يسدد وفق طرق السداد المقررة قانون ًا.
وتخضع تلك المكاتب لإشراف ورقابة الهيئة،ويكون للهيئة حق الاطلاع في أي وقت على الدفاتر والسجلات الخاصة بها وطلب ما تراه من البيانات والمستندات التي تحقق أغراض الإشراف والرقابة عليها. ويجب على تلك المكاتب أن تخطر الهيئة بأى تعديلات تطرأ على بياناتها المسجلة لدى الهيئة. وفى حالة مخالفة أى من تلك المكاتب لأى من شروط وضوابط الهيئة يتم إنذارها بالمخالفة وطلب إزالتها خلال ثلاثين يوما من تاريخ إنذارها،فإذا لم تتم إزالتها يتم شطبها من السجل بقرار من مجلس إدارة الهيئة. وتلتزم تلك المكاتب بإخطار الهيئة عند إغلاقها المكتب سواء بصورة مؤقتة أو نهائية.$q848$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q848$يجوز للهيئة الترخيص بإنشاء مكاتب تمثيل في جمهورية مصر العربية للشركات الأجنبية التى تعمل فى مجال التأمين أو إعادة التأمين أو الأنشطة والخدمات المرتبطة بهما وفق ًا للشروط والضوابط التي يصدر بها قرار عن مجلس إدارة الهيئة،وذلك بعد أداء رسم تسجيل مقداره خمسة آلاف دولار أو ما يعادله بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى،يسدد وفق طرق السداد المقررة قانون ًا. ويقتصر غرض عملها على دراسة سوق التأمين والعلاقات العامة والاتصالات، والقيام بدور حلقة اتصال مع المراكز الرئيسية فى الخارج والمساهمة في تذليل المشاكل والصعوبات وتقديم التسهيلات لشركات السوق المحلية. وتجدد تلك الموافقة سنويا مقابل رسم مقداره ألف دولار أو ما يعادله بالعملات الأجنبية الحرة التى يقبلها البنك المركزى المصرى،يسدد وفق طرق السداد المقررة قانون ًا.
وتخضع تلك المكاتب لإشراف ورقابة الهيئة،ويكون للهيئة حق الاطلاع في أي وقت على الدفاتر والسجلات الخاصة بها وطلب ما تراه من البيانات والمستندات التي تحقق أغراض الإشراف والرقابة عليها. ويجب على تلك المكاتب أن تخطر الهيئة بأى تعديلات تطرأ على بياناتها المسجلة لدى الهيئة. وفى حالة مخالفة أى من تلك المكاتب لأى من شروط وضوابط الهيئة يتم إنذارها بالمخالفة وطلب إزالتها خلال ثلاثين يوما من تاريخ إنذارها،فإذا لم تتم إزالتها يتم شطبها من السجل بقرار من مجلس إدارة الهيئة. وتلتزم تلك المكاتب بإخطار الهيئة عند إغلاقها المكتب سواء بصورة مؤقتة أو نهائية.$q848$, '2024-07-11', 'active' FROM ins_art_law155_123;

WITH ins_art_law155_124 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 124, $q849$الفصل الثامن: المهن التأمينية$q849$, $q850$لا يجوز للخبير الاكتوارى من الأشخاص الطبيعيين أن يزاول أعماله إلا بعد الحصول على ترخيص بذلك من الهيئة ويسجل فى السجل المعد لذلك بالهيئة، ويتم قيد اسمه وفق ًا للشروط والقواعد والإجراءات التي يضعها مجلس إدارة الهيئة، والتي من بينها على وجه الخصوص ما يلى: أن يكون حاصلا ً على إحدى الدرجات أو الدبلومات الآتية: ) أ ( درجة زميل أو رفيق من أحد المعاهد الآتية: معهد وكلية الخبراء الاكتواريون بالمملكة المتحدة. جمعية الخبراء الاكتواريون بالولايات المتحدة الأمريكية. )ب( درجة مهنية تالية لمرحلة الدراسة الجامعية الأولى فى العلوم الاكتوارية من إحدى جمعيات أو معاهد الخبراء الاكتواريين،معادلة للشهادات الواردة في البند )أ(، التي يعتمدها مجلس إدارة الهيئة.
ويسرى القيد لمدة خمس سنوات قابلة للتجديد،ويقدم طلب التجديد في سجل الخبراء الاكتواريين وفق ًا للشروط والأوضاع التي يحددها مجلس إدارة الهيئة، على أن يتم اتخاذ إجراءات التجديد خلال ثلاثة الأشهر الأخيرة على الأقل من الموعد المذكور. ويؤدى طالب القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز عشرة آلاف جنيه للشخص الطبيعي،يسدد وفق ًا لطرق السداد المقررة قانون ًا.$q850$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q850$لا يجوز للخبير الاكتوارى من الأشخاص الطبيعيين أن يزاول أعماله إلا بعد الحصول على ترخيص بذلك من الهيئة ويسجل فى السجل المعد لذلك بالهيئة، ويتم قيد اسمه وفق ًا للشروط والقواعد والإجراءات التي يضعها مجلس إدارة الهيئة، والتي من بينها على وجه الخصوص ما يلى: أن يكون حاصلا ً على إحدى الدرجات أو الدبلومات الآتية: ) أ ( درجة زميل أو رفيق من أحد المعاهد الآتية: معهد وكلية الخبراء الاكتواريون بالمملكة المتحدة. جمعية الخبراء الاكتواريون بالولايات المتحدة الأمريكية. )ب( درجة مهنية تالية لمرحلة الدراسة الجامعية الأولى فى العلوم الاكتوارية من إحدى جمعيات أو معاهد الخبراء الاكتواريين،معادلة للشهادات الواردة في البند )أ(، التي يعتمدها مجلس إدارة الهيئة.
ويسرى القيد لمدة خمس سنوات قابلة للتجديد،ويقدم طلب التجديد في سجل الخبراء الاكتواريين وفق ًا للشروط والأوضاع التي يحددها مجلس إدارة الهيئة، على أن يتم اتخاذ إجراءات التجديد خلال ثلاثة الأشهر الأخيرة على الأقل من الموعد المذكور. ويؤدى طالب القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز عشرة آلاف جنيه للشخص الطبيعي،يسدد وفق ًا لطرق السداد المقررة قانون ًا.$q850$, '2024-07-11', 'active' FROM ins_art_law155_124;

WITH ins_art_law155_125 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 125, $q851$الفصل الثامن: المهن التأمينية$q851$, $q852$يجوز للهيئة الترخيص بمزاولة أعمال الخبرة الاكتوارية من خلال شركات يتم تأسيسها لهذا الغرض وتقيد بالسجل المعد لذلك بالهيئة،وذلك وفق ًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة. ويشترط للقيد في السجل المشار إليه في الفقرة الأولى من هذه المادة ضرورة توافر الآتي:
-١ ألا يقل رأسمالها المصدر والمدفوع بالكامل عن المبلغ الذي يحدده مجلس إدارة الهيئة بما لا يقل عن ثلاثة ملايين جنيه نقدا أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى.
-٢ التقدم بطلب للهيئة للتسجيل والترخيص للشركة بمزاولة نشاطها مصحوبا بدراسة الجدوى وعقد تأسيس الشركة ونظامها الأساسي والسجل التجاري.
-٣ أن يكون القائم بالإدارة التنفيذية للشركة من بين المقيدين بسجل الخبراء الاكتواريين بالهيئة وذلك وفق ًا للشروط والمعايير التي يقررها مجلس إدارة الهيئة.
-٤ توافر جميع الشروط المتطلبة لقيد الأشخاص الطبيعيين في سجل الخبراء لدى كل من يزاول أعمال الخبرة الاكتوارية من خلال الشخص الاعتباري.
-٥ أن يقتصر غرض الشركة على مزاولة أعمال الخبرة الاكتوارية. وتؤدى الشركة طالبة القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه يسدد وفق ًا لطرق السداد المقررة قانون ًا. وفى حالة قيام مانع لدى العضو القائم بالإدارة التنفيذية يحول دون مباشرة أعماله، يجوز لمجلس إدارة الشركة أن يكلف مؤقت ًا أحد الخبراء الاكتواريين من المقيدين بسجلات الهيئة بتولى مهام القائم بالإدارة التنفيذية لحين تعيين آخر مكانه أو زوال المانع،شريطة أن تتوافر لديه ذات الشروط والمعايير التي تصدر عن مجلس إدارة الهيئة.$q852$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q852$يجوز للهيئة الترخيص بمزاولة أعمال الخبرة الاكتوارية من خلال شركات يتم تأسيسها لهذا الغرض وتقيد بالسجل المعد لذلك بالهيئة،وذلك وفق ًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة. ويشترط للقيد في السجل المشار إليه في الفقرة الأولى من هذه المادة ضرورة توافر الآتي:
-١ ألا يقل رأسمالها المصدر والمدفوع بالكامل عن المبلغ الذي يحدده مجلس إدارة الهيئة بما لا يقل عن ثلاثة ملايين جنيه نقدا أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى.
-٢ التقدم بطلب للهيئة للتسجيل والترخيص للشركة بمزاولة نشاطها مصحوبا بدراسة الجدوى وعقد تأسيس الشركة ونظامها الأساسي والسجل التجاري.
-٣ أن يكون القائم بالإدارة التنفيذية للشركة من بين المقيدين بسجل الخبراء الاكتواريين بالهيئة وذلك وفق ًا للشروط والمعايير التي يقررها مجلس إدارة الهيئة.
-٤ توافر جميع الشروط المتطلبة لقيد الأشخاص الطبيعيين في سجل الخبراء لدى كل من يزاول أعمال الخبرة الاكتوارية من خلال الشخص الاعتباري.
-٥ أن يقتصر غرض الشركة على مزاولة أعمال الخبرة الاكتوارية. وتؤدى الشركة طالبة القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه يسدد وفق ًا لطرق السداد المقررة قانون ًا. وفى حالة قيام مانع لدى العضو القائم بالإدارة التنفيذية يحول دون مباشرة أعماله، يجوز لمجلس إدارة الشركة أن يكلف مؤقت ًا أحد الخبراء الاكتواريين من المقيدين بسجلات الهيئة بتولى مهام القائم بالإدارة التنفيذية لحين تعيين آخر مكانه أو زوال المانع،شريطة أن تتوافر لديه ذات الشروط والمعايير التي تصدر عن مجلس إدارة الهيئة.$q852$, '2024-07-11', 'active' FROM ins_art_law155_125;

WITH ins_art_law155_126 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 126, $q853$الفصل الثامن: المهن التأمينية$q853$, $q854$يتم قيد الخبير أو إعادة قيده أو تجديده أو شطبه الاختياري أو عدم التجديد في الموعد الوارد بهذا القانون بقرار من رئيس مجلس إدارة الهيئة. ويتم وقف قيد الخبير لمدة لا تجاوز ثلاث سنوات أو شطب قيده بقرار من مجلس إدارة الهيئة في أي من الحالات التالية:
-١ فقد أحد شروط القيد.
-٢ إذا ثبت أنه قدم أية بيانات جوهرية غير صحيحة مطلوبة وفق ًا لأحكام هذا القانون نتيجة تعمد أو خطأ جسيم.
-٣ عدم الالتزام بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة والتي يصدر بها قرار عن مجلس إدارة الهيئة.
-٤ إذا ثبت أنه قام بأعمال مخالفة للقوانين أو اللوائح المتعلقة بمهنته أو تنطوي على خطأ عمدى أو خطأ جسيم. وفي الحالات الثلاث الأخيرة يجب إجراء تحقيق من خلال الهيئة.$q854$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q854$يتم قيد الخبير أو إعادة قيده أو تجديده أو شطبه الاختياري أو عدم التجديد في الموعد الوارد بهذا القانون بقرار من رئيس مجلس إدارة الهيئة. ويتم وقف قيد الخبير لمدة لا تجاوز ثلاث سنوات أو شطب قيده بقرار من مجلس إدارة الهيئة في أي من الحالات التالية:
-١ فقد أحد شروط القيد.
-٢ إذا ثبت أنه قدم أية بيانات جوهرية غير صحيحة مطلوبة وفق ًا لأحكام هذا القانون نتيجة تعمد أو خطأ جسيم.
-٣ عدم الالتزام بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة والتي يصدر بها قرار عن مجلس إدارة الهيئة.
-٤ إذا ثبت أنه قام بأعمال مخالفة للقوانين أو اللوائح المتعلقة بمهنته أو تنطوي على خطأ عمدى أو خطأ جسيم. وفي الحالات الثلاث الأخيرة يجب إجراء تحقيق من خلال الهيئة.$q854$, '2024-07-11', 'active' FROM ins_art_law155_126;

WITH ins_art_law155_127 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 127, $q855$الفصل الثامن: المهن التأمينية$q855$, $q856$على طالب القيد أو التجديد أن يقدم قبل قيده بالسجل أو عند تجديد هذا القيد وثيقة تأمين مسئولية مهنية يحدد حداها الأدنى والأقصى في ضوء حجم أعماله وفق ًا للضوابط التي يصدر بها قرار من الهيئة. ويكتفى بالنسبة للخبراء الاكتواريين والقائم بمهام الإدارة التنفيذية لها الذين يعملون باسم ولحساب شركة خبرة اكتوارية واحدة فقط أن تتم تغطيتهم من خلال وثيقة شاملة عن أعمال شركتهم لدى إحدى شركات التأمين المسجلة بالهيئة. ويباشر الخبير الاكتوارى أعماله وفق ًا للقواعد والضوابط والشروط الصادرة عن مجلس إدارة الهيئة. وفي جميع الأحوال،يلتزم الخبراء الاكتواريون الطبيعيون والاعتباريون في مباشرة أعمالهم بقواعد ومعايير الخبرة الاكتوارية المعتمدة من مجلس إدارة الهيئة.
خبراء التأمين الاستشاريون$q856$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
