INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q866$يتم قيد الخبير أو إعادة قيده أو تجديده أو شطبه الاختياري أو لعدم التجديد في الموعد الوارد بهذا القانون بقرار من رئيس مجلس إدارة الهيئة. ويتم وقف القيد لمدة لا تجاوز ثلاث سنوات أو شطب قيد الخبير بقرار من مجلس إدارة الهيئة في أي من الحالات التالية:
-١ فقد أحد شروط القيد.
-٢ إذا ثبت أنه قدم أية بيانات جوهرية غير صحيحة مطلوبة وفق ًا لأحكام هذا القانون نتيجة تعمد أو خطأ جسيم.
-٣ عدم الالتزام بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة والتي يصدر بها قرار عن مجلس إدارة الهيئة.
-٤ إذا ثبت أنه قام بأعمال مخالفة للقوانين أو اللوائح المتعلقة بمهنته أو تنطوي على خطأ عمدى أو خطأ جسيم. وفي الحالات الثلاث الأخيرة يجب إجراء تحقيق من خلال الهيئة.$q866$, '2024-07-11', 'active' FROM ins_art_law155_132;

WITH ins_art_law155_133 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 133, $q867$الفصل الثامن: المهن التأمينية$q867$, $q868$على طالب القيد أو التجديد أن يقدم قبل قيده بالسجل أو عند تجديد هذا القيد وثيقة تأمين مسئولية مهنية يحدد حدها الأقصى وفق ًا للضوابط الصادرة عن الهيئة. ويكتفى بالنسبة لخبراء التأمين الاستشاريين والقائم بأعمال الإدارة التنفيذية لها الذين يعملون باسم ولحساب شركة خبرة استشارية بأن يتم تغطيتهم من خلال وثيقة شاملة عن أعمال تلك الشركة لدى إحدى شركات التأمين المسجلة بالهيئة. ويباشر خبراء التأمين الاستشاريون أعمالهم وفق ًا للقواعد والضوابط والشروط الصادرة عن مجلس إدارة الهيئة. خبراء تقييم الأخطار أو معاينة وتقدير الأضرار$q868$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q868$على طالب القيد أو التجديد أن يقدم قبل قيده بالسجل أو عند تجديد هذا القيد وثيقة تأمين مسئولية مهنية يحدد حدها الأقصى وفق ًا للضوابط الصادرة عن الهيئة. ويكتفى بالنسبة لخبراء التأمين الاستشاريين والقائم بأعمال الإدارة التنفيذية لها الذين يعملون باسم ولحساب شركة خبرة استشارية بأن يتم تغطيتهم من خلال وثيقة شاملة عن أعمال تلك الشركة لدى إحدى شركات التأمين المسجلة بالهيئة. ويباشر خبراء التأمين الاستشاريون أعمالهم وفق ًا للقواعد والضوابط والشروط الصادرة عن مجلس إدارة الهيئة. خبراء تقييم الأخطار أو معاينة وتقدير الأضرار$q868$, '2024-07-11', 'active' FROM ins_art_law155_133;

WITH ins_art_law155_134 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 134, $q869$الفصل الثامن: المهن التأمينية$q869$, $q870$لا يجوز لأى شخص من الأشخاص الطبيعيين مزاولة مهنة تقييم الأخطار أو معاينة وتقدير الأضرار إلا بعد قيد اسمه في السجل المعد لذلك بالهيئة. وعلى طالب القيد فى هذا السجل أن يحدد فرعين على الأكثر من فروع تأمينات الممتلكات أو المسئوليات التي نص عليها بالمادة ) (٢من هذا القانون لممارسة تخصصه المهني سواء فى مجال تقييم الأخطار أو معاينة وتقدير الأضرار. ويتم القيد وفق ًا للشروط والقواعد والإجراءات التي يضعها مجلس إدارة الهيئة.$q870$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q870$لا يجوز لأى شخص من الأشخاص الطبيعيين مزاولة مهنة تقييم الأخطار أو معاينة وتقدير الأضرار إلا بعد قيد اسمه في السجل المعد لذلك بالهيئة. وعلى طالب القيد فى هذا السجل أن يحدد فرعين على الأكثر من فروع تأمينات الممتلكات أو المسئوليات التي نص عليها بالمادة ) (٢من هذا القانون لممارسة تخصصه المهني سواء فى مجال تقييم الأخطار أو معاينة وتقدير الأضرار. ويتم القيد وفق ًا للشروط والقواعد والإجراءات التي يضعها مجلس إدارة الهيئة.$q870$, '2024-07-11', 'active' FROM ins_art_law155_134;

WITH ins_art_law155_135 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 135, $q871$الفصل الثامن: المهن التأمينية$q871$, $q872$يقدم طلب القيد أو التجديد فى سجل خبراء تقييم الأخطار أو معاينة وتقدير الأضرار وفق ًا للشروط والأوضاع التي يحددها مجلس إدارة الهيئة،ويسرى القيد لمدة خمس سنوات قابلة للتجديد،ويتعين أن يتم اتخاذ إجراءات تجديد القيد خلال ثلاثة الأشهر الأخيرة على الأقل من الموعد المذكور. ويؤدى طالب القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز عشرة آلاف جنيه للشخص الطبيعي،يسدد وفق ًا لطرق السداد المقررة قانون ًا.$q872$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q872$يقدم طلب القيد أو التجديد فى سجل خبراء تقييم الأخطار أو معاينة وتقدير الأضرار وفق ًا للشروط والأوضاع التي يحددها مجلس إدارة الهيئة،ويسرى القيد لمدة خمس سنوات قابلة للتجديد،ويتعين أن يتم اتخاذ إجراءات تجديد القيد خلال ثلاثة الأشهر الأخيرة على الأقل من الموعد المذكور. ويؤدى طالب القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز عشرة آلاف جنيه للشخص الطبيعي،يسدد وفق ًا لطرق السداد المقررة قانون ًا.$q872$, '2024-07-11', 'active' FROM ins_art_law155_135;

WITH ins_art_law155_136 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 136, $q873$الفصل الثامن: المهن التأمينية$q873$, $q874$يجوز للهيئة الترخيص بمزاولة أعمال خبراء تقييم الأخطار أو معاينة وتقدير الأضرار من خلال شركات تؤسس لهذا الغرض وتقيد بالسجل المعد لذلك بالهيئة وذلك وفق ًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة.
ويشترط للقيد فى السجل المشار إليه فى الفقرة الأولى من هذه المادة ضرورة توافر الآتى:
-١ ألا يقل رأسمالها المصدر والمدفوع بالكامل عن المبلغ الذي يحدده مجلس إدارة الهيئة بما لا يقل عن ثلاثة ملايين جنيه نقدا أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى.
-٢ التقدم بطلب للهيئة للتسجيل والترخيص للشركة بمزاولة نشاطها مصحوبا بدراسة الجدوى وعقد تأسيس الشركة ونظامها الأساسي والسجل التجاري.
-٣ أن يكون القائم بالإدارة التنفيذية للشركة من بين المقيدين بسجل خبراء تقييم الأخطار ومعاينة وتقدير الأضرار بالهيئة،وذلك وفق ًا للشروط والمعايير التي يقررها مجلس إدارة الهيئة.
-٤ توافر جميع الشروط المطلوبة لقيد الأشخاص الطبيعيين في سجل الخبراء لدى كل من يزاول أعمال الخبرة في تقييم الأخطار ومعاينة وتقدير الأضرار من المسجلين بالهيئة من خلال الشخص الاعتباري.
-٥ أن يقتصر غرض الشركة على مزاولة أعمال الخبرة في تقييم الأخطار ومعاينة وتقدير الأضرار. وتؤدى الشركة طالبة القيد أو التجديد رس ما يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه،يسدد وفق ًا لطرق السداد المقررة قانون ًا. وفى حالة قيام مانع لدى العضو القائم بالإدارة التنفيذية يحول دون مباشرة أعماله، يجوز لمجلس إدارة الشركة أن يكلف مؤقت ًا أحد خبراء تقييم الأخطار أو تقدير الأضرار من المقيدين بسجلات الهيئة بتولى مهام القائم بالإدارة التنفيذية لحين تعيين آخر مكانه أو زوال المانع،شريطة أن تتوافر لديه ذات الشروط والمعايير التي تصدر عن مجلس إدارة الهيئة.$q874$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
