)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q880$لا يجوز لأى من الأشخاص الطبيعيين مزاولة أعمال الوساطة في التأمين في جمهورية مصر العربية إلا بعد قيد اسمه فى السجل المعد لذلك بالهيئة. ويتم القيد وفق ًا للشروط والقواعد والإجراءات التي يصدر بها قرار من مجلس إدارة الهيئة. ولا يجوز مزاولة أعمال الوساطة في إعادة التأمين في جمهورية مصر العربية إلا من خلال أشخاص اعتبارية تؤسس لهذا الغرض وفق ًا لأحكام هذا القانون والقرارات الصادرة تنفيذ ًا له على أن يقوم بمباشرة تلك الأعمال ممثلو الشخص الاعتباري من المقيدة أسماؤهم في السجل المعد لذلك بالهيئة.$q880$, '2024-07-11', 'active' FROM ins_art_law155_139;

WITH ins_art_law155_140 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 140, $q881$الفصل الثامن: المهن التأمينية$q881$, $q882$يسرى القيد في سجل وسطاء التأمين وإعادة التأمين للأشخاص الطبيعيين لمدة خمس سنوات قابلة للتجديد وفق ًا للشروط والأوضاع التي يصدر بها قرار عن مجلس إدارة الهيئة،ويتعين أن يتم اتخاذ إجراءات التجديد قبل نهاية هذه المدة بثلاثة أشهر على الأقل. ويؤدى طالب القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز عشرة آلاف جنيه للشخص الطبيعى،يسدد وفق ًا لطرق السداد المقررة قانون ًا.$q882$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q882$يسرى القيد في سجل وسطاء التأمين وإعادة التأمين للأشخاص الطبيعيين لمدة خمس سنوات قابلة للتجديد وفق ًا للشروط والأوضاع التي يصدر بها قرار عن مجلس إدارة الهيئة،ويتعين أن يتم اتخاذ إجراءات التجديد قبل نهاية هذه المدة بثلاثة أشهر على الأقل. ويؤدى طالب القيد أو التجديد رسما يحدده مجلس إدارة الهيئة بما لا يجاوز عشرة آلاف جنيه للشخص الطبيعى،يسدد وفق ًا لطرق السداد المقررة قانون ًا.$q882$, '2024-07-11', 'active' FROM ins_art_law155_140;

WITH ins_art_law155_141 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 141, $q883$الفصل الثامن: المهن التأمينية$q883$, $q884$مع عدم الإخلال بحكم المادة ) (١٣٩من هذا القانون يجوز للهيئة الترخيص بمزاولة أعمال وساطة التأمين أو إعادة التأمين من خلال شركات تؤسس لهذا الغرض وتقيد بالسجل المعد لذلك بالهيئة،وذلك وفق ًا للقواعد والإجراءات التي يصدرها مجلس إدارة الهيئة. ويشترط للقيد فى السجل المشار إليه فى الفقرة الأولى من هذه المادة ما يلى:
-١ ألا يقل رأسمالها المصدر والمدفوع بالكامل عن المبلغ الذي يحدده مجلس إدارة الهيئة بما لا يقل عن خمسة ملايين جنيه نقدا،أو ما يعادلها بالعملات الأجنبية الحرة التي يقبلها البنك المركزى المصرى.
-٢ التقدم بطلب للهيئة للتسجيل والترخيص للشركة بمزاولة نشاطها مصحوبا بدراسة الجدوى وعقد تأسيس الشركة ونظامها الأساسي والسجل التجاري.
-٣ أن يكون القائم بالإدارة التنفيذية للشركة من بين المقيدين بسجل وسطاء التأمين أو إعادة التأمين،بحسب الأحوال،وذلك وفق ًا للشروط والمعايير التي يقررها مجلس إدارة الهيئة.
-٤ توافر جميع الشروط المطلوبة لقيد الأشخاص الطبيعيين فى سجل الوسطاء لدى كل من يزاول أعمال الوساطة في التأمين أو إعادة التأمين من المسجلين بالهيئة من خلال الشخص الاعتباري.
-٥ أن يقتصر غرض الشركة على مزاولة أعمال الوساطة فى التأمين أو إعادة التأمين. وتؤدى الشركة طالبة القيد أو التجديد رس ما يحدده مجلس إدارة الهيئة بما لا يجاوز خمسين ألف جنيه،يسدد وفق ًا لطرق السداد المقررة قانون ًا.
وفى حالة قيام مانع لدى العضو القائم بالإدارة التنفيذية يحول دون مباشرة أعماله،يجوز لمجلس إدارة الشركة أن يكلف مؤقت ًا أحد وسطاء التأمين أو إعادة التأمين،بحسب الأحوال،من المقيدين بسجلات الهيئة بتولى مهام القائم بالإدارة التنفيذية لحين تعيين آخر مكانه أو زوال المانع،شريطة أن تتوافر لديه ذات الشروط والمعايير التي تصدر عن مجلس إدارة الهيئة.$q884$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
