WITH ins_art_law155_142 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 142, $q885$الفصل الثامن: المهن التأمينية$q885$, $q886$يتم قيد الخبير أو إعادة قيده أو تجديده أو شطبه الاختيارى أو لعدم التجديد في الموعد الوارد بهذا القانون بقرار من رئيس مجلس إدارة الهيئة. ويتم وقف القيد لمدة لا تجاوز ثلاث سنوات أو شطب قيد الوسيط بقرار من مجلس إدارة الهيئة في أي من الحالات التالية:
-١ فقد أحد شروط القيد.
-٢ إذا ثبت أنه قدم أية بيانات جوهرية غير صحيحة مطلوبة وفق ًا لأحكام هذا القانون نتيجة تعمد أو خطأ جسيم.
-٣ عدم الالتزام بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة والتي يصدر بها قرار عن مجلس إدارة الهيئة.
-٤ إذا ثبت أنه قام بأعمال مخالفة للقوانين أو اللوائح المتعلقة بمهنته أو تنطوي على غش أو خطأ جسيم. وفي الحالات الثلاث الأخيرة يجب إجراء تحقيق من خلال الهيئة.$q886$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q886$يتم قيد الخبير أو إعادة قيده أو تجديده أو شطبه الاختيارى أو لعدم التجديد في الموعد الوارد بهذا القانون بقرار من رئيس مجلس إدارة الهيئة. ويتم وقف القيد لمدة لا تجاوز ثلاث سنوات أو شطب قيد الوسيط بقرار من مجلس إدارة الهيئة في أي من الحالات التالية:
-١ فقد أحد شروط القيد.
-٢ إذا ثبت أنه قدم أية بيانات جوهرية غير صحيحة مطلوبة وفق ًا لأحكام هذا القانون نتيجة تعمد أو خطأ جسيم.
-٣ عدم الالتزام بالقواعد والمعايير المهنية اللازمة لمزاولة المهنة والتي يصدر بها قرار عن مجلس إدارة الهيئة.
