INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q902$يصدر عن مجلس إدارة الهيئة قواعد ومعايير ممارسة تلك المهن وفق ًا لنوع النشاط أو التصنيف الصادر عن الهيئة.$q902$, '2024-07-11', 'active' FROM ins_art_law155_150;

WITH ins_art_law155_151 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 151, $q903$الباب الثاني: شركات قطاع التأمين  ،والخدمات المرتبطة بها  ،والرقابة عليها$q903$, $q904$تختص الهيئة،دون غيرها،بالإشراف والرقابة على نشاط التأمين وإعادة التأمين والخدمات والمهن والأنشطة المرتبطة بهما،ولها فى سبيل ذلك على وجه الخصوص:
-١ الإشراف والرقابة على الأشخاص الطبيعية والاعتبارية التي تمارس نشاط التأمين والمهن والأنشطة المرتبطة به والاتحادات والأجهزة المعاونة ومكاتب التمثيل.
-٢ إصدار القواعد والقرارات التنفيذية المنظمة لأنشطة المخاطبين بأحكام هذا القانون،ومن بينها القواعد المنظمة لمنح التراخيص والتجديد والإلغاء والشطب وإعادة القيد وذلك فى ضوء القواعد والإجراءات والمعايير،ومن بينها معايير الملاءة المالية والتصنيف الائتمانى،التي يصدرها مجلس إدارة الهيئة.
-٣ وضع قواعد ومتطلبات الحوكمة،والإفصاحات المطلوبة وتوقيتاتها، ووضع قواعد ومعايير إلزام شركات التأمين بالحصول على تصنيف ائتماني من إحدى جهات التصنيف المقبولة من الهيئة.
-٤ وضع القواعد والمعايير اللازمة لممارسة نشاط التأمين والأنشطة المرتبطة به، ومنها أساليب تقييم وإدارة المخاطر وقواعد الملاءة المالية.
-٥ إصدار ضوابط فتح ونقل وغلق الفروع.
-٦ إصدار الضوابط التفصيلية لمكافحة غسل الأموال وتمويل الإرهاب في مجال التأمين وإعادة التأمين وما يرتبط به من أنشطة وخدمات،تتضمن الالتزام بالضوابط الصادرة من وحدة مكافحة غسل الأموال وتمويل الإرهاب وبعد التنسيق مع الجهات المعنية.
-٧ وضع الضوابط اللازمة لحماية المتعاملين،على أن تكون ملزمة لجميع الجهات والأشخاص الخاضعين لأحكام هذا القانون.
-٨ وضع قواعد وضوابط التحول الرقمى بالقطاع،بما فيها استخدام وسائل تكنولوجيا المعلومات في مجال انعقاد الجمعيات العامة ومجالس الإدارة والتصويت على القرارات الصادرة عنهما.
-٩ وضع القواعد المتعلقة بالإعلان عن الخدمات والمنتجات التأمينية وما يترتب على الإخلال بالالتزامات التي تنشئها.
-١٠ وضع قواعد وضوابط استثمار أموال شركات التأمين وإعادة التأمين وصناديق التأمين.
-١١ تنظيم اعتماد نماذج وشروط وثائق التأمين.
-١٢ فحص شكاوى المتعاملين مع الأشخاص الطبيعية والاعتبارية التي تمارس نشاط التأمين والمهن والخدمات المرتبطة به والفصل فيها وفق ًا للضوابط والقواعد التي يضعها مجلس إدارة الهيئة.
-١٣ اتخاذ ما تراه من إجراءات فى حالة حدوث تعثر مالى لأى من الجهات الخاضعة لأحكام هذا القانون،وذلك طبق ًا للشروط والقواعد التي يحددها مجلس إدارة الهيئة.
-١٤ إعداد ونشر البيانات الإحصائية والتقارير والدراسات عن نشاط سوق التأمين ووحداته.
-١٥ اقتراح المخاطر التي يكون التأمين فيها إلزاميا.
-١٦ المساهمة فى تعزيز مفهوم الشمول المالى والعمل على توسيع قاعدة المستفيدين من التأمين.
-١٧ المشاركة في تنمية الوعى التأمينى ورفع مهارات العاملين في نشاط التأمين والأنشطة المرتبطة به.
-١٨ وضع قواعد المشاركة في نظام الاستعلام الائتماني في مجال التأمين.
-١٩ توثيق روابط التعاون والتكامل مع هيئات الإشراف والرقابة على التأمين على المستويين الإقليمي والدولي.
-٢٠ دعم الدراسات التأمينية والمساهمة فى تمويلها لخدمة سوق التأمين.$q904$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
