WITH ins_art_law155_153 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 153, $q907$الباب الثاني: شركات قطاع التأمين  ،والخدمات المرتبطة بها  ،والرقابة عليها$q907$, $q908$يلتزم المخاطبون بأحكام هذا القانون كافة بالمحافظة على السرية التامة لبيانات عملائهم،وعدم إفشاء أى معلومات عنهم أو عن معاملاتهم إلى الغير دون موافقتهم الكتابية المسبقة وفى حدود هذه الموافقة،وذلك باستثناء الحالات التي يلزم فيها تقديم معلومات محددة وفق ًا لما تفرضه القوانين لكل من الهيئة أو الجهات القضائية أو الجهات التأمينية أو شركات التصنيف أو الاستعلام الائتمانى،وعلى شركات التأمين أن تتخذ الإجراءات التي تكفل الالتزام بأحكام هذه المادة.$q908$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q908$يلتزم المخاطبون بأحكام هذا القانون كافة بالمحافظة على السرية التامة لبيانات عملائهم،وعدم إفشاء أى معلومات عنهم أو عن معاملاتهم إلى الغير دون موافقتهم الكتابية المسبقة وفى حدود هذه الموافقة،وذلك باستثناء الحالات التي يلزم فيها تقديم معلومات محددة وفق ًا لما تفرضه القوانين لكل من الهيئة أو الجهات القضائية أو الجهات التأمينية أو شركات التصنيف أو الاستعلام الائتمانى،وعلى شركات التأمين أن تتخذ الإجراءات التي تكفل الالتزام بأحكام هذه المادة.$q908$, '2024-07-11', 'active' FROM ins_art_law155_153;

WITH ins_art_law155_154 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 154, $q909$الباب الثاني: شركات قطاع التأمين  ،والخدمات المرتبطة بها  ،والرقابة عليها$q909$, $q910$على المخاطبين بأحكام هذا القانون كافة أن يثبتوا فيما يصدر عنهم من الأوراق أو المستندات أو الوثائق الرقمية اسم وشعار الجهة ورقم وتاريخ الترخيص الصادر لها من الهيئة بمزاولة النشاط.$q910$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q910$على المخاطبين بأحكام هذا القانون كافة أن يثبتوا فيما يصدر عنهم من الأوراق أو المستندات أو الوثائق الرقمية اسم وشعار الجهة ورقم وتاريخ الترخيص الصادر لها من الهيئة بمزاولة النشاط.$q910$, '2024-07-11', 'active' FROM ins_art_law155_154;

WITH ins_art_law155_155 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 155, $q911$الباب الثاني: شركات قطاع التأمين  ،والخدمات المرتبطة بها  ،والرقابة عليها — الفصل الثاني: التأسيس والترخيص ونقل الملكية$q911$, $q912$يشترط فيمن يؤسس شركة من الشركات الخاضعة لأحكام هذا القانون،توافر الشروط التي يضعها مجلس إدارة الهيئة،على أن تتضمن على وجه الخصوص: بالنسبة للأشخاص الطبيعيين:
-١ ألا يكون قد سبق الحكم عليه أو على أحد مؤسسى الشركة أو مديريها أو أحد أعضاء مجلس الإدارة خلال الخمس سنوات السابقة على تقديم طلب التأسيس، بعقوبة جناية أو بعقوبة جنحة في جريمة ماسة بالشرف أو الأمانة أو بعقوبة سالبة للحرية في إحدى الجرائم المنصوص عليها في قوانين الشركات أو التجارة أو القوانين المنظمة للأنشطة المالية غير المصرفية لأسباب تتعلق بنشاط الشركة،أو حكم بإشهار إفلاسه ما لم يكن قدر رد إليه اعتباره.
-٢ ألا يقوم به عارض من عوارض الأهلية.
-٣ أن يتوافر لديه النزاهة وحسن السمعة.
-٤ أن يكون متمتعا بحقوقه المدنية كاملة.
وبالنسبة للأشخاص الاعتباريين:
-١ وضوح هيكل الملكية بما يكفل التعرف على المستفيد النهائي والتأكد من مشروعية مصدر الأموال لطالب التأسيس وأطرافه المرتبطة.
-٢ توافر الملاءة المالية اللازمة لدى طالب التأسيس لدعم أعمال الشركة أو لزيادة رأسمالها إذا دعت الحاجة لذلك.
-٣ إذا كان الطالب شركة أو مؤسسة مالية أجنبية خاضعة لإشراف ورقابة جهة أجنبية مناظرة مختصة في الدولة التي يقع فيها مقرها الرئيسي،أن توافق تلك السلطة لها على العمل في جمهورية مصر العربية،وأن تطبق مبدأ الرقابة المجمعة.$q912$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q912$يشترط فيمن يؤسس شركة من الشركات الخاضعة لأحكام هذا القانون،توافر الشروط التي يضعها مجلس إدارة الهيئة،على أن تتضمن على وجه الخصوص: بالنسبة للأشخاص الطبيعيين:
-١ ألا يكون قد سبق الحكم عليه أو على أحد مؤسسى الشركة أو مديريها أو أحد أعضاء مجلس الإدارة خلال الخمس سنوات السابقة على تقديم طلب التأسيس، بعقوبة جناية أو بعقوبة جنحة في جريمة ماسة بالشرف أو الأمانة أو بعقوبة سالبة للحرية في إحدى الجرائم المنصوص عليها في قوانين الشركات أو التجارة أو القوانين المنظمة للأنشطة المالية غير المصرفية لأسباب تتعلق بنشاط الشركة،أو حكم بإشهار إفلاسه ما لم يكن قدر رد إليه اعتباره.
-٢ ألا يقوم به عارض من عوارض الأهلية.
-٣ أن يتوافر لديه النزاهة وحسن السمعة.
-٤ أن يكون متمتعا بحقوقه المدنية كاملة.
وبالنسبة للأشخاص الاعتباريين:
-١ وضوح هيكل الملكية بما يكفل التعرف على المستفيد النهائي والتأكد من مشروعية مصدر الأموال لطالب التأسيس وأطرافه المرتبطة.
-٢ توافر الملاءة المالية اللازمة لدى طالب التأسيس لدعم أعمال الشركة أو لزيادة رأسمالها إذا دعت الحاجة لذلك.
-٣ إذا كان الطالب شركة أو مؤسسة مالية أجنبية خاضعة لإشراف ورقابة جهة أجنبية مناظرة مختصة في الدولة التي يقع فيها مقرها الرئيسي،أن توافق تلك السلطة لها على العمل في جمهورية مصر العربية،وأن تطبق مبدأ الرقابة المجمعة.$q912$, '2024-07-11', 'active' FROM ins_art_law155_155;

WITH ins_art_law155_156 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 156, $q913$الباب الثاني: شركات قطاع التأمين  ،والخدمات المرتبطة بها  ،والرقابة عليها — الفصل الثاني: التأسيس والترخيص ونقل الملكية$q913$, $q914$تقدم طلبات تأسيس الشركات الواردة بأحكام هذا القانون إلى الهيئة على النموذج الذي تعده الهيئة مرفق ًا بها الأوراق التي تحددها الهيئة. وتعد الهيئة سجلا ً تدون به طلبات التأسيس وفق ًا لتاريخ ورود كل منها،ويكون لكل طلب ملف خاص ورقى أو إلكترونى تودع فيه أوراق التأسيس وكل ما يتعلق بذلك من إجراءات. ويضع مجلس إدارة الهيئة إجراءات وأوضاع تأسيس تلك الشركات والتي من بينها تشكيل لجنة تضم عناصر فنية وقانونية ومالية لدراسة طلبات التأسيس على ضوء المستندات المقدمة،ومنها:
-١ دراسة الجدوى الفنية والاقتصادية للشركة وأغراضها وفروع التأمين المزمع القيام بمزاولتها،والبيانات الإضافية اللازمة لدراسة الطلب.
-٢ سداد مبلغ يحدده مجلس إدارة الهيئة بما لا يجاوز مائتين وخمسين ألف جنيه مقابل مصروفات فحص الطلب بالنسبة لشركات التأمين أو إعادة التأمين،وبما لا يجاوز مائة ألف جنيه لغيرها من الشركات،ويتم السداد وفق ًا للطرق المقررة قانون ًا. وللهيئة أن ترفض طلب التأسيس أو إضافة الفرع التأميني أو النشاط بناء على دراستها في ضوء الآتي:
-١ مدى حاجة السوق إلى شركة جديدة.
-٢ مدى مساهمة الشركة فى تلبية احتياجات السوق،سيما من خلال طرح منتجات تأمين جديدة أو التعديل على المنتجات القائمة أو إضافة آليات تسويق غير تقليدية أو التوسع في مناطق جديدة.
- ٣هيكل الملكية لمؤسسى الشركة وخبراتهم وملاءتهم المالية وفق ًا للضوابط والمعايير التي يضعها مجلس إدارة الهيئة. - ٤عدم اقتصار غرض الشركة على أحد الأنشطة التأمينية أو الخدمات أو المهن بحسب الأحوال،الواردة بأحكام هذا القانون. - ٥عدم نص النظام الأساسي للشركة على وجوب استخدام أسلوب التصويت التراكمي في انتخاب أعضاء مجلس الإدارة.$q914$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $q914$تقدم طلبات تأسيس الشركات الواردة بأحكام هذا القانون إلى الهيئة على النموذج الذي تعده الهيئة مرفق ًا بها الأوراق التي تحددها الهيئة. وتعد الهيئة سجلا ً تدون به طلبات التأسيس وفق ًا لتاريخ ورود كل منها،ويكون لكل طلب ملف خاص ورقى أو إلكترونى تودع فيه أوراق التأسيس وكل ما يتعلق بذلك من إجراءات. ويضع مجلس إدارة الهيئة إجراءات وأوضاع تأسيس تلك الشركات والتي من بينها تشكيل لجنة تضم عناصر فنية وقانونية ومالية لدراسة طلبات التأسيس على ضوء المستندات المقدمة،ومنها:
