WITH ins_art_law155_224 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 224, $q1049$الباب الثالث: تسوية المنازعات والعقوبات$q1049$, $q1050$تسرى أحكام المادة السادسة عشرة من قانون تنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية رقم ۱۰لسنة ۲۰۰۹على الجرائم التى ترتكب بالمخالفة لأحكام هذا القانون والقرارات الصادرة نفاذ ًا له.
جدول الرسوم الملحق بالقانون الرسم الإجراءات المقرر جنيه - ١يحصل مبلغ ۱۰۰جنيه من المؤمن لهم نظير اطلاعهم على بيانات وثائقهم، أو حصولهم على نسخة إضافية منها بناء على طلبهم. - ٢تكون رسوم الاطلاع واستخراج الصور أو الشهادات أو المستخرجات بالهيئة كما يلى: ) أ ( الاطلاع على الأوراق والبيانات: ٥٠ عن كل شركة من الشركات الخاضعة للقانون أو اتحاد............................... )ب( طلب صورة أو شهادات أو مستخرجات من الأوراق والبيانات الواجب تقديمها طبق ًا للقانون أو من القرارات الصادرة تنفيذ ًا له عن الصفحة الواحدة.................. )ج( طلب شهادات أو مستخرجات من السجلات المنصوص عليها فى القانون: عن كل شركة من الشركات الخاضعة للقانون....................................... عن كل خبير أو وسيط من الخبراء أو الوسطاء المنصوص عليهم فى المواد )، ٦٠ (٧١، ٦٧، ٦٤من هذا القانون،وذلك بالنسبة لكل شهادة أو مستخرج............. ٥٠ - ٣طلب الترخيص بإجراء السحب بالنسبة لعمليات التأمين على الحياة وتكوين الأموال.
-٤ النشر على الموقع الإلكترونى الذى تحدده الهيئة: ١٥٠ ) أ ( قرار تسجيل شركة التأمين. )ب( قرار تعديل بيانات التسجيل. )ج( القرار الصادر بتحويل وثائق الشركة والتزاماتها إلى شركة أخرى. )د ( ما يحدده مجلس إدارة الهيئة من قرارات أخرى واجبة النشر.
ولمجلس إدارة الهيئة تعديل الرسوم المقررة فى هذا الجدول بما لا يجاوز عشر أمثالها.
طبعت بالهيئة العامة لشئون المطابع الأميرية رئيس مجلس الإدارة   رقم الإيداع بدار الكتب ٦٥لسنة ٢٠٢٤ ٥٥٩ - ٢٠٢٤/٧/١٥ - ٢٠٢٤/٢٥٠٣٢$q1050$
  FROM laws WHERE law_no = 155 AND law_year = 2024
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
